# ----------------------------------------------------------------------------
# source: 01-helpers.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# CORE HELPERS
# ==============================================================================

# Write-Log  lives in 03-ui-log.ps1, Confirm-Action in 05-dialogs.ps1.
# Both are UI-aware and are defined later in the build so they win over any
# earlier definition. Everything below is UI-agnostic.

function Ensure-WingetInstalled {
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        Write-Log "Winget not found. Installing Winget..." "Warn"
        $bundlePath = Join-Path $DataTemp "winget.msixbundle"
        Invoke-WebRequest -Uri "https://aka.ms/getwinget" -OutFile $bundlePath
        Add-AppxPackage -Path $bundlePath
    }

    # Keep winget and its sources fresh. Their real output is streamed line by
    # line instead of discarded: these are quick, already in memory (no
    # process plumbing needed), and silent runs hide verification failures.
    try {
        Write-Log "Refreshing winget sources..." "Info"
        $refreshLines = @(winget source update --disable-interactivity 2>&1 | ForEach-Object { "$_" })
        foreach ($line in $refreshLines) {
            if ($line -and $line.Trim()) { Write-Log $line.TrimEnd() "Info" }
        }
    }
    catch {
        Write-Log "Winget source refresh failed: $($_.Exception.Message)" "Warn"
    }

    try {
        Write-Log "Checking winget client updates..." "Info"
        $upgradeLines = @(winget upgrade --id Microsoft.DesktopAppInstaller --exact --source winget --accept-source-agreements --accept-package-agreements --disable-interactivity 2>&1 | ForEach-Object { "$_" })
        foreach ($line in $upgradeLines) {
            if ($line -and $line.Trim()) { Write-Log $line.TrimEnd() "Info" }
        }
    }
    catch {
        Write-Log "Winget client upgrade skipped/failed: $($_.Exception.Message)" "Warn"
    }
}

function Test-WingetPackageInstalled([string]$Id) {
    Ensure-WingetInstalled
    $listOutput = winget list --id $Id --exact --source winget --accept-source-agreements 2>$null | Out-String
    return $listOutput -match [regex]::Escape($Id)
}

function Install-WingetPackage([string]$Id) {
    if (Test-WingetPackageInstalled -Id $Id) {
        Write-Log "Already installed: $Id"
        return
    }

    Write-Log "Installing package: $Id"
    Invoke-ExternalCommand -FilePath "winget.exe" -Arguments @(
        "install", "--id", $Id, "--exact", "-s", "winget",
        "--accept-package-agreements", "--accept-source-agreements", "--disable-interactivity"
    ) | Out-Null
}

function Get-InstalledExecutablePath {
    param(
        [Parameter(Mandatory = $true)][string[]]$ExecutableNames,
        [Parameter()][string[]]$CandidatePaths = @()
    )

    foreach ($path in $CandidatePaths | Where-Object { $_ }) {
        if (Test-Path $path) { return $path }
    }

    foreach ($name in $ExecutableNames | Where-Object { $_ }) {
        $command = Get-Command $name -ErrorAction SilentlyContinue
        if ($command -and $command.Source -and (Test-Path $command.Source)) {
            return $command.Source
        }
    }

    $searchRoots = @()
    if ($env:LOCALAPPDATA) {
        $searchRoots += Join-Path $env:LOCALAPPDATA "Microsoft\WinGet\Packages"
        $searchRoots += Join-Path $env:LOCALAPPDATA "Programs"
    }
    if ($env:ProgramFiles) {
        $searchRoots += Join-Path $env:ProgramFiles "WinGet\Packages"
        $searchRoots += $env:ProgramFiles
    }
    if (${env:ProgramFiles(x86)}) {
        $searchRoots += ${env:ProgramFiles(x86)}
    }
    $searchRoots = $searchRoots | Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique

    foreach ($root in $searchRoots) {
        foreach ($name in $ExecutableNames | Where-Object { $_ }) {
            $match = Get-ChildItem -Path $root -Filter $name -File -Recurse -ErrorAction SilentlyContinue |
                Select-Object -First 1
            if ($match) { return $match.FullName }
        }
    }

    return $null
}

function Install-And-LaunchWingetPackage {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        [Parameter(Mandatory = $true)][string[]]$ExecutableNames,
        [Parameter()][string[]]$CandidatePaths = @()
    )

    Install-WingetPackage -Id $Id

    $exePath = Get-InstalledExecutablePath -ExecutableNames $ExecutableNames -CandidatePaths $CandidatePaths
    if (-not $exePath) {
        throw "Installed package '$Id', but could not locate executable: $($ExecutableNames -join ', ')"
    }

    Write-Log "Launching $exePath" "Info"
    Start-Process -FilePath $exePath
}

function Test-NetworkConnectivity {
    try {
        return [bool](Test-Connection -ComputerName "1.1.1.1" -Count 1 -Quiet -ErrorAction Stop)
    }
    catch {
        return $false
    }
}

function Get-WindowsBuildNumber {
    try {
        return [int](Get-ItemPropertyValue -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion" -Name "CurrentBuild")
    }
    catch {
        return 0
    }
}

function Test-IsWindows11 {
    if ($SysInfo.OS -match "Windows 11") {
        return $true
    }

    return (Get-WindowsBuildNumber) -ge 22000
}

function Get-SpotifyExecutablePath {
    $candidates = @(
        "$env:APPDATA\Spotify\Spotify.exe",
        "$env:LOCALAPPDATA\Microsoft\WindowsApps\Spotify.exe"
    )

    $msixRoot = Join-Path $env:LOCALAPPDATA "Microsoft\WindowsApps"
    if (Test-Path $msixRoot) {
        $msixSpotify = Get-ChildItem -Path $msixRoot -Filter "Spotify*.exe" -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match "spotify" } |
            Select-Object -First 1
        if ($msixSpotify) { $candidates += $msixSpotify.FullName }
    }

    foreach ($p in $candidates | Select-Object -Unique) {
        if (Test-Path $p) { return $p }
    }
    return $null
}

# Lines streamed per poll tick at most: a pathological burst is paced across
# ticks instead of freezing the UI behind thousands of synchronous log writes.
$FmkStreamPollLines = 500

function Invoke-ExternalCommand {
    <#
        Runs an external tool and STREAMS its real output into the log while it
        runs -- stdout as Info, stderr as Warn -- instead of replaying it after
        exit. The console host is hidden for the life of the GUI, so without
        this the output of winget/sfc/DISM would go to a window nobody can see.

        Mechanism, and why not .NET output events: event callbacks would run on
        threadpool threads inside PowerShell scriptblocks bound to the very
        runspace that is blocked waiting -- a deadlock. Instead this thread
        polls both pipes itself with BeginRead plus a 200ms wait handle (pure
        .NET, no scriptblock callbacks, no shared locks), and each new segment
        is logged immediately, so the Output panel updates during long
        installs. Per-stream order is exact; across the two independent
        streams the order is arrival order, which the OS does not guarantee --
        and is not claimed to be reconstructable.

        Decoding is UTF-8 unless the stream proves otherwise: a BOM or a
        NUL-interleaved prefix (how UTF-16LE console output such as sfc.exe
        arrives) switches that stream to a UTF-16 decoder for the rest of the
        run. Anything undecodable degrades to replacement characters rather
        than throwing mid-stream. Carriage-return progress rewrites are split
        into segments so they cannot arrive as one enormous line. Leading
        indentation is preserved; only trailing whitespace is trimmed and empty
        segments are skipped. Success or failure comes from the exit code
        alone -- stderr text is never itself a failure.
    #>
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [Parameter()][string[]]$Arguments = @()
    )

    Write-Log "> $FilePath $($Arguments -join ' ')" "Info"

    # Quote exactly like an argv array would: Start-Process used to take the
    # array directly, and a naive join would corrupt paths containing spaces.
    $escapedArgs = foreach ($a in @($Arguments)) {
        if ($null -eq $a -or "$a" -eq '') { continue }
        if ("$a" -match '[\s"]') { '"' + ("$a" -replace '"', '\"') + '"' }
        else { "$a" }
    }

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $FilePath
    $psi.Arguments = ($escapedArgs -join ' ')
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true

    $proc = $null
    try {
        $proc = [System.Diagnostics.Process]::Start($psi)
    }
    catch {
        throw "Could not start '$FilePath': $($_.Exception.Message)"
    }

    # One state block per pipe. BaseStream is read directly -- never the
    # StreamReader wrappers, which would fight over the same pipe. The text
    # decoder is chosen per stream by Read-FmkStreamBytes (UTF-8 unless the
    # bytes prove UTF-16) and then kept for the whole run, so a multibyte or
    # surrogate-split character across two reads still decodes correctly.
    $streams = @(
        @{ Pipe = $proc.StandardOutput.BaseStream; Tag = 'OUT'; LogType = 'Info';
           Enc = $null; Decoder = $null; Lead = (New-Object System.Collections.Generic.List[byte]);
           Buffer = (New-Object byte[] 4096); PendingAsync = $null;
           Fragment = ''; Eof = $false },
        @{ Pipe = $proc.StandardError.BaseStream; Tag = 'ERR'; LogType = 'Warn';
           Enc = $null; Decoder = $null; Lead = (New-Object System.Collections.Generic.List[byte]);
           Buffer = (New-Object byte[] 4096); PendingAsync = $null;
           Fragment = ''; Eof = $false }
    )

    try {
        $openStreams = @($streams | Where-Object { -not $_.Eof })
        while ((-not $proc.HasExited) -or ($openStreams.Count -gt 0)) {
            foreach ($st in $streams) {
                if ($st.Eof) { continue }
                try {
                    if ($null -eq $st.PendingAsync) {
                        $st.PendingAsync = $st.Pipe.BeginRead($st.Buffer, 0, $st.Buffer.Length, $null, $null)
                    }
                    if ($st.PendingAsync.AsyncWaitHandle.WaitOne(200)) {
                        $got = $st.Pipe.EndRead($st.PendingAsync)
                        $st.PendingAsync = $null
                        if ($got -eq 0) { $st.Eof = $true; continue }
                        $text = Read-FmkStreamBytes -State $st -Buffer $st.Buffer -Count $got
                        if ($text -ne '') {
                            Write-FmkStreamText -State $st -Text $text -Final:$false
                        }
                    }
                }
                catch {
                    # A broken pipe ends that stream, not the task. The exit
                    # code below still decides success or failure.
                    $st.Eof = $true
                    $st.PendingAsync = $null
                }
            }
            $openStreams = @($streams | Where-Object { -not $_.Eof })
        }
        foreach ($st in $streams) {
            $tail = Read-FmkStreamBytes -State $st -Buffer (New-Object byte[] 0) -Count 0 -Final
            Write-FmkStreamText -State $st -Text $tail -Final:$true
        }
    }
    catch {
        # Capture must never stick the task: wait out our own child (waiting
        # is correct -- never kill) and let the exit code decide.
        Write-Log "Stream capture degraded, waiting for exit: $($_.Exception.Message)" "Warn"
        try { $proc.WaitForExit() } catch { }
    }

    $exitCode = 0
    try { $exitCode = $proc.ExitCode } catch { $exitCode = 0 }
    try { $proc.Dispose() } catch { }

    if ($exitCode -ne 0) {
        throw "Command failed (exit $exitCode): $FilePath $($Arguments -join ' ')"
    }

    return [pscustomobject]@{
        FilePath  = $FilePath
        Arguments = ($Arguments -join " ")
        ExitCode  = $exitCode
    }
}

function Test-FmkStreamEncoding {
    <#
        Decides a pipe's text encoding from its leading bytes. A BOM decides
        immediately (UTF-16LE, or UTF-8 with its BOM skipped). Otherwise the
        decision waits for at least 4 bytes: NUL-interleaved ASCII-range text
        means UTF-16LE, anything else means UTF-8. Short prefixes stay
        undecided ($null) until more arrive or the stream ends (-Final falls
        back to UTF-8). Pure function, unit tested.
    #>
    param([byte[]]$Lead = @(), [switch]$Final)
    $Lead = @($Lead)
    if ($Lead.Count -ge 2 -and $Lead[0] -eq 0xFF -and $Lead[1] -eq 0xFE) {
        return @{ Enc = 'utf16'; Skip = 2 }
    }
    if ($Lead.Count -ge 3 -and $Lead[0] -eq 0xEF -and $Lead[1] -eq 0xBB -and $Lead[2] -eq 0xBF) {
        return @{ Enc = 'utf8'; Skip = 3 }
    }
    if ($Lead.Count -ge 4) {
        $pairs = [Math]::Floor($Lead.Count / 2)
        $zeroOdd = 0
        $nonZeroEven = 0
        for ($i = 0; $i -lt $pairs; $i++) {
            if ($Lead[$i * 2 + 1] -eq 0) { $zeroOdd++ }
            if ($Lead[$i * 2] -ne 0) { $nonZeroEven++ }
        }
        if ($pairs -ge 2 -and $zeroOdd -eq $pairs -and $nonZeroEven -gt 0) {
            return @{ Enc = 'utf16'; Skip = 0 }
        }
        return @{ Enc = 'utf8'; Skip = 0 }
    }
    if ($Final) { return @{ Enc = 'utf8'; Skip = 0 } }
    return $null
}

function Convert-FmkBytesToText {
    <#
        Decodes bytes with a stateful decoder; never throws. Empty input is a
        legal value (end of stream), not a binding error: $Bytes is therefore
        deliberately NOT a mandatory [byte[]], because PowerShell refuses to
        bind an empty array to a mandatory typed parameter.
    #>
    param($Decoder, $Bytes, [switch]$Flush)
    try {
        $arr = @()
        if ($null -ne $Bytes) { $arr = @($Bytes) }
        $src = New-Object byte[] 0
        if ($arr.Count -gt 0) { $src = [byte[]]$arr }
        if ($src.Length -eq 0 -and -not $Flush) { return '' }
        $chars = New-Object char[] ($src.Length + 1)
        $used = $Decoder.GetChars($src, 0, $src.Length, $chars, 0, [bool]$Flush)
        if ($used -gt 0) { return (-join $chars[0..($used - 1)]) }
        return ''
    }
    catch { return '' }
}

function Read-FmkStreamBytes {
    <#
        Decodes one raw pipe read into text using the stream's sticky decoder,
        choosing it on first evidence via Test-FmkStreamEncoding. Split
        multibyte characters survive because decoder state persists across
        reads; -Final flushes a dangling tail. Returns '' when there is
        nothing decodable yet.
    #>
    param(
        [Parameter(Mandatory)]$State,
        [byte[]]$Buffer,
        [int]$Count,
        [switch]$Final
    )
    if (-not $State.Enc) {
        # Accumulate until decidable. Test-FmkStreamEncoding always decides at
        # 4 bytes, so this buffer stays tiny; nothing is dropped meanwhile.
        for ($i = 0; $i -lt $Count; $i++) { [void]$State.Lead.Add($Buffer[$i]) }
        $leadBytes = @($State.Lead.ToArray())
        $dec = Test-FmkStreamEncoding -Lead $leadBytes -Final:$Final
        if (-not $dec) { return '' }
        $State.Enc = [string]$dec.Enc
        if ($State.Enc -eq 'utf16') {
            $State.Decoder = [System.Text.Encoding]::Unicode.GetDecoder()
        }
        else {
            $State.Decoder = [System.Text.Encoding]::UTF8.GetDecoder()
        }
        $skip = [int]$dec.Skip
        $payload = @()
        if ($skip -lt $leadBytes.Length) { $payload = @($leadBytes[$skip..($leadBytes.Length - 1)]) }
        $State.Lead = (New-Object System.Collections.Generic.List[byte])
        return (Convert-FmkBytesToText -Decoder $State.Decoder -Bytes $payload -Flush:$Final)
    }
    if ($Count -le 0) {
        if ($Final) { return (Convert-FmkBytesToText -Decoder $State.Decoder -Flush:$true) }
        return ''
    }
    return (Convert-FmkBytesToText -Decoder $State.Decoder -Bytes @($Buffer[0..($Count - 1)]) -Flush:$Final)
}

function Get-FmkObservedPercent {
    <#
        Extracts a genuine percentage from real installer output text, e.g.
        "Downloading 42%" or "Progress: 42 %". Returns the LAST percentage on
        the line (later rewrites supersede earlier ones), clamped to 0..100,
        or $null when the line carries no percentage. Pure function: no
        estimation, no timers, no line counting.
    #>
    param([string]$Text)

    if ([string]::IsNullOrEmpty($Text)) { return $null }
    $hits = @([regex]::Matches($Text, '(\d{1,3})\s*%') | ForEach-Object { [int]$_.Groups[1].Value })
    if ($hits.Count -eq 0) { return $null }
    $pct = $hits[$hits.Count - 1]
    if ($pct -lt 0) { $pct = 0 }
    if ($pct -gt 100) { $pct = 100 }
    return $pct
}

function Write-FmkStreamText {
    <#
        Logs newly arrived text from one pipe. Complete segments (split on CR
        and LF, so progress rewrites cannot fuse into one giant line) stream
        immediately; a trailing fragment without a terminator is held back
        until more arrives or the process exits (-Final flushes it).
    #>
    param(
        [Parameter(Mandatory)]$State,
        [string]$Text = '',
        [switch]$Final
    )

    $text = [string]$State.Fragment + $Text
    $State.Fragment = ''
    if ($text -eq '') { return }

    $terminated = $text.EndsWith("`r") -or $text.EndsWith("`n")
    $parts = $text -split "`r`n|`n|`r"
    $complete = $parts
    if (-not $terminated -and -not $Final) {
        $State.Fragment = $parts[$parts.Count - 1]
        if ($parts.Count -gt 1) { $complete = $parts[0..($parts.Count - 2)] }
        else { $complete = @() }
    }

    $shown = 0
    for ($i = 0; $i -lt $complete.Count; $i++) {
        $segment = $complete[$i]
        if ($shown -ge $FmkStreamPollLines) {
            # Burst protection: hold THIS segment and everything after it for
            # the next tick, in order, instead of flooding the UI thread
            # behind one poll. Nothing is dropped.
            $rest = @($complete[$i..($complete.Count - 1)])
            $State.Fragment = (($rest -join "`n") + "`n" + $State.Fragment)
            break
        }
        if ($segment -eq '' -or $segment.Trim() -eq '') { continue }
        Write-Log $segment.TrimEnd() $State.LogType
        $shown++
        # A percentage observed in genuine output feeds the shared bar via the
        # queue/total math (or directly for lone tasks). Lines without one
        # change nothing -- the bar simply stays where measured evidence put it.
        $observed = Get-FmkObservedPercent -Text $segment
        if ($null -ne $observed) { Update-FmkObservedProgress -ItemPercent $observed }
    }
}

# ----------------------------------------------------------------------------
# source: 02-registry.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# MODULE REGISTRY
# ==============================================================================

$Modules = [ordered]@{}
$ModuleMeta = [ordered]@{}
$ModuleResults = New-Object System.Collections.Generic.List[object]

function Register-Module(
    [string]$Key,
    [string]$Label,
    [string]$Description,
    [scriptblock]$Action,
    [string]$Risk = "None",
    [hashtable]$Options = @{}
) {
    $Modules[$Key] = $Action
    $ModuleMeta[$Key] = [ordered]@{
        Key             = $Key
        Label           = $Label
        Description     = $Description
        Risk            = $Risk
        RequiresNetwork = $false
        ConfirmMessage  = $null
        Verify          = $null
        RollbackHint    = ""
        # UI placement. Category drives the sidebar; Group drives the section
        # heading within a page. Both are optional so a module can be registered
        # without appearing in the GUI.
        Category        = "Other"
        Group           = ""
        # Key into $FmkLogos (src/assets/logos.ps1) for the Software grid. A
        # module with no entry -- or no Logo key at all -- still draws, falling
        # back to the label's initials, so this never has to be set.
        Logo            = ""
        # Button caption. "Run" suits a maintenance task; a module that installs
        # something reads better as "Install", and one that uninstalls or opens a
        # page reads better as its own verb.
        ActionLabel     = "Run"
        # Risk metadata. Only set on entries that carry a Low/Medium/High
        # rating; ordinary tools stay Risk="None" with these empty. Kept here
        # (not in UI code) so contributors update ratings without touching UI.
        # RiskReason is the short tooltip line; the Risk* dimensions feed the
        # detailed tooltip and the risk-help dialog. RiskEvidence is a URL or
        # short reference; RiskReviewed is yyyy-MM-dd. Never fabricate audits.
        RiskReason      = ""
        RiskTechnical   = ""
        RiskSource      = ""
        RiskPrivacy     = ""
        RiskLicense     = ""
        RiskPrivileges  = ""
        RiskEvidence    = ""
        RiskReviewed    = ""
    }

    foreach ($k in $Options.Keys) {
        $ModuleMeta[$Key][$k] = $Options[$k]
    }
}

function Get-ModuleMetaValue([string]$ActionKey, [string]$Name, $DefaultValue) {
    if ($ModuleMeta.Contains($ActionKey) -and $ModuleMeta[$ActionKey].Contains($Name) -and $null -ne $ModuleMeta[$ActionKey][$Name]) {
        return $ModuleMeta[$ActionKey][$Name]
    }
    return $DefaultValue
}

function Add-ModuleResult([string]$Module, [string]$Status, [string]$Message, [timespan]$Duration, [string]$RollbackHint = "", [string]$PreviousState = "") {
    $ModuleResults.Add([pscustomobject]@{
            Timestamp     = Get-Date
            Module        = $Module
            Status        = $Status
            DurationSec   = [Math]::Round($Duration.TotalSeconds, 2)
            Message       = $Message
            RollbackHint  = $RollbackHint
            PreviousState = $PreviousState
        })
}

function Export-SessionResults {
    $stamp = Get-Date -Format "yyyyMMdd_HHmmss"
    $resultsPath = Join-Path $DataLogs "FreeMixKit_ModuleResults_$stamp.csv"

    if ($ModuleResults.Count -gt 0) {
        $ModuleResults | Export-Csv -Path $resultsPath -NoTypeInformation -Encoding UTF8
        Write-Log "Module results exported to: $resultsPath" "Success"
    }
    else {
        Write-Log "No module executions to export for this session." "Info"
    }

}

# Last progress record surfaced to the status line, so Write-Progress ticks
# update the status instead of spamming the log. Reset per module run below.
$Script:FmkLastProgress = @{ Activity = ''; Percent = -2 }

function Format-FmkStreamRecord {
    <#
        Classifies one merged-stream record into how the Output panel should
        show it. Pure function: no UI, no logging, safe to unit test.
        Returns @{ Kind; Type; Text; Percent; Activity } where Type is the
        Write-Log color key. Progress records carry no log text at all.
    #>
    param($Record)

    if ($null -eq $Record) { return @{ Kind = 'Empty'; Type = 'Info'; Text = ''; Percent = -1; Activity = '' } }

    if ($Record -is [System.Management.Automation.ErrorRecord]) {
        $detail = ''
        try { $detail = [string]$Record.Exception.Message } catch { }
        if (-not $detail) {
            try { $detail = $Record.ToString() } catch { $detail = 'Unknown error' }
        }
        $category = ''
        try { $category = [string]$Record.CategoryInfo.Category } catch { }
        $text = if ($category) { "ERROR [$category]: $detail" } else { "ERROR: $detail" }
        return @{ Kind = 'Error'; Type = 'Error'; Text = $text; Percent = -1; Activity = '' }
    }

    if ($Record -is [System.Management.Automation.WarningRecord]) {
        return @{ Kind = 'Warning'; Type = 'Warn'; Text = "WARNING: $($Record.Message)"; Percent = -1; Activity = '' }
    }

    if ($Record -is [System.Management.Automation.VerboseRecord]) {
        return @{ Kind = 'Verbose'; Type = 'Info'; Text = "VERBOSE: $($Record.Message)"; Percent = -1; Activity = '' }
    }

    if ($Record -is [System.Management.Automation.DebugRecord]) {
        return @{ Kind = 'Debug'; Type = 'Info'; Text = "DEBUG: $($Record.Message)"; Percent = -1; Activity = '' }
    }

    if ($Record -is [System.Management.Automation.InformationRecord]) {
        $infoText = ''
        try { $infoText = [string]$Record.MessageData } catch { $infoText = $Record.ToString() }
        return @{ Kind = 'Information'; Type = 'Info'; Text = $infoText; Percent = -1; Activity = '' }
    }

    if ($Record -is [System.Management.Automation.ProgressRecord]) {
        $pct = -1
        try { $pct = [int]$Record.PercentComplete } catch { $pct = -1 }
        $activity = ''
        try { $activity = [string]$Record.Activity } catch { }
        return @{ Kind = 'Progress'; Type = 'Info'; Text = ''; Percent = $pct; Activity = $activity }
    }

    # Ordinary success output. Strings pass through untouched; anything else
    # is formatted the way the console would render one object. Trailing
    # whitespace (line breaks, padding) is trimmed, but leading indentation
    # is preserved verbatim.
    $body = ''
    if ($Record -is [string]) { $body = $Record }
    else {
        try { $body = (@($Record) | Out-String) } catch { $body = [string]$Record }
    }
    if ($null -eq $body) { $body = '' }
    $body = ([string]$body).TrimEnd()
    return @{ Kind = 'Output'; Type = 'Info'; Text = $body; Percent = -1; Activity = '' }
}

function Write-FmkStreamRecord {
    <#
        Sends one merged-stream record to the Output panel, preserving the
        stream distinction (errors red, warnings amber, verbose/debug tagged).
        Progress records update the status line instead -- throttled to a new
        activity or a >=5 point move, so a chatty Write-Progress loop cannot
        flood either surface. Reached from the background runspace; both sinks
        marshal to the UI thread through the existing delegates.
    #>
    param($Record)

    $fmt = Format-FmkStreamRecord -Record $Record
    if ($fmt.Kind -eq 'Empty') { return }
    if ($fmt.Kind -eq 'Progress') {
        $last = $Script:FmkLastProgress
        $show = ($fmt.Activity -ne $last.Activity) -or ([Math]::Abs($fmt.Percent - $last.Percent) -ge 5)
        if ($show) {
            $Script:FmkLastProgress = @{ Activity = $fmt.Activity; Percent = $fmt.Percent }
            $statusText = $fmt.Activity
            if ($fmt.Percent -ge 0) { $statusText += " ($($fmt.Percent)%)" }
            if (-not $statusText) { $statusText = 'Working...' }
            Set-FmkStatus -Text $statusText
        }
        return
    }
    if ($fmt.Text -eq '') { return }
    Write-Log $fmt.Text $fmt.Type
}

function Invoke-ModuleAction([string]$ActionKey) {
    if (-not $Modules.Contains($ActionKey)) {
        throw "Unknown action '$ActionKey'."
    }

    $label = Get-ModuleMetaValue -ActionKey $ActionKey -Name "Label" -DefaultValue $ActionKey
    $requiresNetwork = [bool](Get-ModuleMetaValue -ActionKey $ActionKey -Name "RequiresNetwork" -DefaultValue $false)
    $confirmMessage = Get-ModuleMetaValue -ActionKey $ActionKey -Name "ConfirmMessage" -DefaultValue $null
    $verifyBlock = Get-ModuleMetaValue -ActionKey $ActionKey -Name "Verify" -DefaultValue $null
    $rollbackHint = Get-ModuleMetaValue -ActionKey $ActionKey -Name "RollbackHint" -DefaultValue ""

    if ($confirmMessage) {
        if (-not (Confirm-Action $confirmMessage)) {
            return [pscustomobject]@{
                Status        = "Canceled"
                Message       = "Canceled by user"
                Duration      = [timespan]::Zero
                RollbackHint  = $rollbackHint
                PreviousState = ""
            }
        }
    }

    if ($requiresNetwork -and -not (Test-NetworkConnectivity)) {
        throw "Network is required, but connectivity check failed."
    }

    $Script:ModuleExecutionContext = @{}
    $Script:FmkLastProgress = @{ Activity = ''; Percent = -2 }
    $start = Get-Date
    $hadLastExitCode = Test-Path variable:global:LASTEXITCODE
    $oldLastExitCode = if ($hadLastExitCode) { $global:LASTEXITCODE } else { 0 }
    $global:LASTEXITCODE = 0

    try {
        # Merged-stream execution: every record the module emits -- success
        # output, errors, warnings, verbose/debug/information, progress -- is
        # classified and streamed to the Output panel as it happens instead of
        # being discarded. Terminating errors still throw straight through to
        # the catch below, and the constructed result object (not stray output)
        # remains the return value, so the module contract is unchanged.
        & $Modules[$ActionKey] *>&1 | ForEach-Object { Write-FmkStreamRecord -Record $_ }

        $duration = (Get-Date) - $start

        $effectiveExitCode = if (Test-Path variable:global:LASTEXITCODE) { $global:LASTEXITCODE } else { 0 }
        if ($effectiveExitCode -ne 0) {
            throw "Module returned non-zero exit code: $effectiveExitCode"
        }

        if ($verifyBlock) {
            $ok = & $verifyBlock
            if (-not $ok) {
                throw "Post-check failed for module '$label'."
            }
        }

        $previousState = ""
        if ($Script:ModuleExecutionContext.ContainsKey("PreviousState")) {
            $previousState = [string]$Script:ModuleExecutionContext["PreviousState"]
        }

        return [pscustomobject]@{
            Status        = "Success"
            Message       = "Completed"
            Duration      = $duration
            RollbackHint  = $rollbackHint
            PreviousState = $previousState
        }
    }
    finally {
        if ($hadLastExitCode) {
            $global:LASTEXITCODE = $oldLastExitCode
        }
        else {
            Remove-Variable -Scope Global -Name LASTEXITCODE -ErrorAction SilentlyContinue
        }
    }
}

# ----------------------------------------------------------------------------
# source: 03-ui-log.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# LOGGING AND STATUS
# ==============================================================================
# Write-Log keeps its original signature and file-append behaviour, so the ~30
# call sites inside the module bodies work unchanged. The only difference is
# that output also goes to the UI log pane when a window exists.
#
# SCOPE: the UI is reached through delegates built on the UI thread at boot and
# stored on $sync (see New-FmkSyncState). Scriptblocks are never created in a
# background runspace and handed to Dispatcher.Invoke -- a scriptblock carries
# the session state it was created in, so that would re-enter the runspace that
# is currently blocked on the Invoke. Instead the caller parks its arguments on
# $sync, which is thread-safe, and the UI-thread delegate reads them back.
#
# Write-Log is reached from the UI thread *and* from background runspaces, so
# both paths exist and Invoke (not BeginInvoke) keeps log order matching
# execution order. On the UI thread it runs inline.

$FmkLogColorKeys = @{
    Info    = 'FmkFg'
    Success = 'FmkRiskLow'
    Warn    = 'FmkRiskMed'
    Error   = 'FmkRiskHigh'
    # Framework lifecycle chatter (dispatch notices, selection echoes) renders
    # muted gray so it stays structurally distinct from real tool output
    # (white/amber/red) and from result verdicts (green/amber/red).
    Muted   = 'FmkFgMuted'
}

# Bounded so a chatty module cannot grow the document without limit.
$FmkMaxLogLines = 2000

function Invoke-FmkUiAction {
    <#
        Runs one of the UI-thread delegates from wherever we happen to be.
        Returns quietly if the UI is not up yet, so logging during boot and in
        library mode falls through to the console path instead of throwing.
    #>
    param([Parameter(Mandatory)][string]$Name)

    $window = $null
    if ($global:sync) { $window = $global:sync.FmkWindow }
    if (-not $window) { return $false }

    $delegate = $null
    if ($global:sync.ContainsKey($Name)) { $delegate = $global:sync[$Name] }
    if (-not $delegate) { return $false }

    try {
        [void]$window.Dispatcher.Invoke($delegate)
        return $true
    }
    catch {
        # Never let a display failure break the operation being displayed.
        return $false
    }
}

function Add-FmkLogLine {
    <# Appends one colored line. Must run on the UI thread. #>
    param(
        [string]$Text,
        [string]$ColorKey = 'FmkFg'
    )

    # Not [Parameter(Mandatory)]: this is invoked from a no-argument delegate, so
    # a missing value must be a silent no-op rather than an interactive prompt.
    if (-not $Text) { return }

    $box = $global:sync.LogBox
    if (-not $box) { return }

    $para = New-Object System.Windows.Documents.Paragraph
    $para.Margin = New-Object System.Windows.Thickness(0)
    $para.LineHeight = 15

    $brush = $null
    if ($global:sync.FmkWindow -and $global:sync.FmkWindow.Resources.Contains($ColorKey)) {
        $brush = $global:sync.FmkWindow.Resources[$ColorKey]
    }
    if (-not $brush) { $brush = [System.Windows.Media.Brushes]::LightGray }

    $run = New-Object System.Windows.Documents.Run($Text)
    $run.Foreground = $brush
    [void]$para.Inlines.Add($run)
    [void]$box.Document.Blocks.Add($para)

    while ($box.Document.Blocks.Count -gt $FmkMaxLogLines) {
        $box.Document.Blocks.Remove($box.Document.Blocks.FirstBlock)
    }

    $box.ScrollToEnd()
}

function Write-Log($Message, $Type = "Info") {
    # File append first, so a crash mid-log still leaves a record on disk.
    try {
        $tag = $Type.ToUpperInvariant()
        "[{0}] [{1}] {2}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss"), $tag, $Message |
            Add-Content -Path $SessionLogPath -Encoding UTF8 -ErrorAction SilentlyContinue
    }
    catch { }

    $line = "[{0}] {1}" -f (Get-Date).ToString('HH:mm:ss'), $Message
    $colorKey = if ($FmkLogColorKeys.ContainsKey($Type)) { $FmkLogColorKeys[$Type] } else { 'FmkFg' }

    $window = $null
    if ($global:sync -and $global:sync.FmkWindow) { $window = $global:sync.FmkWindow }

    if ($window) {
        $global:sync.PendingLogText = $line
        $global:sync.PendingLogColor = $colorKey
        try {
            [void](Invoke-FmkUiAction -Name 'ActLogFlush')
        }
        finally {
            $global:sync.PendingLogText = $null
            $global:sync.PendingLogColor = $null
        }
    }
    else {
        $consoleColor = switch ($Type) {
            "Success" { "Cyan" }
            "Warn" { "Yellow" }
            "Error" { "Red" }
            default { "White" }
        }
        Write-Host " $line" -ForegroundColor $consoleColor
    }
}

function Set-FmkStatusNow {
    <# Applies $global:sync.PendingStatusText. Must run on the UI thread. #>
    $state = $global:sync
    if (-not $state.StatusText) { return }

    $state.StatusText.Text = $state.PendingStatusText
    if ($state.FmkWindow.Resources.Contains($state.PendingStatusColor)) {
        $state.StatusText.Foreground = $state.FmkWindow.Resources[$state.PendingStatusColor]
    }
}

function Set-FmkStatus {
    <# Updates the status line shown to the right of the progress bar. #>
    param(
        [string]$Text,
        [string]$ColorKey = 'FmkFgMuted'
    )

    if (-not ($global:sync -and $global:sync.FmkWindow -and $global:sync.StatusText)) { return }

    $global:sync.PendingStatusText = $Text
    $global:sync.PendingStatusColor = $ColorKey
    [void](Invoke-FmkUiAction -Name 'ActStatus')
}

function Get-FmkProgressRequest {
    <#
        Normalizes a caller-supplied percentage into a progress request for the
        one shared bar. A finite number is trustworthy determinate progress
        (clamped to 0..100); $null, NaN, infinity, or anything unparseable is
        indeterminate. Percentages are never invented here -- callers only pass
        numbers they actually measured.
    #>
    param($Percent)

    if ($null -eq $Percent) { return @{ Mode = 'Indeterminate'; Value = 0 } }
    try {
        $value = [double]$Percent
        if ([double]::IsNaN($value) -or [double]::IsInfinity($value)) {
            return @{ Mode = 'Indeterminate'; Value = 0 }
        }
        if ($value -lt 0) { $value = 0 }
        if ($value -gt 100) { $value = 100 }
        return @{ Mode = 'Determinate'; Value = $value }
    }
    catch {
        return @{ Mode = 'Indeterminate'; Value = 0 }
    }
}

function Set-FmkProgress {
    <#
        Progress-only update for the shared bar (busy state untouched). Rides
        the ActBusy delegate so it works from any thread without a second
        marshaller; a no-op while nothing is busy, since the bar is hidden.
    #>
    param(
        $Percent = $null,
        [switch]$Indeterminate,
        [string]$Text = ''
    )

    if (-not ($global:sync -and $global:sync.FmkWindow)) { return }

    if ($Indeterminate -or ($null -eq $Percent)) {
        $global:sync.PendingProgressMode = 'Indeterminate'
        $global:sync.PendingProgressValue = 0
    }
    else {
        $req = Get-FmkProgressRequest -Percent $Percent
        $global:sync.PendingProgressMode = $req.Mode
        $global:sync.PendingProgressValue = $req.Value
    }
    if ($Text) {
        $global:sync.PendingBusyText = $Text
        $global:sync.PendingStatusText = $Text
        $global:sync.PendingStatusColor = 'FmkFgMuted'
    }
    [void](Invoke-FmkUiAction -Name 'ActBusy')
}

function Get-FmkQueueOverallPercent {
    <#
        Queue-wide percentage from completed tasks plus the current task's
        measured fraction -- the only honest determinate number available when
        installers emit no progress of their own. Pure math, unit tested.
    #>
    param(
        [int]$Done = 0,
        [int]$Total = 0,
        [double]$ItemPercent = 0
    )
    if ($Total -le 0) { return 0 }
    if ($Done -lt 0) { $Done = 0 }
    if ($Done -gt $Total) { $Done = $Total }
    if ($ItemPercent -lt 0) { $ItemPercent = 0 }
    if ($ItemPercent -gt 100) { $ItemPercent = 100 }
    return ($Done + ($ItemPercent / 100)) / $Total * 100
}

function Update-FmkObservedProgress {
    <#
        Forwards an installer-observed percentage (parsed from real output
        text, never estimated) to the shared bar. Inside a queue it is folded
        into the overall completed/total math; for a lone task it is the task
        percentage. Forwards only on integer change. Safe to call from the
        background runspace or with no window at all (then a no-op).
    #>
    param([int]$ItemPercent)

    $st = $global:sync
    if (-not ($st -and $st.FmkWindow)) { return }
    if ($ItemPercent -lt 0) { $ItemPercent = 0 }
    if ($ItemPercent -gt 100) { $ItemPercent = 100 }

    $overall = $ItemPercent
    if ([bool]$st.QueueRunning) {
        $total = 0
        $done = 0
        try { $total = [int]$st.QueueTotal } catch { $total = 0 }
        try { $done = [int]$st.QueueDone } catch { $done = 0 }
        if ($total -gt 0) {
            $overall = Get-FmkQueueOverallPercent -Done $done -Total $total -ItemPercent $ItemPercent
        }
    }
    $rounded = [int][Math]::Round($overall)
    $sent = -1
    try { $sent = [int]$st.ObservedItemSent } catch { $sent = -1 }
    if ($rounded -ne $sent) {
        $st.ObservedItemSent = $rounded
        Set-FmkProgress -Percent $overall
    }
}

function Set-FmkBusyNow {
    <#
        Applies PendingBusy / PendingBusyText / PendingProgressMode /
        PendingProgressValue. UI thread only. This is the single place that
        locks and unlocks the interface, and every task path reaches it from a
        finally block -- so success, failure, and cancellation all restore.
        Terminal modes (Complete/Failed/Cancelled) keep a truthful end state
        on the bar after the overlay lifts, until the next task starts.
    #>
    $state = $global:sync
    $busy = [bool]$state.PendingBusy
    $text = [string]$state.PendingBusyText
    $mode = [string]$state.PendingProgressMode
    if (-not $mode) { $mode = if ($busy) { 'Indeterminate' } else { 'None' } }
    $value = 0
    try { $value = [double]$state.PendingProgressValue } catch { $value = 0 }

    # Loading overlay: dims the body, swallows its mouse input, keeps the
    # current operation and a cancel action visible. The log pane is outside
    # the overlay, so output keeps streaming and the shared bar stays in view.
    if ($state.BusyOverlay) {
        $state.BusyOverlay.Visibility = if ($busy) {
            [System.Windows.Visibility]::Visible
        }
        else {
            [System.Windows.Visibility]::Collapsed
        }
    }
    # Indeterminate means no measured percentage exists (winget, for example,
    # emits phase lines but never a number on a redirected pipe), so the
    # overlay says so explicitly instead of implying measurable progress.
    if ($state.BusyOverlayText -and $text) {
        $state.BusyOverlayText.Text = if ($busy -and ($mode -eq 'Indeterminate')) {
            "$text -- waiting for installer progress information"
        }
        else {
            $text
        }
    }
    # Only the queue is safely cancellable (it stops after the current step;
    # a running installer is never killed). Single tasks show no Cancel.
    if ($state.TaskCancelButton) {
        $showCancel = $busy -and [bool]$state.QueueRunning
        $state.TaskCancelButton.Visibility = if ($showCancel) {
            [System.Windows.Visibility]::Visible
        }
        else {
            [System.Windows.Visibility]::Collapsed
        }
    }

    if ($state.ProgressBar) {
        # Terminal states stay visible after the task ends (green 100 on true
        # success, red/amber frozen at the last measured value otherwise), so
        # failure never masquerades as completion. The next task start resets.
        $showBar = $busy -or ($mode -eq 'Complete') -or ($mode -eq 'Failed') -or ($mode -eq 'Cancelled')
        $state.ProgressBar.Visibility = if ($showBar) {
            [System.Windows.Visibility]::Visible
        }
        else {
            [System.Windows.Visibility]::Collapsed
        }
        try { $state.ProgressBar.IsIndeterminate = ($busy -and ($mode -eq 'Indeterminate')) } catch { }
        $barBrush = $null
        try {
            if ($mode -eq 'Failed') { $barBrush = $state.FmkWindow.Resources['FmkRiskHigh'] }
            elseif ($mode -eq 'Cancelled') { $barBrush = $state.FmkWindow.Resources['FmkRiskMed'] }
            else { $barBrush = $state.FmkWindow.Resources['FmkRiskLow'] }
            if ($barBrush) { $state.ProgressBar.Foreground = $barBrush }
        }
        catch { }
        if ($mode -eq 'Determinate' -or $mode -eq 'Failed' -or $mode -eq 'Cancelled') {
            try { $state.ProgressBar.Value = $value } catch { }
        }
        elseif ($mode -eq 'Complete') {
            try { $state.ProgressBar.Value = 100 } catch { }
        }
        elseif (-not $busy) {
            try { $state.ProgressBar.Value = 0 } catch { }
        }
    }

    # Numeric percentage beside the bar. Set only from measured values; empty
    # (not zero) whenever none exists, so indeterminate never fakes a number.
    if ($state.ProgressPercent) {
        $pctText = ''
        if ($mode -eq 'Complete') { $pctText = '100%' }
        elseif ($mode -eq 'Determinate' -or $mode -eq 'Failed' -or $mode -eq 'Cancelled') {
            $pctText = "$([int][Math]::Round($value))%"
        }
        $state.ProgressPercent.Text = $pctText
    }

    foreach ($btn in $state.RunButtons) { $btn.IsEnabled = -not $busy }

    # Keep the Software queue action bar in step with single-module runs without
    # adding it to RunButtons (the queue owns its enabled state).
    try {
        if ($state.InstallSelectedButton -or $state.ClearSelectionButton) {
            $count = 0
            if ($state.SoftwareSelection) { $count = $state.SoftwareSelection.Count }
            $queueBusy = [bool]$state.QueueRunning
            if ($state.InstallSelectedButton) {
                $state.InstallSelectedButton.IsEnabled = ($count -gt 0) -and (-not $busy) -and (-not $queueBusy)
            }
            if ($state.ClearSelectionButton) {
                $state.ClearSelectionButton.IsEnabled = ($count -gt 0) -and (-not $busy) -and (-not $queueBusy)
            }
        }
    }
    catch { }

    # Interaction lock: the overlay above swallows mouse input over the body,
    # and disabling these containers also drops their keyboard tab stops, so
    # tabs, cards, and page buttons are unreachable while exclusive work runs.
    # Header search, risk help, and the log toggle stay live on purpose:
    # filtering and log inspection never conflict with a running task.
    try {
        if ($state.SideBar) { $state.SideBar.IsEnabled = -not $busy }
        if ($state.MainContent) { $state.MainContent.IsEnabled = -not $busy }
    }
    catch { }

    if (-not $state.StatusText) { return }
    if ($busy -and $text) { $state.StatusText.Text = $text }
    elseif (-not $busy) { $state.StatusText.Text = 'Ready' }
}

function Set-FmkBusy {
    <#
        The single authoritative task-state switch: overlay, shared progress
        bar, status text, interaction lock, and action buttons. Busy without an
        explicit percentage is indeterminate -- a percentage is only shown
        when the caller measured one. Quick interactions (selecting cards,
        filtering, navigating) never call this, so they never lock.
    #>
    param(
        [Parameter(Mandatory)][bool]$Busy,
        [string]$Text = '',
        $Percent = $null
    )

    if (-not ($global:sync -and $global:sync.FmkWindow)) { return }

    $global:sync.PendingBusy = $Busy
    $global:sync.PendingBusyText = $Text
    if ($Busy) {
        if ($null -eq $Percent) {
            $global:sync.PendingProgressMode = 'Indeterminate'
            $global:sync.PendingProgressValue = 0
        }
        else {
            $req = Get-FmkProgressRequest -Percent $Percent
            $global:sync.PendingProgressMode = $req.Mode
            $global:sync.PendingProgressValue = $req.Value
        }
    }
    else {
        $global:sync.PendingProgressMode = 'None'
        $global:sync.PendingProgressValue = 0
    }
    [void](Invoke-FmkUiAction -Name 'ActBusy')
}

function Set-FmkTaskComplete {
    <#
        Parks the truthful end state after a task finishes: 100% green only on
        real success, red/amber frozen at the last measured value on failure
        or cancellation. The overlay is already down (Busy=$false); this only
        sets what the bar keeps showing until the next task starts.
    #>
    param(
        [Parameter(Mandatory)][ValidateSet('Success', 'Failed', 'Cancelled')][string]$Status
    )

    if (-not ($global:sync -and $global:sync.FmkWindow)) { return }

    $global:sync.PendingBusy = $false
    $global:sync.PendingProgressMode = if ($Status -eq 'Success') { 'Complete' }
    elseif ($Status -eq 'Failed') { 'Failed' }
    else { 'Cancelled' }
    if ($Status -eq 'Success') { $global:sync.PendingProgressValue = 100 }
    [void](Invoke-FmkUiAction -Name 'ActBusy')
}

# ----------------------------------------------------------------------------
# source: 04-runspace.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# BACKGROUND EXECUTION
# ==============================================================================
# Modules block for minutes (sfc, DISM, winget). Running them on the UI thread
# would freeze the window, so each one runs on its own runspace.
#
# A fresh runspace has an empty session state -- none of our functions or
# modules exist in it. Rather than marshalling every function and variable
# across by hand, the runspace re-runs this script in "library mode"
# (-FmkLibraryMode), which defines everything and returns before touching the
# UI. That keeps a single source of truth for all module code.
#
# One runspace per invocation, not a pool: modules mutate process-wide state
# (scheduled tasks, registry, services) and reusing a runspace risks leaking
# that between runs. The ~1s startup cost is acceptable for operations that
# take minutes.

function Get-FmkLibraryPath {
    <#
        A path to a copy of this script that a runspace can dot-source.
        Running from a file we already have one; running from `irm | iex` we do
        not, so fetch a copy into the temp dir (that is what $ScriptUrl is for).
    #>
    if ($PSCommandPath -and (Test-Path -LiteralPath $PSCommandPath)) {
        return $PSCommandPath
    }

    $libPath = Join-Path $DataTemp 'FreeMixKit.Library.ps1'
    if (-not (Test-Path -LiteralPath $libPath)) {
        Write-Host "Fetching a runspace bootstrap copy..." -ForegroundColor DarkGray
        Invoke-WebRequest -Uri $ScriptUrl -OutFile $libPath -UseBasicParsing -ErrorAction Stop
    }
    return $libPath
}

function Wait-FmkPump {
    <#
        Runs a nested dispatcher frame for a short interval, which is what
        actually lets the UI repaint and lets background threads deliver their
        Dispatcher.Invoke calls while we are blocked waiting on a runspace.

        NOTE: this must be a real frame. Dispatcher.Invoke called *on* the
        dispatcher thread executes inline and does not drain the queue, so
        `Invoke([Background], {})` would look like a pump but process nothing.

        The frame and timer are held in globals on purpose: PowerShell
        scriptblocks do not capture the local scope they were created in, so a
        Tick handler cannot see function-local variables.
    #>
    param([int]$Milliseconds = 60)

    $global:FmkPumpFrame = New-Object System.Windows.Threading.DispatcherFrame
    $global:FmkPumpTimer = New-Object System.Windows.Threading.DispatcherTimer
    $global:FmkPumpTimer.Interval = [TimeSpan]::FromMilliseconds($Milliseconds)
    # [void]: this runs inside the wait loop in Invoke-FmkRunspace, so anything
    # that reached the pipeline here would be emitted by *that* function and turn
    # its single result object into an array.
    [void]$global:FmkPumpTimer.Add_Tick({
            # Null-checked because the globals are cleared in the finally block:
            # a tick that somehow outlives its frame must not throw inside a
            # dispatcher callback.
            if ($global:FmkPumpTimer) { $global:FmkPumpTimer.Stop() }
            if ($global:FmkPumpFrame) { $global:FmkPumpFrame.Continue = $false }
        })

    try {
        $global:FmkPumpTimer.Start()
        [System.Windows.Threading.Dispatcher]::PushFrame($global:FmkPumpFrame)
    }
    finally {
        $global:FmkPumpTimer.Stop()
        $global:FmkPumpTimer = $null
        $global:FmkPumpFrame = $null
    }
}

function Invoke-FmkRunspace {
    <#
        Runs one module on a background runspace and returns the same
        {Status, Message, Duration, ...} object Invoke-ModuleAction produces.
    #>
    param(
        [Parameter(Mandatory)][string]$ActionKey,
        [Parameter(Mandatory)]$Sync
    )

    $libPath = $null
    try {
        $libPath = Get-FmkLibraryPath
    }
    catch {
        Write-Log "Could not obtain a runspace bootstrap: $($_.Exception.Message)" "Warn"
    }

    if (-not $libPath) {
        # Degrade rather than fail: the module still runs, the window just
        # blocks for the duration.
        Write-Log "No bootstrap available; running on the UI thread (window will block)." "Warn"
        return Invoke-ModuleAction -ActionKey $ActionKey
    }

    $rs = $null
    $ps = $null
    try {
        $rs = [runspacefactory]::CreateRunspace()
        # STA, not MTA. Modules reach late-bound COM (WScript.Shell for the
        # shortcut module, Windows Installer) which the original script only ever
        # touched from PowerShell 5.1's STA thread. One module runs at a time, so
        # there is no throughput to gain from MTA and a real regression to lose.
        $rs.ApartmentState = 'STA'
        $rs.Open()

        $ps = [powershell]::Create()
        $ps.Runspace = $rs

        [void]$ps.AddScript({
                param($Sync, $LibraryPath, $ActionKey)

                # Library mode defines every function and module in this
                # runspace's scope, then returns.
                . $LibraryPath -FmkLibraryMode

                # Must be set AFTER the dot-source -- library mode initialises
                # $global:sync to $null on the way through.
                $global:sync = $Sync

                return Invoke-ModuleAction -ActionKey $ActionKey
            }).AddArgument($Sync).AddArgument($libPath).AddArgument($ActionKey)

        $handle = $ps.BeginInvoke()

        # Keep the window alive while the module runs. Without this the UI
        # thread would sit inside EndInvoke: no repaint, no log lines, and the
        # window would be reported as "not responding".
        while (-not $handle.IsCompleted) {
            Wait-FmkPump -Milliseconds 60
        }

        # EndInvoke hands back a Collection[PSObject]. Take the last element
        # explicitly rather than relying on pipeline unrolling, so a module that
        # accidentally emits extra output cannot turn $result into an array.
        $output = @($ps.EndInvoke($handle))
        if ($output.Count -gt 0) { return $output[$output.Count - 1] }
        return $null
    }
    finally {
        if ($ps) { $ps.Dispose() }
        if ($rs) {
            $rs.Close()
            $rs.Dispose()
        }
    }
}

function Invoke-FmkModule {
    <#
        UI-facing entry point: runs a module with busy state and result
        bookkeeping, swallowing failures into the exported result list.
    #>
    param(
        [Parameter(Mandatory)][string]$ActionKey,
        [Parameter(Mandatory)]$Sync
    )

    $label = Get-ModuleMetaValue -ActionKey $ActionKey -Name "Label" -DefaultValue $ActionKey

    # Re-entrancy guard. Set-FmkBusy disables every action button before the
    # module starts, which is what normally stops a second click, but a queued
    # click that was already dispatched can still arrive here. Refusing it
    # explicitly is what makes "clicking the same button twice installs once"
    # true of the dispatch path rather than only of the button's enabled state.
    if ([bool]$Sync.QueueRunning) {
        Write-Log "Install queue is running; ignored the request for '$label'." "Warn"
        return $null
    }
    if ($Sync.Busy) {
        Write-Log "Already running: $($Sync.BusyLabel). Ignored the request for '$label'." "Warn"
        return $null
    }
    $Sync.Busy = $true
    $Sync.BusyLabel = $label

    Set-FmkBusy -Busy $true -Text "Running: $label"
    Write-Log "Executing: $label" "Muted"

    try {
        $result = Invoke-FmkRunspace -ActionKey $ActionKey -Sync $Sync
    }
    catch {
        $result = [pscustomobject]@{
            Status        = "Failed"
            Message       = $_.Exception.Message
            Duration      = [timespan]::Zero
            RollbackHint  = Get-ModuleMetaValue -ActionKey $ActionKey -Name "RollbackHint" -DefaultValue ""
            PreviousState = ""
        }
    }
    finally {
        $Sync.Busy = $false
        $Sync.BusyLabel = $null
        Set-FmkBusy -Busy $false
    }

    # A module that returned nothing at all still gets recorded as a failure
    # rather than crashing the result bookkeeping below.
    if (-not $result -or -not $result.PSObject.Properties['Status']) {
        $result = [pscustomobject]@{
            Status        = "Failed"
            Message       = "Module produced no result object."
            Duration      = [timespan]::Zero
            RollbackHint  = ""
            PreviousState = ""
        }
    }

    Add-ModuleResult -Module $ActionKey `
        -Status $result.Status `
        -Message $result.Message `
        -Duration $result.Duration `
        -RollbackHint $result.RollbackHint `
        -PreviousState $result.PreviousState

    if ($result.Status -eq 'Success') {
        Write-Log "Result: $($result.Status) in $([Math]::Round($result.Duration.TotalSeconds, 2))s" "Success"
        Set-FmkTaskComplete -Status 'Success'
        Set-FmkStatus "Completed: $label" 'FmkRiskLow'
    }
    elseif ($result.Status -eq 'Canceled') {
        Write-Log "Result: canceled by user" "Warn"
        Set-FmkTaskComplete -Status 'Cancelled'
        Set-FmkStatus 'Canceled.' 'FmkRiskMed'
    }
    else {
        Write-Log "Result: $($result.Status) - $($result.Message)" "Error"
        Set-FmkTaskComplete -Status 'Failed'
        Set-FmkStatus 'Failed -- see output.' 'FmkRiskHigh'
    }

    if ($result.RollbackHint) { Write-Log "Rollback hint: $($result.RollbackHint)" "Warn" }
    if ($result.PreviousState) { Write-Log "Previous state: $($result.PreviousState)" "Info" }

    return $result
}

# ----------------------------------------------------------------------------
# source: 05-dialogs.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# DIALOGS
# ==============================================================================
# Confirm-Action keeps its original signature so Invoke-ModuleAction's
# ConfirmMessage path works unchanged -- it just renders a real modal instead of
# a console prompt.
#
# SCOPE: Confirm-Action is reached from a *background runspace* (a module body
# calls it), so the dialog has to be built on the UI thread. The runspace cannot
# do that itself, and it must not hand Dispatcher.Invoke a scriptblock of its
# own -- that scriptblock would carry the runspace's session state and re-enter
# the runspace that is currently blocked on the Invoke. So the arguments travel
# through $global:sync and the work happens in New-FmkConfirmWindow, reached via
# the ActShowDialog delegate built on the UI thread at boot.

function New-FmkConfirmWindow {
    <#
        Builds and shows the modal. Runs on the UI thread. Reads everything it
        needs out of $global:sync -- see the scope note above.
    #>
    $state = $global:sync
    $owner = $state.FmkWindow

    try {
        $dlg = New-Object System.Windows.Window
        $dlg.Title = $state.DlgTitle
        $dlg.Width = 500
        $dlg.MaxWidth = 640
        $dlg.SizeToContent = [System.Windows.SizeToContent]::Height
        $dlg.ResizeMode = [System.Windows.ResizeMode]::NoResize
        $dlg.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
        $dlg.ShowInTaskbar = $false
        $dlg.Owner = $owner
        $dlg.Background = $owner.Resources['FmkBgAlt']
        $dlg.Foreground = $owner.Resources['FmkFg']
        $dlg.FontFamily = $owner.FontFamily
        $dlg.FontSize = 13

        $root = New-Object System.Windows.Controls.Grid
        $root.Margin = New-Object System.Windows.Thickness(22)

        $rowText = New-Object System.Windows.Controls.RowDefinition
        $rowText.Height = [System.Windows.GridLength]::Auto
        $rowBar = New-Object System.Windows.Controls.RowDefinition
        $rowBar.Height = [System.Windows.GridLength]::Auto
        [void]$root.RowDefinitions.Add($rowText)
        [void]$root.RowDefinitions.Add($rowBar)

        $text = New-Object System.Windows.Controls.TextBlock
        $text.Text = $state.DlgMessage
        $text.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $text.Margin = New-Object System.Windows.Thickness(0, 0, 0, 20)
        [System.Windows.Controls.Grid]::SetRow($text, 0)
        [void]$root.Children.Add($text)

        $bar = New-Object System.Windows.Controls.StackPanel
        $bar.Orientation = [System.Windows.Controls.Orientation]::Horizontal
        $bar.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
        [System.Windows.Controls.Grid]::SetRow($bar, 1)

        $cancel = New-Object System.Windows.Controls.Button
        $cancel.Content = $state.DlgCancel
        $cancel.MinWidth = 96
        $cancel.Padding = New-Object System.Windows.Thickness(14, 7, 14, 7)
        $cancel.Margin = New-Object System.Windows.Thickness(0, 0, 8, 0)
        $cancel.IsCancel = $true
        $cancel.Add_Click({
                $global:sync.DialogResult = $false
                if ($global:sync.Dialog) { $global:sync.Dialog.Close() }
            })

        $ok = New-Object System.Windows.Controls.Button
        $ok.Content = $state.DlgConfirm
        $ok.MinWidth = 96
        $ok.Padding = New-Object System.Windows.Thickness(14, 7, 14, 7)
        $ok.IsDefault = $true
        $ok.Add_Click({
                $global:sync.DialogResult = $true
                if ($global:sync.Dialog) { $global:sync.Dialog.Close() }
            })

        [void]$bar.Children.Add($cancel)
        [void]$bar.Children.Add($ok)
        [void]$root.Children.Add($bar)

        $dlg.Content = $root
        $state.Dialog = $dlg

        [void]$dlg.ShowDialog()
    }
    finally {
        # Cleared even if ShowDialog throws, so a later Confirm-Action is not
        # left holding a dead window.
        $global:sync.Dialog = $null
    }
}

function Show-FmkConfirmDialog {
    param(
        [Parameter(Mandatory)][string]$Message,
        [string]$Title = 'FreeMixKit',
        [string]$ConfirmText = 'Continue',
        [string]$CancelText = 'Cancel'
    )

    $state = $global:sync
    if (-not $state) { return $false }

    $state.DialogResult = $false
    $state.Dialog = $null
    $state.DlgMessage = $Message
    $state.DlgTitle = $Title
    $state.DlgConfirm = $ConfirmText
    $state.DlgCancel = $CancelText

    try {
        [void](Invoke-FmkUiAction -Name 'ActShowDialog')
    }
    finally {
        foreach ($key in 'DlgMessage', 'DlgTitle', 'DlgConfirm', 'DlgCancel') {
            $state.Remove($key)
        }
    }

    return [bool]$state.DialogResult
}

function Confirm-Action([string]$Prompt) {
    # No window (library mode, or called before the UI is up): fall back to the
    # console so modules stay usable outside the GUI.
    if (-not ($global:sync -and $global:sync.FmkWindow)) {
        $response = Read-Host "$Prompt (Y/N)"
        return $response -match '^[Yy]$'
    }

    # ConfirmMessage strings already carry real newlines -- they were written as
    # double-quoted PowerShell literals, so `n was expanded at parse time. No
    # unescaping needed here.
    return Show-FmkConfirmDialog -Message $Prompt
}

function Show-FmkError {
    param([Parameter(Mandatory)][string]$Message, [string]$Title = 'FreeMixKit - Error')
    if (-not ($global:sync -and $global:sync.FmkWindow)) {
        Write-Host $Message -ForegroundColor Red
        return
    }
    [void](Show-FmkConfirmDialog -Message $Message -Title $Title -ConfirmText 'OK' -CancelText 'Close')
}

# ----------------------------------------------------------------------------
# source: 06-cards.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# NAVIGATION AND CONTENT CARDS
# ==============================================================================
# Every card is generated from $ModuleMeta, so the registry stays the single
# source of truth for what appears in the UI.
#
# A page is a stack of sections. Each section is a heading plus a body panel,
# and the body is either
#
#   * a WrapPanel of tiles  -- categories in $FmkGridCategories, where each
#     entry is a standalone application and a logo reads better than a row of
#     text; or
#   * a StackPanel of list cards -- everything else, where a one-line
#     description next to the action is the right shape.
#
# Both bodies hold children carrying the module key in Uid and the search
# haystack in Tag (a Border for list rows, a Button for tiles), so filtering
# treats them identically.
#
# Click handlers read their inputs from the sender ($this) and from
# $global:sync. They deliberately never close over function-locals, because
# PowerShell scriptblocks do not capture the scope they were created in -- a
# `$key` referenced inside Add_Click would resolve to nothing at click time.
#
# The StackPanel holding a page's cards is called $cardPanel, not $host. "Host"
# is the obvious name for it and that is exactly the problem: variable names are
# case-insensitive, so $host is $Host, the read-only automatic variable, and the
# assignment throws at runtime. Compile.ps1 now rejects assignments to automatic
# variables outright.

# Sidebar order. Each name must match a Category in registry.ps1 and a
# x:Name="page_<name>" element in ui.xaml; Compile.ps1 enforces this.
$FmkCategories = @('System', 'Utilities', 'Software', 'Activation', 'About')

# Categories drawn as a logo grid. Software is where the standalone applications
# live, which is exactly the set a user browses by name and icon; the other
# categories are task lists ("clean this", "fix that") where a compact row per
# entry is easier to scan.
$FmkGridCategories = @('Software')

# Tile metrics. Every tile sets its own Width/Height to these, so all tiles come
# out the same size, the columns line up regardless of how long a name or
# description is, and the WrapPanel reflows to the page width on its own (the
# page's ScrollViewer has horizontal scrolling disabled, which is what makes the
# panel wrap instead of growing a scrollbar).
#
# The size sits on the tile rather than on the panel as WrapPanel.ItemWidth /
# ItemHeight, and that is load-bearing. ItemWidth/ItemHeight are applied to every
# child unconditionally, Collapsed ones included: a tile the search has filtered
# out keeps a full-size empty slot, so the survivors stay in their original
# columns and the grid fills up with holes. A Collapsed Border measures to
# nothing, so a tile carrying its own size drops out of the layout entirely and
# the rest close up behind it. Never set ItemWidth/ItemHeight here.
#
# The margin lies outside Width/Height: it is the gutter between neighbours and
# at the panel edges.
#
# Compact launcher sizing: the tile is a single clickable surface with no inner
# button, so the height budget covers the logo, the name, and the description
# only. The mark is deliberately large against the tile (26px art in a 38px box
# on a 152px tile) so icons stay recognizable at five columns.
$FmkTileWidth = 152
$FmkTileHeight = 140
$FmkTileMargin = 5
$FmkLogoSize = 26

# Content height budget inside a tile, in device-independent pixels, with the
# TileButton template's 8px padding on each side already subtracted -- the tile
# is 140 tall, so 124 is available:
#
#     38  logo box
#      6  gap
#     32  name          (two lines at 12px)
#      4  gap
#     32  description   (two lines at 11px)
#    ---
#    112, against 124 available -- the remainder is slack for descenders and
#    the risk-badge overlay, which floats above the content and shifts nothing.
#
# A name longer than two lines or a description longer than two is clipped
# (with an ellipsis) rather than allowed to stretch the tile, which is what
# keeps the grid regular. Keep Software descriptions under about 48 characters
# and labels under about 24.
$FmkTileNameHeight = 32
$FmkTileDescriptionHeight = 32

function Get-FmkModuleKeys {
    <# Module keys for a category, in registration order. #>
    param([Parameter(Mandatory)][string]$Category)

    $keys = @()
    foreach ($key in $ModuleMeta.Keys) {
        if ($ModuleMeta[$key].Category -eq $Category) { $keys += $key }
    }
    return $keys
}

function Test-FmkGridCategory {
    param([Parameter(Mandatory)][string]$Category)
    return ($FmkGridCategories -contains $Category)
}

function Test-FmkLowContrast {
    <#
        True when two colors are too close together to tell apart.

        Used to decide whether a brand mark's own colour is legible against the
        card it is drawn on. The threshold is deliberately loose: a brand colour
        is a deliberate choice and worth keeping even when it is low contrast, so
        this only fires when a mark is effectively invisible against the card.
    #>
    param(
        [Parameter(Mandatory)][string]$Foreground,
        [Parameter(Mandatory)][string]$Background,
        [double]$Minimum = 1.8
    )

    $lumA = Get-FmkLuminance -Hex $Foreground
    $lumB = Get-FmkLuminance -Hex $Background
    $high = [Math]::Max($lumA, $lumB)
    $low = [Math]::Min($lumA, $lumB)
    return ((($high + 0.05) / ($low + 0.05)) -lt $Minimum)
}

function Get-FmkLuminance {
    <# WCAG relative luminance of a #rrggbb color, 0 (black) to 1 (white). #>
    param([Parameter(Mandatory)][string]$Hex)

    $hexValue = $Hex.TrimStart('#')
    if ($hexValue.Length -ne 6) { return 0 }

    $linear = foreach ($offset in 0, 2, 4) {
        $channel = [Convert]::ToInt32($hexValue.Substring($offset, 2), 16) / 255
        if ($channel -le 0.03928) { $channel / 12.92 }
        else { [Math]::Pow((($channel + 0.055) / 1.055), 2.4) }
    }

    return (0.2126 * $linear[0]) + (0.7152 * $linear[1]) + (0.0722 * $linear[2])
}

function Get-FmkInitials {
    <# Fallback mark for a module with no logo: initials on a neutral tile. #>
    param([Parameter(Mandatory)][string]$Text)

    $words = @([regex]::Matches($Text, '[A-Za-z0-9]\S*') | ForEach-Object { $_.Value })
    if ($words.Count -eq 0) { return '?' }
    if ($words.Count -eq 1) { return $words[0].Substring(0, [Math]::Min(2, $words[0].Length)).ToUpperInvariant() }
    return (($words[0].Substring(0, 1)) + ($words[1].Substring(0, 1))).ToUpperInvariant()
}

function New-FmkLogoPath {
    <#
        One vector mark at tile-icon size. $null when the data does not parse,
        so a corrupt entry degrades to the monogram path instead of throwing
        during card construction.
    #>
    param(
        [Parameter(Mandatory)][string]$Data,
        [Parameter(Mandatory)]$Sync
    )

    try {
        $path = New-Object System.Windows.Shapes.Path
        # "F1 " is the path mini-language's fill-rule prefix (non-zero). SVG
        # defaults to non-zero and the marks are authored for it, but WPF's
        # parser defaults to even-odd -- which punches holes through the parts of
        # a mark that are meant to be solid, such as Node.js's hexagon.
        $path.Data = [System.Windows.Media.Geometry]::Parse("F1 $Data")
        # Uniform stretch scales each mark's own coordinate space to the box, so
        # an icon authored on a 24x24 grid and one on a 128x128 grid come out the
        # same size.
        $path.Stretch = [System.Windows.Media.Stretch]::Uniform
        $path.Width = $FmkLogoSize
        $path.Height = $FmkLogoSize
        $path.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $path.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        return $path
    }
    catch {
        return $null
    }
}

function New-FmkLogoBox {
    <#
        The square mark at the top of a tile.

        Four cases, in order: a vendored brand mark drawn as vector path data;
        a vendored raster icon (base64 PNG from the publisher's own repo) drawn
        as an Image with aspect preserved; a shape set (one Path per element,
        for marks that are not a single flat shape); and a monogram where no
        trustworthy mark exists. A module with no entry in $FmkLogos at all
        falls back to the label's initials, so a new registry entry -- or a
        missing asset file -- never breaks the grid.
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)]$Meta,
        [Parameter(Mandatory)]$Sync
    )

    $box = New-Object System.Windows.Controls.Border
    $box.Style = $Sync.FmkWindow.FindResource('LogoBox')

    $entry = $null
    $logoKey = [string]$Meta.Logo
    if ($logoKey -and $FmkLogos.ContainsKey($logoKey)) { $entry = $FmkLogos[$logoKey] }

    if ($entry -and $entry.ContainsKey('Png')) {
        # Raster icons are vendored base64 at build time, so the tile draws
        # with no network access and no image files, exactly like the marks.
        try {
            $bytes = [Convert]::FromBase64String([string]$entry.Png)
            $stream = New-Object System.IO.MemoryStream($bytes, $false)
            try {
                $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
                $bmp.BeginInit()
                $bmp.StreamSource = $stream
                $bmp.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $bmp.EndInit()
            }
            finally {
                $stream.Close()
            }
            $img = New-Object System.Windows.Controls.Image
            $img.Source = $bmp
            # Uniform keeps the aspect and the transparency; a wide banner
            # (SpotX) letterboxes instead of stretching.
            $img.Stretch = [System.Windows.Media.Stretch]::Uniform
            $img.Width = $FmkLogoSize
            $img.Height = $FmkLogoSize
            $img.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
            $img.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
            [System.Windows.Media.RenderOptions]::SetBitmapScalingMode($img, [System.Windows.Media.BitmapScalingMode]::HighQuality)

            $box.Child = $img
            return $box
        }
        catch {
            Write-Log "Logo for '$Key' is corrupt ($($_.Exception.Message)); using initials." "Warn"
        }
    }

    if ($entry -and $entry.ContainsKey('Shapes')) {
        $layer = New-Object System.Windows.Controls.Grid
        foreach ($shape in @($entry.Shapes)) {
            $sub = New-FmkLogoPath -Data ([string]$shape.Data) -Sync $Sync
            if (-not $sub) { continue }
            if ($shape.ContainsKey('Fill') -and $shape.Fill) {
                $sub.Fill = (New-Object System.Windows.Media.BrushConverter).ConvertFromString([string]$shape.Fill)
            }
            else {
                $sub.Fill = [System.Windows.Media.Brushes]::Transparent
            }
            if ($shape.ContainsKey('Stroke') -and $shape.Stroke) {
                $sub.Stroke = (New-Object System.Windows.Media.BrushConverter).ConvertFromString([string]$shape.Stroke)
                $sub.StrokeThickness = [double]$shape.StrokeThickness
            }
            [void]$layer.Children.Add($sub)
        }
        if ($layer.Children.Count -gt 0) {
            $box.Child = $layer
            return $box
        }
    }

    if ($entry -and $entry.ContainsKey('Data')) {
        $fill = [string]$entry.Color

        # A mark drawn in the card's own colour is invisible. Substituting the
        # theme foreground rather than a hardcoded white is what keeps the
        # fallback correct on the light theme too, where the foreground is
        # dark and a dark mark must stay dark.
        $palette = $FmkThemes[$Sync.Theme]
        if ($palette -and (Test-FmkLowContrast -Foreground $fill -Background $palette['FmkCard'])) {
            $fill = $palette['FmkFg']
        }

        $path = New-FmkLogoPath -Data ([string]$entry.Data) -Sync $Sync
        if ($path) {
            $path.Fill = (New-Object System.Windows.Media.BrushConverter).ConvertFromString($fill)
            $box.Child = $path
            return $box
        }
    }

    $text = New-Object System.Windows.Controls.TextBlock
    $text.Text = if ($entry -and $entry.ContainsKey('Mono')) {
        [string]$entry.Mono
    }
    else {
        Get-FmkInitials -Text $Meta.Label
    }
    $text.FontSize = 15
    $text.FontWeight = [System.Windows.FontWeights]::Bold
    $text.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
    $text.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    if ($Sync.FmkWindow.Resources.Contains('FmkLabel')) {
        $text.Foreground = $Sync.FmkWindow.Resources['FmkLabel']
    }

    $box.Child = $text
    return $box
}

function New-FmkRiskBadge {
    <#
        Low, Medium, and High each get a badge in their own theme color; None
        (and anything unknown) gets nothing. Visibility goes through
        Test-FmkRiskBadgeVisible so the rule lives in one testable place.
    #>
    param([Parameter(Mandatory)]$Meta, [Parameter(Mandatory)]$Sync)

    if (-not (Test-FmkRiskBadgeVisible -Risk ([string]$Meta.Risk))) { return $null }

    $resources = $Sync.FmkWindow.Resources
    $badge = New-Object System.Windows.Controls.Border
    $badge.Style = $Sync.FmkWindow.FindResource('Pill')

    $riskKey = if ($Meta.Risk -eq 'High') { 'FmkRiskHigh' }
    elseif ($Meta.Risk -eq 'Medium') { 'FmkRiskMed' }
    else { 'FmkRiskLow' }
    if ($resources.Contains($riskKey)) { $badge.Background = $resources[$riskKey] }

    $badgeText = New-Object System.Windows.Controls.TextBlock
    $badgeText.Text = $Meta.Risk
    $badgeText.FontSize = 10
    $badgeText.FontWeight = [System.Windows.FontWeights]::SemiBold
    # FmkBg rather than white: the risk fills are bright in the dark theme and
    # dark in the light one, and FmkBg is the inverse of both, so one lookup
    # gives readable text either way. Hardcoded white was unreadable on the
    # dark theme's amber (#FFC83D).
    if ($resources.Contains('FmkBg')) { $badgeText.Foreground = $resources['FmkBg'] }
    $badge.Child = $badgeText

    # Tooltip carries the full breakdown (dimensions, evidence, review date).
    # Get-FmkRiskTooltip lives in 08-risk.ps1; resolved at click time, so the
    # file order does not matter.
    try {
        $tip = Get-FmkRiskTooltip -Meta $Meta
        if ($tip) { $badge.ToolTip = $tip }
    }
    catch { }

    return $badge
}

function New-FmkActionButton {
    <#
        The action button on a list-card row. (Grid tiles are buttons
        themselves and carry no inner button.) Uid holds the module key and the
        click handler lives here, so every row dispatches identically; Tag
        is left free for the search haystack on the card itself.

        Every button is added to $Sync.RunButtons, which is what Set-FmkBusy
        walks to disable the whole UI while a module is in flight -- that is the
        first of the two things stopping a repeated click from starting a second
        install. The second is the re-entrancy guard in Invoke-FmkModule.
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)]$Meta,
        [Parameter(Mandatory)]$Sync,
        [Parameter(Mandatory)][string]$Caption
    )

    $run = New-Object System.Windows.Controls.Button
    $run.Content = $Caption
    $run.Style = $Sync.FmkWindow.FindResource('RunButton')
    $run.ToolTip = "$Caption $($Meta.Label)"
    $run.Uid = $Key
    # [void]: this must not put anything on the pipeline ahead of the caller's
    # return. Both ArrayList.Add and Add_Click return values.
    [void]$run.Add_Click({
            # Named in the log so it is always clear which component a click is
            # installing, including when the click is refused as a duplicate.
            # Muted: dispatch chatter, distinct from the operation's own output.
            Write-Log "Requested: $($this.ToolTip)" "Muted"
            [void](Invoke-FmkModule -ActionKey $this.Uid -Sync $global:sync)
        })
    [void]$Sync.RunButtons.Add($run)

    return $run
}

function New-FmkCard {
    <# A row card: title and description on the left, badge and action on the right. #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)]$Sync
    )

    $meta = $ModuleMeta[$Key]
    $resources = $Sync.FmkWindow.Resources

    $card = New-Object System.Windows.Controls.Border
    $card.Style = $Sync.FmkWindow.FindResource('Card')
    $card.Uid = $Key
    # Search haystack. Lowercased once here so filtering stays cheap.
    $card.Tag = ("$($meta.Label) $($meta.Description)").ToLowerInvariant()

    $grid = New-Object System.Windows.Controls.Grid
    $colText = New-Object System.Windows.Controls.ColumnDefinition
    $colText.Width = New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)
    $colActions = New-Object System.Windows.Controls.ColumnDefinition
    $colActions.Width = [System.Windows.GridLength]::Auto
    [void]$grid.ColumnDefinitions.Add($colText)
    [void]$grid.ColumnDefinitions.Add($colActions)

    # --- left: title + description -------------------------------------------
    $left = New-Object System.Windows.Controls.StackPanel

    $title = New-Object System.Windows.Controls.TextBlock
    $title.Text = $meta.Label
    # 13 matches WinUtil's AppEntryFontSize (13.2); the base size is 12.
    $title.FontSize = 13
    $title.FontWeight = [System.Windows.FontWeights]::SemiBold
    $title.TextWrapping = [System.Windows.TextWrapping]::Wrap
    [void]$left.Children.Add($title)

    $desc = New-Object System.Windows.Controls.TextBlock
    $desc.Text = $meta.Description
    $desc.FontSize = 12
    $desc.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $desc.Margin = New-Object System.Windows.Thickness(0, 4, 0, 0)
    if ($resources.Contains('FmkFgMuted')) { $desc.Foreground = $resources['FmkFgMuted'] }
    [void]$left.Children.Add($desc)

    [System.Windows.Controls.Grid]::SetColumn($left, 0)
    [void]$grid.Children.Add($left)

    # --- right: risk badge + action ------------------------------------------
    $right = New-Object System.Windows.Controls.StackPanel
    $right.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $right.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
    $right.Margin = New-Object System.Windows.Thickness(16, 0, 0, 0)

    $badge = New-FmkRiskBadge -Meta $meta -Sync $Sync
    if ($badge) { [void]$right.Children.Add($badge) }

    [void]$right.Children.Add((New-FmkActionButton -Key $Key -Meta $meta -Sync $Sync -Caption $meta.ActionLabel))

    [System.Windows.Controls.Grid]::SetColumn($right, 1)
    [void]$grid.Children.Add($right)

    $card.Child = $grid
    return $card
}

function New-FmkTile {
    <#
        A grid tile: logo, name, description. The tile toggles selection -- a
        click selects, a second click deselects -- and never installs on its
        own. The shared Install Selected button runs the queue in selection
        order. No inner Install button, no checkbox; selection rides on
        Tag ("selected") so the TileButton style draws the colored rounded
        border, with the search haystack in DataContext (Tag is taken).

        Being a real Button buys the interaction states for free: hover and
        pressed come from the TileButton template, keyboard Enter/Space works
        natively, the tile participates in tab order with a visible focus ring
        (IsKeyboardFocused trigger), and the queue disables the action bar
        while running on top of its own re-entrancy guard.

        The risk badge sits in a Grid overlay rather than in the flow, so it can
        appear on a Medium or High tile without shifting the name down and making
        that one tile's contents sit differently from its neighbours'.
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)]$Sync
    )

    $meta = $ModuleMeta[$Key]
    $resources = $Sync.FmkWindow.Resources

    $tile = New-Object System.Windows.Controls.Button
    $tile.Style = $Sync.FmkWindow.FindResource('TileButton')
    # Focus adorner lives OUTSIDE the tile (TileFocusVisual): keyboard focus
    # must never recolor the tile border itself, or a deselected-but-focused
    # tile renders a stale highlight. See the TileButton trigger note in XAML.
    $tile.FocusVisualStyle = $Sync.FmkWindow.FindResource('TileFocusVisual')
    # Local values, so they win over the style's setters; kept here rather than
    # in the XAML so the tile metrics live in one file. Fixed rather than
    # content-sized so the columns and rows line up, and set on the tile rather
    # than on the panel so that filtering a tile out actually removes its slot.
    $tile.Width = $FmkTileWidth
    $tile.Height = $FmkTileHeight
    $tile.Margin = New-Object System.Windows.Thickness($FmkTileMargin)
    $tile.Uid = $Key
    # Haystack lives in DataContext so Tag stays free for the "selected" marker
    # read by the TileButton style. Lowercased once here so filtering stays cheap.
    $tile.DataContext = ("$($meta.Label) $($meta.Description)").ToLowerInvariant()
    $tile.Tag = $null
    $tile.Cursor = [System.Windows.Input.Cursors]::Hand
    Update-FmkTileTooltip -Tile $tile -Meta $meta
    # [void]: Add_Click returns a value that must not reach the pipeline ahead
    # of the caller's return.
    [void]$tile.Add_Click({
            [void](Toggle-FmkSoftwareSelection -ActionKey $this.Uid -Sync $global:sync)
        })
    # Tiles are NOT in RunButtons: Set-FmkBusy disables single-run actions, and
    # the queue manages its own busy state plus the action bar. Click handlers
    # read $this/$global:sync, never function-locals, because PowerShell
    # scriptblocks do not capture the scope they were made in.

    $root = New-Object System.Windows.Controls.Grid

    $stack = New-Object System.Windows.Controls.StackPanel
    $stack.VerticalAlignment = [System.Windows.VerticalAlignment]::Top

    [void]$stack.Children.Add((New-FmkLogoBox -Key $Key -Meta $meta -Sync $Sync))

    $name = New-Object System.Windows.Controls.TextBlock
    $name.Text = $meta.Label
    $name.FontSize = 12
    $name.FontWeight = [System.Windows.FontWeights]::SemiBold
    $name.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $name.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
    $name.TextAlignment = [System.Windows.TextAlignment]::Center
    $name.Height = $FmkTileNameHeight
    $name.Margin = New-Object System.Windows.Thickness(0, 6, 0, 0)
    [void]$stack.Children.Add($name)

    $desc = New-Object System.Windows.Controls.TextBlock
    $desc.Text = $meta.Description
    $desc.FontSize = 11
    $desc.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $desc.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
    $desc.TextAlignment = [System.Windows.TextAlignment]::Center
    $desc.Height = $FmkTileDescriptionHeight
    $desc.Margin = New-Object System.Windows.Thickness(0, 4, 0, 0)
    if ($resources.Contains('FmkFgMuted')) { $desc.Foreground = $resources['FmkFgMuted'] }
    [void]$stack.Children.Add($desc)

    [void]$root.Children.Add($stack)

    $badge = New-FmkRiskBadge -Meta $meta -Sync $Sync
    if ($badge) {
        $badge.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
        $badge.VerticalAlignment = [System.Windows.VerticalAlignment]::Top
        [void]$root.Children.Add($badge)
    }

    $tile.Content = $root
    return $tile
}

function New-FmkSectionBody {
    <#
        Wraps one group's entries in the panel its category calls for. Returns the
        panel; the caller pairs it with a heading.
    #>
    param([Parameter(Mandatory)][bool]$Grid)

    if ($Grid) {
        # No ItemWidth/ItemHeight: those would apply to Collapsed tiles too and
        # keep an empty slot for every filtered-out card, so a search would leave
        # the survivors in their original columns among holes. The tiles carry
        # their own size instead, which is what lets the panel close up the gaps
        # and reflow the filtered set from the top-left. See the metrics above.
        return (New-Object System.Windows.Controls.WrapPanel)
    }

    return (New-Object System.Windows.Controls.StackPanel)
}

function Get-FmkSoftwareGroups {
    <# Group names on the Software page, in first-appearance order. #>
    $groups = @()
    foreach ($key in (Get-FmkModuleKeys -Category 'Software')) {
        $group = $ModuleMeta[$key].Group
        if ($group -and ($groups -notcontains $group)) { $groups += $group }
    }
    return $groups
}

function Build-FmkSoftwareChips {
    <#
        The All + group chip bar above the Software grid. Chips are Buttons so
        they tab-focus and trigger on Enter/Space natively; selection rides on
        Tag ("active"), the same convention as the sidebar.
    #>
    param([Parameter(Mandatory)]$Sync)

    if (-not $Sync.SoftwareChips) { return }
    $Sync.SoftwareChips.Children.Clear()

    $names = @('All') + @(Get-FmkSoftwareGroups)
    foreach ($name in $names) {
        $chip = New-Object System.Windows.Controls.Button
        $chip.Content = $name
        $chip.Style = $Sync.FmkWindow.FindResource('ChipButton')
        # Empty Uid means All; Set-FmkSoftwareGroup normalises it to $null.
        $chip.Uid = if ($name -eq 'All') { '' } else { $name }
        $chip.Tag = if ((-not $Sync.SoftwareGroup -and $name -eq 'All') -or
            ($Sync.SoftwareGroup -and $Sync.SoftwareGroup -eq $name)) { 'active' } else { $null }
        [void]$chip.Add_Click({
                Set-FmkSoftwareGroup -Group $this.Uid -Sync $global:sync
            })
        [void]$Sync.SoftwareChips.Children.Add($chip)
    }
}

function Set-FmkSoftwareGroup {
    <#
        Selects a Software chip (empty means All), refreshes the chip states,
        and re-applies the filter. Search text is untouched, so chips and the
        search box combine: a card must match both.
    #>
    param(
        $Group = $null,
        [Parameter(Mandatory)]$Sync
    )

    if ([string]::IsNullOrEmpty($Group)) { $Group = $null }
    $Sync.SoftwareGroup = $Group

    foreach ($chip in $Sync.SoftwareChips.Children) {
        $chipGroup = $chip.Uid
        if ([string]::IsNullOrEmpty($chipGroup)) { $chipGroup = $null }
        $chip.Tag = if ($chipGroup -eq $Group) { 'active' } else { $null }
    }

    Apply-FmkFilter -Sync $Sync
}

function Build-FmkCards {
    param([Parameter(Mandatory)]$Sync)

    $Sync.CardSections = @{}

    foreach ($category in $FmkCategories) {
        $cardPanel = $Sync.FmkWindow.FindName("cards_$category")
        if (-not $cardPanel) { continue }

        $cardPanel.Children.Clear()
        $sections = New-Object System.Collections.ArrayList
        $Sync.CardSections[$category] = $sections

        # Short risk intro on pages that carry badges. Hovering a badge shows
        # the full breakdown; the header and Software action bar link the
        # complete Low/Medium/High criteria.
        if (-not (Test-FmkGridCategory -Category $category)) {
            $hasRated = $false
            foreach ($k in (Get-FmkModuleKeys -Category $category)) {
                $r = [string]$ModuleMeta[$k].Risk
                if ($r -eq 'Medium' -or $r -eq 'High') { $hasRated = $true; break }
            }
            if ($hasRated) {
                $intro = New-Object System.Windows.Controls.TextBlock
                $intro.Text = 'Risk badges mark Low, Medium, and High entries. Hover a badge for the reason; see Risk ratings? for the criteria.'
                $intro.FontSize = 11
                $intro.TextWrapping = [System.Windows.TextWrapping]::Wrap
                $intro.Margin = New-Object System.Windows.Thickness(2, 0, 0, 8)
                try {
                    if ($Sync.FmkWindow.Resources.Contains('FmkFgMuted')) {
                        $intro.Foreground = $Sync.FmkWindow.Resources['FmkFgMuted']
                    }
                }
                catch { }
                [void]$cardPanel.Children.Add($intro)
            }
        }

        # About page lead-in: product description, implemented features, and
        # support actions. The registry cards below it (repository, website,
        # shortcut) are preserved unchanged.
        if ($category -eq 'About') {
            [void]$cardPanel.Children.Add((New-FmkAboutPanel -Sync $Sync))
        }

        $isGrid = Test-FmkGridCategory -Category $category
        $currentGroup = $null
        $body = $null

        foreach ($key in (Get-FmkModuleKeys -Category $category)) {
            $meta = $ModuleMeta[$key]

            if ($meta.Group -and $meta.Group -ne $currentGroup) {
                $currentGroup = $meta.Group

                $heading = New-Object System.Windows.Controls.TextBlock
                $heading.Text = $currentGroup.ToUpperInvariant()
                $heading.Style = $Sync.FmkWindow.FindResource('SectionHeading')
                [void]$cardPanel.Children.Add($heading)

                $body = New-FmkSectionBody -Grid $isGrid
                [void]$cardPanel.Children.Add($body)

                # Kept so Apply-FmkFilter can hide a heading whose entries are
                # all filtered out -- walking the page's children instead would
                # mean re-deriving which heading belongs to which body.
                [void]$sections.Add(@{ Heading = $heading; Body = $body })
            }

            if (-not $body) { continue }

            $card = if ($isGrid) {
                New-FmkTile -Key $key -Sync $Sync
            }
            else {
                New-FmkCard -Key $key -Sync $Sync
            }
            [void]$body.Children.Add($card)
        }
    }

    Build-FmkSoftwareChips -Sync $Sync
}

function Build-FmkNav {
    param([Parameter(Mandatory)]$Sync)

    $Sync.NavPanel.Children.Clear()

    foreach ($category in $FmkCategories) {
        # @() because Get-FmkModuleKeys unrolls on return: one key comes back as
        # a bare string, none comes back as $null.
        if (@(Get-FmkModuleKeys -Category $category).Count -eq 0) { continue }

        $btn = New-Object System.Windows.Controls.Button
        $btn.Content = $category
        $btn.Style = $Sync.FmkWindow.FindResource('NavButton')
        # Uid = which page to show; Tag = selection marker read by the style.
        $btn.Uid = $category
        $btn.Add_Click({
                Set-FmkPage -Category $this.Uid -Sync $global:sync
            })

        [void]$Sync.NavPanel.Children.Add($btn)
    }
}

function Set-FmkPage {
    param(
        [Parameter(Mandatory)][string]$Category,
        [Parameter(Mandatory)]$Sync
    )

    foreach ($name in $FmkCategories) {
        $page = $Sync.FmkWindow.FindName("page_$name")
        if ($page) {
            $page.Visibility = if ($name -eq $Category) {
                [System.Windows.Visibility]::Visible
            }
            else {
                [System.Windows.Visibility]::Collapsed
            }
        }
    }

    foreach ($btn in $Sync.NavPanel.Children) {
        $btn.Tag = if ($btn.Uid -eq $Category) { 'active' } else { $null }
    }

    $Sync.ActiveCategory = $Category
    $Sync.SearchBox.Text = ''
    Apply-FmkFilter -Sync $Sync
}

function Apply-FmkFilter {
    <#
        Hides entries on the active page that do not match the search box and,
        on the Software page, the selected group chip. A card must match both.

        Hiding is all this does -- the panels reflow on their own. A Collapsed
        child is not measured, so the grid closes up around it and the matches
        move up to the first free slot without any element being recreated or
        reordered. That is also why the tiles carry their own size instead of the
        panel carrying an item size; see the tile metrics at the top of this file.

        Also resets the page's scroll offset when the query or the chip changes,
        so a filtered grid starts at the top rather than at whatever offset the
        unfiltered list was left at. The Software page scrolls an inner viewer
        (the chips stay put), so that viewer is preferred when it exists.
    #>
    param([Parameter(Mandatory)]$Sync)

    $category = $Sync.ActiveCategory
    if (-not $category) { return }

    $sections = $null
    if ($Sync.CardSections) { $sections = $Sync.CardSections[$category] }
    if (-not $sections) { return }

    $term = ''
    if ($Sync.SearchBox.Text) { $term = $Sync.SearchBox.Text.Trim().ToLowerInvariant() }

    $group = $null
    if ($Sync.SoftwareGroup -and (Test-FmkGridCategory -Category $category)) {
        $group = $Sync.SoftwareGroup
    }

    $visible = 0

    foreach ($section in $sections) {
        $hits = 0

        foreach ($card in $section.Body.Children) {
            $inGroup = (-not $group) -or ($ModuleMeta[$card.Uid].Group -eq $group)
            # Tiles keep the haystack in DataContext (Tag is the selection
            # marker); list cards keep it in Tag. Filtering only flips
            # Visibility, so selection survives search and chip changes.
            $haystack = $null
            try {
                if ($card -is [System.Windows.Controls.Button]) { $haystack = [string]$card.DataContext }
                else { $haystack = [string]$card.Tag }
            }
            catch { $haystack = $null }
            $match = $inGroup -and (($term -eq '') -or ($haystack -and $haystack.Contains($term)))
            $card.Visibility = if ($match) {
                [System.Windows.Visibility]::Visible
            }
            else {
                [System.Windows.Visibility]::Collapsed
            }
            if ($match) { $hits++ }
        }

        # A heading with nothing under it is noise, so it goes with its entries.
        # Collapsed rather than hidden so it takes no space in the StackPanel.
        $section.Heading.Visibility = if ($hits -gt 0) {
            [System.Windows.Visibility]::Visible
        }
        else {
            [System.Windows.Visibility]::Collapsed
        }

        $visible += $hits
    }

    if ((Test-FmkGridCategory -Category $category) -and $Sync.SoftwareCount) {
        $total = @(Get-FmkModuleKeys -Category $category).Count
        if (($term -eq '') -and (-not $group)) {
            $Sync.SoftwareCount.Text = "$total applications"
        }
        else {
            $Sync.SoftwareCount.Text = "$visible of $total applications"
        }
    }

    # Reset the scroll only when this page's filter state actually changed.
    # Comparing against the last applied state keeps a plain navigation click
    # from throwing away the offset a page was left at, while every keystroke,
    # every chip change -- and clearing the box -- starts the grid at the top.
    $terms = $Sync.FilterTerms
    if (-not $terms) {
        $terms = @{}
        $Sync.FilterTerms = $terms
    }

    $state = "$group`n$term"
    if (-not $terms.ContainsKey($category) -or $terms[$category] -ne $state) {
        $terms[$category] = $state
        $scroller = $Sync.FmkWindow.FindName("scroll_$category")
        if (-not $scroller -or -not $scroller.PSObject.Methods['ScrollToTop']) {
            $scroller = $Sync.FmkWindow.FindName("page_$category")
        }
        if ($scroller -and $scroller.PSObject.Methods['ScrollToTop']) {
            $scroller.ScrollToTop()
        }
    }

    if ($visible -eq 0) {
        # The grid pages list applications; the others list tasks.
        $Sync.EmptyPageNotice.Text = if (Test-FmkGridCategory -Category $category) {
            'No applications found'
        }
        else {
            'No modules match that filter.'
        }
        $Sync.EmptyPageNotice.Visibility = [System.Windows.Visibility]::Visible
    }
    else {
        $Sync.EmptyPageNotice.Visibility = [System.Windows.Visibility]::Collapsed
    }
}

# --- Software multi-select ----------------------------------------------------
# Selection order is the ArrayList order: entries are appended on select and
# removed on deselect, never sorted or re-derived. Filtering only flips
# Visibility, so the queue survives search and chip changes.

function Get-FmkSoftwareSelection {
    <# Ordered snapshot of selected Software keys. #>
    param([Parameter(Mandatory)]$Sync)
    if (-not $Sync.SoftwareSelection) { return @() }
    return @($Sync.SoftwareSelection)
}

function Update-FmkTileTooltip {
    param(
        [Parameter(Mandatory)]$Tile,
        [Parameter(Mandatory)]$Meta
    )
    $base = "Click to select $($Meta.Label)"
    try {
        if ($Tile.Tag -eq 'selected') { $base = "$($Meta.Label) (selected, click to deselect)" }
    }
    catch { }
    $riskTip = ''
    try { $riskTip = Get-FmkRiskTooltip -Meta $Meta } catch { $riskTip = '' }
    if ($riskTip) { $Tile.ToolTip = "$base`n$riskTip" }
    else { $Tile.ToolTip = $base }
}

function Update-FmkTileSelectionVisual {
    param(
        [Parameter(Mandatory)][string]$ActionKey,
        [Parameter(Mandatory)]$Sync
    )
    if (-not $Sync.CardSections) { return }
    $sections = $Sync.CardSections['Software']
    if (-not $sections) { return }
    $selected = $false
    if ($Sync.SoftwareSelection -and $Sync.SoftwareSelection.Contains($ActionKey)) { $selected = $true }
    foreach ($section in $sections) {
        foreach ($card in $section.Body.Children) {
            if ($card.Uid -ne $ActionKey) { continue }
            $card.Tag = if ($selected) { 'selected' } else { $null }
            try { Update-FmkTileTooltip -Tile $card -Meta $ModuleMeta[$ActionKey] } catch { }
        }
    }
}

function Update-FmkInstallButton {
    param([Parameter(Mandatory)]$Sync)
    $count = 0
    if ($Sync.SoftwareSelection) { $count = $Sync.SoftwareSelection.Count }
    if ($Sync.InstallSelectedButton) {
        $Sync.InstallSelectedButton.Content = if ($count -eq 0) { 'Install Selected (0)' } else { "Install Selected ($count)" }
        # Disabled when nothing is selected or a queue/single module is running.
        $busy = [bool]$Sync.Busy -or [bool]$Sync.QueueRunning
        $Sync.InstallSelectedButton.IsEnabled = ($count -gt 0) -and (-not $busy)
    }
    if ($Sync.ClearSelectionButton) {
        $busy = [bool]$Sync.Busy -or [bool]$Sync.QueueRunning
        $Sync.ClearSelectionButton.IsEnabled = ($count -gt 0) -and (-not $busy)
    }
    if ($Sync.SelectionStatus -and -not [bool]$Sync.QueueRunning) {
        if ($count -eq 0) {
            $Sync.SelectionStatus.Text = 'Click cards to select apps, then Install Selected.'
        }
        else {
            $names = @()
            foreach ($k in @(Get-FmkSoftwareSelection -Sync $Sync)) {
                if ($ModuleMeta.Contains($k)) { $names += $ModuleMeta[$k].Label }
            }
            $Sync.SelectionStatus.Text = "Selected ($count): " + ($names -join ', ')
        }
    }
}

function Toggle-FmkSoftwareSelection {
    param(
        [Parameter(Mandatory)][string]$ActionKey,
        [Parameter(Mandatory)]$Sync
    )
    if ([bool]$Sync.QueueRunning) {
        Write-Log 'A queue is already running; selection is locked until it finishes.' 'Warn'
        return $null
    }
    if ([bool]$Sync.Busy) {
        Write-Log "Already running: $($Sync.BusyLabel). Selection change ignored." 'Warn'
        return $null
    }
    if (-not $Sync.SoftwareSelection) {
        $Sync.SoftwareSelection = New-Object System.Collections.ArrayList
    }
    if ($Sync.SoftwareSelection.Contains($ActionKey)) {
        [void]$Sync.SoftwareSelection.Remove($ActionKey)
        Write-Log "Deselected: $($ModuleMeta[$ActionKey].Label)" 'Muted'
    }
    else {
        [void]$Sync.SoftwareSelection.Add($ActionKey)
        $pos = $Sync.SoftwareSelection.Count
        Write-Log "Selected (#$pos): $($ModuleMeta[$ActionKey].Label)" 'Muted'
    }
    Update-FmkTileSelectionVisual -ActionKey $ActionKey -Sync $Sync
    Update-FmkInstallButton -Sync $Sync
    return $null
}

function Clear-FmkSoftwareSelection {
    param([Parameter(Mandatory)]$Sync)
    if ([bool]$Sync.QueueRunning) { return }
    $keys = @(Get-FmkSoftwareSelection -Sync $Sync)
    if ($Sync.SoftwareSelection) { [void]$Sync.SoftwareSelection.Clear() }
    foreach ($k in $keys) { Update-FmkTileSelectionVisual -ActionKey $k -Sync $Sync }
    Update-FmkInstallButton -Sync $Sync
}

# ----------------------------------------------------------------------------
# source: 07-boot.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# BOOT
# ==============================================================================
# Loads the XAML, builds the $sync state object every other piece talks
# through, wires the chrome events, and shows the window.
#
# $sync is a [hashtable]::Synchronized() shared with the background runspaces --
# the same pattern WinUtil uses. Event handlers reach it through $global:sync,
# never through a captured local (PowerShell scriptblocks do not close over the
# scope they were created in).

function Get-FmkConsoleHandle {
    if (-not ('FmkNative.ConsoleHost' -as [type])) {
        Add-Type -Namespace FmkNative -Name ConsoleHost -MemberDefinition @'
[DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
[DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
'@
    }
    return [FmkNative.ConsoleHost]::GetConsoleWindow()
}

function Hide-FmkConsole {
    <# SW_HIDE. Called once the window is up so only the GUI is visible. #>
    try {
        $handle = Get-FmkConsoleHandle
        if ($handle -ne [IntPtr]::Zero) { [void][FmkNative.ConsoleHost]::ShowWindow($handle, 0) }
    }
    catch { }
}

function Show-FmkConsole {
    <# SW_SHOW. Restored on exit and on crash, so a failure is never silent. #>
    try {
        $handle = Get-FmkConsoleHandle
        if ($handle -ne [IntPtr]::Zero) { [void][FmkNative.ConsoleHost]::ShowWindow($handle, 5) }
    }
    catch { }
}

function New-FmkSyncState {
    <#
        Builds $sync and populates it from every x:Name in the XAML, so adding
        a named element to ui.xaml is enough to make it reachable as
        $sync.<Name> -- no second list to keep in step.
    #>
    param([Parameter(Mandatory)]$Window, [Parameter(Mandatory)][string]$Xaml)

    $sync = [hashtable]::Synchronized(@{})
    $sync.FmkWindow = $Window
    # Only ever touched on the UI thread, but the busy-state code walks it.
    $sync.RunButtons = New-Object System.Collections.ArrayList
    # Re-entrancy flag read by Invoke-FmkModule. Lives on $sync rather than in a
    # function-local because the click handlers are separate scopes.
    $sync.Busy = $false
    $sync.BusyLabel = $null
    # Filled by Build-FmkCards: category -> list of @{ Heading; Body } sections.
    $sync.CardSections = @{}
    # category -> the search term last applied to it, so Apply-FmkFilter can tell
    # a changed query (reset the scroll) from a plain page switch (keep it).
    $sync.FilterTerms = @{}
    $sync.ActiveCategory = $null
    # Selected Software group chip (unset means All). Lives on $sync so the
    # click handlers -- separate scopes that only see $global:sync -- can share
    # it with Apply-FmkFilter.
    $sync.SoftwareGroup = $null
    # Software multi-select queue. SoftwareSelection is an ArrayList whose order
    # IS the install order (append on select, remove on deselect). QueueRunning
    # plus Busy guards duplicate runs; QueueCancel lets Cancel skip pending
    # items after the current one finishes.
    $sync.SoftwareSelection = New-Object System.Collections.ArrayList
    $sync.QueueRunning = $false
    $sync.QueueCancel = $false
    # Queue progress accounting, read by Update-FmkObservedProgress: totals
    # and completed counts are task facts, never estimates.
    $sync.QueueTotal = 0
    $sync.QueueDone = 0
    $sync.ObservedItemPercent = -1
    $sync.ObservedItemSent = -1
    # Shared progress state, applied by Set-FmkBusyNow. Empty mode means
    # "decide from Busy": indeterminate while busy, hidden when idle.
    $sync.PendingProgressMode = ''
    $sync.PendingProgressValue = 0
    # Which palette was baked into the XAML. Set by Initialize-FmkUi; recorded
    # here because it is UI state, not because anything reads it back yet.
    $sync.Theme = $null
    $sync.Dialog = $null
    $sync.DialogResult = $false
    # Set by module actions that want to report what they changed.
    $sync.LastResult = $null

    foreach ($match in [regex]::Matches($Xaml, 'x:Name="([^"]+)"')) {
        $name = $match.Groups[1].Value
        $element = $Window.FindName($name)
        if ($element) { $sync[$name] = $element }
    }

    # --------------------------------------------------------------------------
    # Marshalling delegates.
    #
    # These are built HERE, on the UI thread, and stored on $sync so a background
    # runspace can call $window.Dispatcher.Invoke($sync.ActLogFlush).
    #
    # Why it matters: a scriptblock created in the runspace carries the
    # runspace's own session state, and invoking that delegate from the UI thread
    # would re-enter the very runspace that is currently blocked waiting on the
    # Invoke -- PowerShell session state is not thread-safe, so that is a
    # deadlock at best. Passing a plain .NET delegate that was compiled against
    # the UI thread's session state avoids the problem entirely: the runspace
    # only ever hands over an object reference.
    #
    # The delegates take no arguments by design. Everything they need is parked
    # on $sync by the caller first, which is also what makes them reusable.
    # --------------------------------------------------------------------------
    $sync.ActLogFlush = [action]{ Add-FmkLogLine -Text $global:sync.PendingLogText -ColorKey $global:sync.PendingLogColor }
    $sync.ActStatus = [action]{ Set-FmkStatusNow }
    $sync.ActBusy = [action]{ Set-FmkBusyNow }
    $sync.ActShowDialog = [action]{ New-FmkConfirmWindow }

    return $sync
}

function Set-FmkTitleBar {
    <#
        Paints the standard window chrome to match the palette.

        WinUtil keeps the ordinary title bar rather than drawing its own, and so
        do we -- but Windows draws that bar light unless asked otherwise, which
        leaves a white strip across the top of an otherwise dark window.
    #>
    param(
        [Parameter(Mandatory)]$Window,
        [bool]$Dark = $true
    )

    try {
        if (-not ('FmkNative.Dwm' -as [type])) {
            Add-Type -Namespace FmkNative -Name Dwm -MemberDefinition @'
[DllImport("dwmapi.dll")] public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int value, int size);
'@
        }

        # Creates the HWND if it does not exist yet, which is why this can run
        # before Show.
        $handle = (New-Object System.Windows.Interop.WindowInteropHelper($Window)).Handle
        if ($handle -eq [IntPtr]::Zero) { return }

        $value = if ($Dark) { 1 } else { 0 }
        # 20 is DWMWA_USE_IMMERSIVE_DARK_MODE from Win10 20H1 on. Builds in the
        # 17763..18984 window only understood 19, and return a failure code for
        # 20, so fall back rather than guessing the build.
        $hr = [FmkNative.Dwm]::DwmSetWindowAttribute($handle, 20, [ref]$value, 4)
        if ($hr -ne 0) { [void][FmkNative.Dwm]::DwmSetWindowAttribute($handle, 19, [ref]$value, 4) }
    }
    catch {
        # Cosmetic only: a light title bar is not worth failing startup over.
    }
}

function Initialize-FmkUi {
    param(
        [Parameter(Mandatory)][string]$Xaml,
        [string]$Version = '',
        [string]$IconPath = '',
        [ValidateSet('Dark', 'Light')][string]$Theme = 'Dark'
    )

    Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase -ErrorAction SilentlyContinue

    # The palette is substituted into the XAML text first, so the window is born
    # with its final colors. Applying a theme to a live window is not possible
    # here -- see the comment above the palette in ui.xaml.
    $themed = Get-FmkThemedXaml -Xaml $Xaml -Theme $Theme
    $window = [System.Windows.Markup.XamlReader]::Parse($themed)

    if ($IconPath -and (Test-Path -LiteralPath $IconPath)) {
        try {
            # OnLoad decodes eagerly and releases the file: the embedded icon
            # is rewritten to temp on every launch, so a lingering read lock
            # here would break the next startup. This Icon feeds the title bar
            # and the taskbar button.
            $iconUri = New-Object System.Uri($IconPath)
            $window.Icon = [System.Windows.Media.Imaging.BitmapFrame]::Create(
                $iconUri,
                [System.Windows.Media.Imaging.BitmapCreateOptions]::None,
                [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
        }
        catch { }
    }

    $sync = New-FmkSyncState -Window $window -Xaml $Xaml
    $sync.Theme = $Theme
    # Must be global before anything can log or marshal a call.
    $global:sync = $sync

    if ($Version -and $sync.VersionBadge) { $sync.VersionBadge.Text = "v$Version" }

    Build-FmkNav -Sync $sync
    Build-FmkCards -Sync $sync
    Set-FmkPage -Category $FmkCategories[0] -Sync $sync
    try { Update-FmkInstallButton -Sync $sync } catch { }

    # --- chrome events --------------------------------------------------------
    $sync.SearchBox.Add_TextChanged({
            Apply-FmkFilter -Sync $global:sync
        })

    # Software multi-select action bar. Handlers read $global:sync, never
    # locals, because scriptblocks do not close over the creating scope.
    try {
        if ($sync.InstallSelectedButton) {
            $sync.InstallSelectedButton.Add_Click({
                    [void](Invoke-FmkSoftwareQueue -Sync $global:sync)
                })
        }
        if ($sync.ClearSelectionButton) {
            $sync.ClearSelectionButton.Add_Click({
                    Clear-FmkSoftwareSelection -Sync $global:sync
                })
        }
        # The overlay Cancel: visible only while the queue runs (the one
        # safely cancellable task). Handlers read $global:sync, never locals,
        # because scriptblocks do not close over the creating scope.
        if ($sync.TaskCancelButton) {
            $sync.TaskCancelButton.Add_Click({
                    Request-FmkQueueCancel -Sync $global:sync
                })
        }
        if ($sync.RiskHelpButton) {
            $sync.RiskHelpButton.Add_Click({ Show-FmkRiskHelp })
        }
        if ($sync.GlobalRiskHelpButton) {
            $sync.GlobalRiskHelpButton.Add_Click({ Show-FmkRiskHelp })
        }
    }
    catch { }

    # Title bar colour. On SourceInitialized rather than before Show: the
    # attribute is dropped if it is set on an HWND DWM has not composited yet,
    # which is the state the window is in until it is shown.
    $window.Add_SourceInitialized({
            Set-FmkTitleBar -Window $this -Dark ($global:sync.Theme -eq 'Dark')
            # Keep the window inside the work area (taskbar excluded) at any DPI.
            # WPF units are device-independent, and WorkArea is reported in the
            # same units, so no manual DPI math is needed. Only shrink, never
            # grow: the XAML size stands on large displays, and the user can
            # still resize (ResizeMode stays CanResize).
            try {
                $area = [System.Windows.SystemParameters]::WorkArea
                if ($this.Width -gt $area.Width) { $this.Width = $area.Width }
                if ($this.Height -gt $area.Height) { $this.Height = $area.Height }
                if ($this.MaxWidth -gt $area.Width -or $this.MaxWidth -le 0) { $this.MaxWidth = $area.Width }
                if ($this.MaxHeight -gt $area.Height -or $this.MaxHeight -le 0) { $this.MaxHeight = $area.Height }
            }
            catch { }
        })

    # Console collapse. The row height is what sizes the pane -- collapsing the
    # RichTextBox instead would leave the 150px row standing empty.
    $sync.LogToggle.Add_Click({
            $row = $global:sync.RootGrid.RowDefinitions[2]
            if ($row.Height.Value -gt 40) {
                $row.Height = New-Object System.Windows.GridLength(32)
                # Up arrow: the pane is closed, so the button offers to open it.
                $global:sync.LogToggle.Content = [string][char]0x25B2
            }
            else {
                $row.Height = New-Object System.Windows.GridLength(150)
                $global:sync.LogToggle.Content = [string][char]0x25BC
            }
        })

    $window.Add_Closing({
            try { Export-SessionResults } catch { }
        })

    $window.Add_Closed({
            Show-FmkConsole
        })

    Write-Log "FreeMixKit v$Version started." "Success"
    Write-Log "OS: $($SysInfo.OS) | CPU: $($SysInfo.CPU) | RAM: $($SysInfo.RAM)" "Info"

    Hide-FmkConsole
    try {
        [void]$window.ShowDialog()
    }
    finally {
        # Also covers the path where ShowDialog throws rather than closing.
        Show-FmkConsole
        $global:sync = $null
    }
}

# ----------------------------------------------------------------------------
# source: 08-risk.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# RISK ASSESSMENT
# ==============================================================================
# Consistent risk-rating criteria for applicable tools. Ratings explain the
# potential consequences of using a tool (technical safety, system changes,
# privacy, source trustworthiness, licensing or service-policy concerns).
# They are guidance, not a guarantee of safety.
#
# Levels: None (untagged, no meaningful warning), Low, Medium, High.
# Low, Medium, and High each get a badge in their own color; None draws
# nothing. Untagged stays untagged -- Low is never assigned just to show
# a badge.
#
# Dimensions stored per entry (see Register-Module defaults in 02-registry):
#   RiskTechnical  - could it damage the system, compromise security, lose data?
#   RiskSource     - is the download source authentic and trustworthy?
#   RiskPrivacy    - does it collect, expose, or transmit sensitive info?
#   RiskLicense    - could use violate terms, license, or agreements?
#   RiskPrivileges - does it need admin / make substantial system changes?
# Licensing alone never makes High; High needs technical-danger evidence.

$FmkRiskHelpTitle = 'Risk ratings'

$FmkRiskHelpText = @'
Risk ratings explain the potential consequences of using a tool. They consider technical safety, system changes, privacy, source trustworthiness, and licensing or service-policy concerns. They are guidance, not a guarantee of safety.

LOW: Limited or well-understood risk. Well-understood functionality, limited and predictable system changes, credible source with reasonable maintenance, no identified significant security concern. Licensing or service-policy concerns may still exist even when technical risk is low.

MEDIUM: Meaningful caveats or elevated risk. Significant system modifications, admin operations with meaningful consequences, changes that could break software or affect stability, unclear maintenance or limited verification, substantial privacy implications, or uncertain compatibility or licensing consequences.

HIGH: Significant risk or serious consequences. Unverified executables from suspicious sources, tools that disable security controls, destructive operations without safeguards, credential theft or covert surveillance, high-impact modifications that could compromise integrity, or serious well-supported evidence of malicious behavior. A licensing concern alone never makes High.

Untagged entries need no warning: ordinary installs from verified sources with predictable behavior.
'@

$FmkRiskLevelOrder = @{ None = 0; Low = 1; Medium = 2; High = 3 }

function Get-FmkRiskTooltip {
    <#
        Multi-line tooltip for a badge or tile: level, short reason, then any
        dimensions that are set, plus evidence and review date. Returns "" for
        untagged entries so callers can skip the tooltip.
    #>
    param([Parameter(Mandatory)]$Meta)

    $risk = [string]$Meta.Risk
    if (-not $risk -or $risk -eq 'None' -or $risk -eq 'Normal') { return '' }

    $lines = @("Risk: $risk")
    if ($Meta.RiskReason) { $lines += [string]$Meta.RiskReason }
    if ($Meta.RiskTechnical) { $lines += "Technical: $($Meta.RiskTechnical)" }
    if ($Meta.RiskSource) { $lines += "Source: $($Meta.RiskSource)" }
    if ($Meta.RiskPrivacy) { $lines += "Privacy: $($Meta.RiskPrivacy)" }
    if ($Meta.RiskLicense) { $lines += "Policy: $($Meta.RiskLicense)" }
    if ($Meta.RiskPrivileges) { $lines += "Privileges: $($Meta.RiskPrivileges)" }
    if ($Meta.RiskEvidence) { $lines += "Ref: $($Meta.RiskEvidence)" }
    if ($Meta.RiskReviewed) { $lines += "Reviewed: $($Meta.RiskReviewed)" }
    return ($lines -join "`n")
}

function Test-FmkRiskBadgeVisible {
    <#
        Whether a risk level draws a badge. Pure rule, shared by the badge
        builder so the condition lives in exactly one place: Low, Medium, and
        High are badged; None (and anything unknown) is not.
    #>
    param([string]$Risk)
    return ($Risk -eq 'Low' -or $Risk -eq 'Medium' -or $Risk -eq 'High')
}

function Get-FmkRiskShort {
    <# One-line "LEVEL - reason" for queue summaries and log lines. #>
    param([Parameter(Mandatory)]$Meta)
    if ($Meta.RiskReason) { return "$($Meta.Risk): $($Meta.RiskReason)" }
    return [string]$Meta.Risk
}

function Test-FmkRiskNeedsConfirm {
    <# True for High entries: queue must require explicit confirmation. #>
    param([Parameter(Mandatory)]$Meta)
    return ([string]$Meta.Risk -eq 'High')
}

function Show-FmkRiskHelp {
    <#
        Risk-rating explainer dialog. Runs on the UI thread via the shared
        confirm dialog so no new window chrome is needed.
    #>
    $text = $FmkRiskHelpText
    if ($global:sync -and $global:sync.FmkWindow) {
        [void](Show-FmkConfirmDialog -Message $text -Title $FmkRiskHelpTitle -ConfirmText 'OK' -CancelText 'Close')
        return
    }
    Write-Host $text
}

# ----------------------------------------------------------------------------
# source: 09-queue.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# SOFTWARE INSTALLATION QUEUE
# ==============================================================================
# Runs the Software multi-select in selection order, one module at a time.
# Order is the SoftwareSelection ArrayList order (see 06-cards.ps1), never
# sorted or re-derived. Filtering never mutates the selection.
#
# Safety: Medium/High entries get one combined pre-install review showing each
# item's reason; any High item requires explicit confirmation. Low/None items
# never force per-item popups. Windows security (UAC, signatures) is never
# bypassed. Failures continue to the next item; nothing retries forever and a
# failure never silently swaps in an unrelated installer.

function Get-FmkQueueRiskItems {
    param(
        [Parameter(Mandatory)][string[]]$Keys
    )
    $items = @()
    foreach ($k in $Keys) {
        if (-not $ModuleMeta.Contains($k)) { continue }
        $meta = $ModuleMeta[$k]
        $risk = [string]$meta.Risk
        if ($risk -eq 'Medium' -or $risk -eq 'High') { $items += $meta }
    }
    return $items
}

function Confirm-FmkQueueRisks {
    <#
        One combined review for the queue's Medium/High items. Returns $true to
        proceed, $false to cancel. High items require explicit confirmation via
        the dialog's Continue path; the message names each High concern.
    #>
    param(
        [Parameter(Mandatory)][string[]]$Keys
    )
    $risky = @(Get-FmkQueueRiskItems -Keys $Keys)
    if ($risky.Count -eq 0) { return $true }

    $lines = @('The selection includes rated items:')
    $hasHigh = $false
    foreach ($m in $risky) {
        $short = ''
        try { $short = Get-FmkRiskShort -Meta $m } catch { $short = "$($m.Risk)" }
        $lines += "- $($m.Label): $short"
        if ([string]$m.Risk -eq 'High') { $hasHigh = $true }
    }
    if ($hasHigh) {
        $lines += ''
        $lines += 'High-risk items require explicit confirmation. Continue only if you accept the specific concerns above.'
    }
    else {
        $lines += ''
        $lines += 'Continue with the installation queue?'
    }
    $msg = $lines -join "`n"
    return (Show-FmkConfirmDialog -Message $msg -Title 'Review rated items' -ConfirmText 'Continue' -CancelText 'Cancel')
}

function Invoke-FmkSoftwareQueue {
    <#
        UI entry point for Install Selected. Guards against duplicate runs via
        QueueRunning plus the shared Busy flag, snapshots the order up front,
        installs sequentially, supports Cancel for pending items, and reports a
        success/failed/cancelled summary with failure details in the log.
    #>
    param([Parameter(Mandatory)]$Sync)

    if ([bool]$Sync.QueueRunning) {
        Write-Log 'Install queue is already running; ignoring duplicate request.' 'Warn'
        return $null
    }
    if ([bool]$Sync.Busy) {
        Write-Log "Already running: $($Sync.BusyLabel). Queue request ignored." 'Warn'
        return $null
    }

    $keys = @(Get-FmkSoftwareSelection -Sync $Sync)
    if ($keys.Count -eq 0) { return $null }

    # Snapshot the order: later selection toggles must not mutate a running queue.
    $queue = @($keys)

    if (-not (Confirm-FmkQueueRisks -Keys $queue)) {
        Write-Log 'Queue canceled at the risk review.' 'Warn'
        return $null
    }

    $Sync.QueueRunning = $true
    $Sync.QueueCancel = $false
    $Sync.Busy = $true
    $Sync.BusyLabel = 'Install queue'
    $Sync.QueueTotal = $queue.Count
    $Sync.QueueDone = 0
    $Sync.ObservedItemPercent = -1
    $Sync.ObservedItemSent = -1
    Update-FmkInstallButton -Sync $Sync
    Write-Log "Queue: preparing $($queue.Count) app(s)" 'Muted'
    Set-FmkBusy -Busy $true -Text "Queue: preparing $($queue.Count) app(s)" -Percent 0

    $ok = 0
    $failed = 0
    $cancelled = 0
    $failures = @()
    $total = $queue.Count
    $index = 0

    try {
        foreach ($key in $queue) {
            $index++
            if ([bool]$Sync.QueueCancel) {
                # Remaining items count as cancelled, including this one.
                $cancelled = $total - $index + 1
                Write-Log "Queue canceled by user; $cancelled pending item(s) skipped." 'Warn'
                break
            }

            $label = $key
            if ($ModuleMeta.Contains($key)) { $label = $ModuleMeta[$key].Label }
            # Step/total status with the completed-task floor as determinate
            # progress through the one shared mechanism. Observed installer
            # percentages refine it within the item when the output carries
            # any; otherwise the floor stands with the waiting message.
            $Sync.QueueDone = $index - 1
            $Sync.ObservedItemPercent = -1
            $Sync.ObservedItemSent = -1
            $statusMsg = "Installing $label ($index of $total)"
            Write-Log $statusMsg 'Muted'
            Set-FmkBusy -Busy $true -Text $statusMsg -Percent ([double](100 * ($index - 1) / $total))
            if ($Sync.SelectionStatus) {
                $Sync.SelectionStatus.Text = "$statusMsg..."
            }

            $result = $null
            try {
                $result = Invoke-FmkRunspace -ActionKey $key -Sync $Sync
            }
            catch {
                $result = [pscustomobject]@{
                    Status        = 'Failed'
                    Message       = $_.Exception.Message
                    Duration      = [timespan]::Zero
                    RollbackHint  = ''
                    PreviousState = ''
                }
            }

            if (-not $result -or -not $result.PSObject.Properties['Status']) {
                $result = [pscustomobject]@{
                    Status        = 'Failed'
                    Message       = 'Module produced no result object.'
                    Duration      = [timespan]::Zero
                    RollbackHint  = ''
                    PreviousState = ''
                }
            }

            $rb = ''
            try { $rb = Get-ModuleMetaValue -ActionKey $key -Name 'RollbackHint' -DefaultValue '' } catch { $rb = '' }
            if (-not $rb -and $result.PSObject.Properties['RollbackHint']) { $rb = [string]$result.RollbackHint }
            $prev = ''
            if ($result.PSObject.Properties['PreviousState']) { $prev = [string]$result.PreviousState }
            $dur = [timespan]::Zero
            if ($result.PSObject.Properties['Duration'] -and $result.Duration -is [timespan]) { $dur = $result.Duration }

            Add-ModuleResult -Module $key -Status $result.Status -Message $result.Message -Duration $dur -RollbackHint $rb -PreviousState $prev

            if ($result.Status -eq 'Success') {
                $ok++
                Write-Log "Queue: $label installed ($index/$total)." 'Success'
            }
            elseif ($result.Status -eq 'Canceled') {
                $cancelled++
                Write-Log "Queue: $label canceled ($index/$total)." 'Warn'
            }
            else {
                $failed++
                $failures += "$label`: $($result.Message)"
                Write-Log "Queue: $label failed ($index/$total) - $($result.Message)" 'Error'
            }
        }
    }
    finally {
        # Guaranteed restore: the overlay, progress bar, and interaction lock
        # all clear here even when a step throws or the user cancels.
        $Sync.QueueRunning = $false
        $Sync.QueueCancel = $false
        $Sync.Busy = $false
        $Sync.BusyLabel = $null
        Set-FmkBusy -Busy $false
        Update-FmkInstallButton -Sync $Sync
    }

    $summary = "Queue finished: $ok installed, $failed failed, $cancelled cancelled (of $total)."
    if ($failed -eq 0 -and $cancelled -eq 0) {
        Write-Log $summary 'Success'
        Set-FmkTaskComplete -Status 'Success'
        Set-FmkStatus "Completed: $ok of $total installed." 'FmkRiskLow'
    }
    elseif ($failed -gt 0) {
        Write-Log $summary 'Error'
        Set-FmkTaskComplete -Status 'Failed'
        Set-FmkStatus 'Finished with errors -- see output.' 'FmkRiskHigh'
    }
    else {
        Write-Log $summary 'Warn'
        Set-FmkTaskComplete -Status 'Cancelled'
        Set-FmkStatus 'Queue canceled.' 'FmkRiskMed'
    }
    foreach ($f in $failures) { Write-Log "Failed: $f" 'Error' }
    if ($Sync.SelectionStatus) { $Sync.SelectionStatus.Text = $summary }

    if ($failures.Count -gt 0) {
        $detail = $summary + "`n`nFailures:`n- " + ($failures -join "`n- ") + "`n`nSee the output pane for details."
        [void](Show-FmkConfirmDialog -Message $detail -Title 'Queue finished' -ConfirmText 'OK' -CancelText 'Close')
    }

    return [pscustomobject]@{
        Total     = $total
        Success   = $ok
        Failed    = $failed
        Cancelled = $cancelled
        Failures  = $failures
    }
}

function Request-FmkQueueCancel {
    param([Parameter(Mandatory)]$Sync)
    if (-not [bool]$Sync.QueueRunning) { return }
    $Sync.QueueCancel = $true
    Write-Log 'Cancel requested; finishing the current install, then stopping.' 'Warn'
}

# ----------------------------------------------------------------------------
# source: 10-support.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# ABOUT, ISSUE REPORTING, AND DIAGNOSTIC LOG SHARING
# ==============================================================================
# The About page lead-in (built by New-FmkAboutPanel, called from
# Build-FmkCards) plus the two support actions behind its buttons. Both actions
# run on the UI thread from button clicks -- they are plain functions, not
# $Modules entries, so they never enter the background runspace machinery and
# never touch the busy state.
#
# URLs come from $FmkRepoUrl (src/w.template.ps1), the single source of truth
# for the project repository. Nothing here guesses a URL.

function New-FmkAboutPanel {
    <#
        The About page lead-in: what Free Mix Kit is, what this version can
        actually do, and the support buttons. Descriptions cover only
        implemented capabilities.
    #>
    param([Parameter(Mandatory)]$Sync)

    $resources = $Sync.FmkWindow.Resources
    $muted = $null
    try {
        if ($resources.Contains('FmkFgMuted')) { $muted = $resources['FmkFgMuted'] }
    }
    catch { }

    $panel = New-Object System.Windows.Controls.StackPanel
    $panel.Margin = New-Object System.Windows.Thickness(2, 0, 0, 4)

    $title = New-Object System.Windows.Controls.TextBlock
    $title.Text = 'About Free Mix Kit'
    $title.FontSize = 14
    $title.FontWeight = [System.Windows.FontWeights]::Bold
    $title.Margin = New-Object System.Windows.Thickness(0, 0, 0, 6)
    [void]$panel.Children.Add($title)

    $blurb = New-Object System.Windows.Controls.TextBlock
    $blurb.Text = 'Free Mix Kit is a PowerShell-based Windows utility that helps you discover and install supported software, run available system utilities, and access useful Windows maintenance and configuration tools from one interface.'
    $blurb.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $blurb.Margin = New-Object System.Windows.Thickness(0, 0, 0, 6)
    if ($muted) { $blurb.Foreground = $muted }
    [void]$panel.Children.Add($blurb)

    $featHead = New-Object System.Windows.Controls.TextBlock
    $featHead.Text = 'Features'
    $featHead.FontWeight = [System.Windows.FontWeights]::SemiBold
    $featHead.Margin = New-Object System.Windows.Thickness(0, 6, 0, 2)
    [void]$panel.Children.Add($featHead)

    $features = @(
        'Software catalog: search, filter, select several applications, and install them in order with Install Selected.',
        'System cleanup and repair: junk cleanup, SFC/DISM repair, malware scans, and system reports.',
        'Utilities and fixes, including Windows tweak launchers.',
        'Activation helpers with risk ratings and explicit confirmations.',
        'Risk badges with per-item explanations, live search, and a streaming output log.'
    )
    foreach ($f in $features) {
        $item = New-Object System.Windows.Controls.TextBlock
        # ASCII hyphen, not a Unicode bullet: the built script ships without a
        # BOM, so a non-ASCII glyph depends on file encoding, host-codepage
        # script parsing, and font coverage all agreeing. A hyphen matches the
        # list style used everywhere else in the app (queue summaries, etc.).
        $item.Text = "- $f"
        $item.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $item.Margin = New-Object System.Windows.Thickness(8, 0, 0, 2)
        if ($muted) { $item.Foreground = $muted }
        [void]$panel.Children.Add($item)
    }

    $srcLine = New-Object System.Windows.Controls.TextBlock
    $srcLine.Text = "Source code: $FmkRepoUrl"
    $srcLine.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $srcLine.Margin = New-Object System.Windows.Thickness(0, 8, 0, 2)
    if ($muted) { $srcLine.Foreground = $muted }
    [void]$panel.Children.Add($srcLine)

    $row = New-Object System.Windows.Controls.StackPanel
    $row.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $row.Margin = New-Object System.Windows.Thickness(0, 8, 0, 10)

    $report = New-Object System.Windows.Controls.Button
    $report.Content = 'Report an Issue'
    $report.Style = $Sync.FmkWindow.FindResource('GhostButton')
    $report.Margin = New-Object System.Windows.Thickness(0, 0, 8, 0)
    $report.ToolTip = 'Open the official GitHub Issues page in your browser'
    # [void]: Add_Click returns a value that must not reach the pipeline.
    [void]$report.Add_Click({ [void](Open-FmkIssuesPage) })
    [void]$row.Children.Add($report)

    $share = New-Object System.Windows.Controls.Button
    $share.Content = 'Share Logs'
    $share.Style = $Sync.FmkWindow.FindResource('GhostButton')
    $share.ToolTip = 'Save sanitized diagnostics to attach to a bug report'
    [void]$share.Add_Click({ [void](Export-FmkDiagnosticLog) })
    [void]$row.Children.Add($share)

    [void]$panel.Children.Add($row)
    return $panel
}

function Get-FmkIssuesUrl {
    <# The official Issues page, derived from the single repo-URL source. #>
    return "$FmkRepoUrl/issues"
}

function Open-FmkIssuesPage {
    <#
        Opens the official GitHub Issues page. Never submits anything: the
        user files the issue themselves. A failed launch shows the URL to
        copy instead of failing silently.
    #>
    $url = Get-FmkIssuesUrl
    try {
        Start-Process $url | Out-Null
        Write-Log "Opened: $url" 'Info'
        return $true
    }
    catch {
        $msg = "Could not open the browser. Copy this URL manually:`n$url"
        if ($global:sync -and $global:sync.FmkWindow) {
            [void](Show-FmkConfirmDialog -Message $msg -Title 'Report an Issue' -ConfirmText 'OK' -CancelText 'Close')
        }
        else {
            Write-Host $msg
        }
        return $false
    }
}

function Protect-FmkLogSecrets {
    <#
        Redacts likely secrets from diagnostic text before export: key/value
        secrets (password, token, API key, ...), bearer tokens, and private
        key blocks. Pure function -- safe to unit test headlessly.
    #>
    param([string]$Text)

    if (-not $Text) { return '' }
    $out = $Text
    $out = [regex]::Replace($out,
        '(?i)(password|passwd|pwd|secret|api[-_]?key|access[-_]?token|auth[-_]?token|client[-_]?secret)(\s*[:=]\s*)([^\s,;"]+)',
        '$1$2[REDACTED]')
    $out = [regex]::Replace($out,
        '(?i)(Bearer\s+)([A-Za-z0-9\-._~+/=]{8,})',
        '$1[REDACTED]')
    $out = [regex]::Replace($out,
        '(?is)(-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----).+?(-----END [A-Z0-9 ]*PRIVATE KEY-----)',
        '$1 [REDACTED] $2')
    return $out
}

function Export-FmkDiagnosticLog {
    <#
        Sanitized diagnostics export for bug reports. Collects the app version,
        timestamp, OS, recorded task results, and the session-log tail the app
        already retains -- nothing else, no credentials, no unrelated files.
        The user picks the save location; nothing is uploaded anywhere. The
        user attaches the file to a GitHub issue themselves.
    #>
    param(
        [string[]]$SessionLog = $null,
        [object[]]$Results = $null,
        [string]$SavePath = ''
    )

    if ($null -eq $SessionLog) {
        $SessionLog = @()
        try {
            if (Test-Path -LiteralPath $SessionLogPath) {
                $SessionLog = @(Get-Content -LiteralPath $SessionLogPath -Tail 300 -ErrorAction Stop)
            }
        }
        catch { $SessionLog = @() }
    }
    if ($null -eq $Results) {
        $Results = @()
        try { $Results = @($ModuleResults) } catch { $Results = @() }
    }

    if ((@($SessionLog).Count -eq 0) -and (@($Results).Count -eq 0)) {
        $msg = 'No diagnostic logs are available yet. Run a task first, then try Share Logs again.'
        if ($global:sync -and $global:sync.FmkWindow) {
            [void](Show-FmkConfirmDialog -Message $msg -Title 'Share Logs' -ConfirmText 'OK' -CancelText 'Close')
        }
        else {
            Write-Host $msg
        }
        return $null
    }

    if (-not $SavePath) {
        # Save dialog must run on the UI thread; this function is only ever
        # reached from a button click, which already is the UI thread.
        try {
            $dlg = New-Object Microsoft.Win32.SaveFileDialog
            $dlg.Filter = 'Text files (*.txt)|*.txt|Log files (*.log)|*.log'
            $dlg.FileName = "FreeMixKit-Diagnostics-$(Get-Date -Format 'yyyyMMdd_HHmmss').txt"
            $picked = $dlg.ShowDialog()
            if (-not $picked) { return $null }
            $SavePath = $dlg.FileName
        }
        catch {
            $msg = "Could not open the save dialog: $($_.Exception.Message)"
            if ($global:sync -and $global:sync.FmkWindow) {
                [void](Show-FmkConfirmDialog -Message $msg -Title 'Share Logs' -ConfirmText 'OK' -CancelText 'Close')
            }
            else {
                Write-Host $msg
            }
            return $null
        }
    }

    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('FreeMixKit diagnostic log')
    [void]$lines.Add("Generated: $((Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ'))")
    try { [void]$lines.Add("App version: v$AppVersion") } catch { }
    try { [void]$lines.Add("OS: $($SysInfo.OS)") } catch { }
    [void]$lines.Add("Tasks recorded: $(@($Results).Count)")
    [void]$lines.Add('')
    [void]$lines.Add('---- Task results ----')
    if (@($Results).Count -eq 0) {
        [void]$lines.Add('(no tasks recorded this session)')
    }
    else {
        foreach ($r in @($Results)) {
            try {
                [void]$lines.Add(("[{0}] Module={1} Status={2} Duration={3}s Message={4}" -f
                        $r.Timestamp, $r.Module, $r.Status, $r.DurationSec, $r.Message))
            }
            catch { }
        }
    }
    [void]$lines.Add('')
    [void]$lines.Add('---- Session log tail (sanitized) ----')
    if (@($SessionLog).Count -eq 0) {
        [void]$lines.Add('(session log unavailable)')
    }
    else {
        foreach ($line in @($SessionLog)) { [void]$lines.Add([string]$line) }
    }

    $body = Protect-FmkLogSecrets -Text ($lines -join "`r`n")
    try {
        [System.IO.File]::WriteAllText($SavePath, $body, (New-Object System.Text.UTF8Encoding($false)))
    }
    catch {
        $msg = "Could not write the log file: $($_.Exception.Message)"
        if ($global:sync -and $global:sync.FmkWindow) {
            [void](Show-FmkConfirmDialog -Message $msg -Title 'Share Logs' -ConfirmText 'OK' -CancelText 'Close')
        }
        else {
            Write-Host $msg
        }
        return $null
    }

    Write-Log "Diagnostics saved to: $SavePath" 'Success'
    if ($global:sync -and $global:sync.FmkWindow) {
        $confirm = Show-FmkConfirmDialog -Message "Saved to:`n$SavePath`n`nAttach it manually to a new GitHub issue." -Title 'Share Logs' -ConfirmText 'Open Issues' -CancelText 'Close'
        if ($confirm) { [void](Open-FmkIssuesPage) }
    }
    return $SavePath
}

# ----------------------------------------------------------------------------
# source: 11-sysreport.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# SYSTEM REPORT -- data collection service
# ==============================================================================
# One shared service behind the System Report module action, which writes the
# full report to a text file. Built-in Windows interfaces only (CIM/WMI,
# registry, inbox cmdlets and commands): no installs, no drivers, no services,
# no configuration changes, and no separate PowerShell process per field --
# one collection pass gathers everything, section by section. The application
# UI stays a button workflow: Run generates the file, nothing renders the
# report on screen.
#
# Robustness contract: every data source is optional. A failed query, a
# missing property, a permission denial, or unsupported hardware produces an
# 'Unavailable' / 'Not supported' / 'Access denied' value plus a section
# warning -- never an exception, and never a hole that stops the rest of the
# report. Missing information is never rendered as zero.
#
# Privacy contract: product keys are never collected. Hardware serial numbers,
# MAC addresses, and IP addresses are collected with Sensitivity='Private'
# and hidden unless an export explicitly includes them. Computer and user
# names are Sensitivity='Identifying': shown on screen (the label says so)
# but withheld from exports unless included.
#
# ASCII only in this file: the build ships UTF-8 without a BOM, and non-ASCII
# glyphs depend on host-codepage parsing and font coverage agreeing.

$FmkSysMissing = 'Unavailable'

function Read-FmkCim {
    <#
        One guarded CIM query. Always returns an array (possibly empty) or
        $null when the class, namespace, provider, or permissions are
        unavailable. The -NoEnumerate is load-bearing: a bare return would
        unroll a single-instance result into a bare object, and every
        `$x.Count` downstream would then throw under strict mode.
    #>
    param(
        [Parameter(Mandatory)][string]$Class,
        [string]$Namespace = 'root/cimv2',
        [string]$Filter = ''
    )
    try {
        if ($Filter -ne '') {
            $found = @(Get-CimInstance -ClassName $Class -Namespace $Namespace -Filter $Filter -ErrorAction Stop)
        }
        else {
            $found = @(Get-CimInstance -ClassName $Class -Namespace $Namespace -ErrorAction Stop)
        }
        Write-Output $found -NoEnumerate
        return
    }
    catch { return $null }
}

function Get-FmkSysField {
    <#
        First present, non-blank property value, else the Missing fallback.
        Numeric zero and $false are real values and pass through untouched.
        Missing is deliberately untyped so callers can pass $null or @() as
        the "nothing there" sentinel for their own $null checks.
    #>
    param($Object, [Parameter(Mandatory)][string[]]$Names, $Missing = 'Unavailable')
    try {
        if ($null -eq $Object) { return $Missing }
        foreach ($n in $Names) {
            $v = $Object.$n
            if ($null -ne $v -and "$v" -ne '') { return $v }
        }
    }
    catch { }
    return $Missing
}

function New-FmkSysSection {
    param([Parameter(Mandatory)][string]$Key, [Parameter(Mandatory)][string]$Title)
    return @{
        Key      = $Key
        Title    = $Title
        Rows     = (New-Object System.Collections.ArrayList)
        Warnings = (New-Object System.Collections.ArrayList)
    }
}

function Add-FmkSysRow {
    <#
        Appends a Label/Value row. $null and blank become 'Unavailable';
        numeric zero and $false are kept as real values.
    #>
    param($Section, [Parameter(Mandatory)][string]$Label, $Value, [string]$Sensitivity = 'None')
    $text = 'Unavailable'
    try {
        if ($null -ne $Value -and "$Value" -ne '') { $text = [string]$Value }
    }
    catch { }
    [void]$Section.Rows.Add(@{ Label = $Label; Value = $text; Sensitivity = $Sensitivity })
}

function Add-FmkSysWarning {
    param($Section, [Parameter(Mandatory)][string]$Text)
    [void]$Section.Warnings.Add($Text)
}

function Find-FmkSysRow {
    <# Row Value by label from a finished section, or '' when absent. #>
    param($Section, [Parameter(Mandatory)][string]$Label)
    try {
        foreach ($row in @($Section.Rows)) {
            if ($row.Label -eq $Label) { return [string]$row.Value }
        }
    }
    catch { }
    return ''
}

function Format-FmkBytes {
    param($Bytes)
    try {
        $b = [double]$Bytes
        if ($b -lt 0) { return 'Unavailable' }
        if ($b -ge 1GB) { return ('{0:N1} GB' -f ($b / 1GB)) }
        if ($b -ge 1MB) { return ('{0:N1} MB' -f ($b / 1MB)) }
        if ($b -ge 1KB) { return ('{0:N1} KB' -f ($b / 1KB)) }
        return ('{0:N0} B' -f $b)
    }
    catch { return 'Unavailable' }
}

function Format-FmkGigahertz {
    <# Advertised/measured megahertz to a GHz string; 0 means not reported. #>
    param($Megahertz)
    try {
        $m = [double]$Megahertz
        if ($m -le 0) { return 'Unavailable' }
        return ('{0:N2} GHz' -f ($m / 1000))
    }
    catch { return 'Unavailable' }
}

function ConvertFrom-FmkWmiDate {
    <#
        WMI datetime to a DateTime, or $null when unparseable. Get-CimInstance
        already converts datetime properties to DateTime objects, so both the
        raw DMTF string and a ready DateTime are accepted.
    #>
    param($Dmtf)
    try {
        if ($Dmtf -is [datetime]) { return $Dmtf }
        if ([string]::IsNullOrEmpty("$Dmtf")) { return $null }
        return [System.Management.ManagementDateTimeConverter]::ToDateTime([string]$Dmtf)
    }
    catch { return $null }
}

function Format-FmkWmiDate {
    param($Dmtf)
    try {
        $dt = ConvertFrom-FmkWmiDate $Dmtf
        if ($null -eq $dt) { return 'Unavailable' }
        return $dt.ToString('yyyy-MM-dd HH:mm')
    }
    catch { return 'Unavailable' }
}

function Format-FmkUptime {
    param($BootTime)
    try {
        $ts = (Get-Date) - [datetime]$BootTime
        if ($ts.TotalSeconds -lt 0) { return 'Unavailable' }
        $d = [int][Math]::Floor($ts.TotalDays)
        $out = ''
        if ($d -eq 1) { $out = '1 day, ' }
        elseif ($d -gt 1) { $out = "$d days, " }
        return ('{0}{1} h {2} min' -f $out, $ts.Hours, $ts.Minutes)
    }
    catch { return 'Unavailable' }
}

function Get-FmkMemoryTypeName {
    <# SMBIOS memory-device type codes; unknown codes report their code. #>
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        0x01 { return 'Other' }
        0x02 { return 'Unknown' }
        0x03 { return 'DRAM' }
        0x0F { return 'SDRAM' }
        0x11 { return 'RDRAM' }
        0x12 { return 'DDR' }
        0x13 { return 'DDR2' }
        0x18 { return 'DDR3' }
        0x1A { return 'DDR4' }
        0x1B { return 'LPDDR' }
        0x1C { return 'LPDDR2' }
        0x1D { return 'LPDDR3' }
        0x1E { return 'LPDDR4' }
        0x22 { return 'DDR5' }
        0x23 { return 'LPDDR5' }
        default { return ('Unknown (SMBIOS code 0x{0:X2})' -f $c) }
    }
}

function Get-FmkCpuArchName {
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        0 { return 'x86' }
        5 { return 'ARM' }
        6 { return 'Itanium' }
        9 { return 'x64' }
        12 { return 'ARM64' }
        default { return 'Unknown' }
    }
}

function Get-FmkOsInstallTypeName {
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        1 { return 'Client (workstation)' }
        2 { return 'Domain controller' }
        3 { return 'Server' }
        default { return 'Unknown' }
    }
}

function Get-FmkEccName {
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        1 { return 'Other' }
        2 { return 'Unknown' }
        3 { return 'None' }
        4 { return 'Parity' }
        5 { return 'Single-bit ECC' }
        6 { return 'Multi-bit ECC' }
        7 { return 'CRC' }
        default { return 'Unknown' }
    }
}

function Format-FmkLinkSpeed {
    param($BitsPerSecond)
    try {
        $b = [double]$BitsPerSecond
        if ($b -le 0) { return 'Unavailable' }
        if ($b -ge 1GB) { return ('{0:N1} Gbps' -f ($b / 1GB)) }
        if ($b -ge 1MB) { return ('{0:N0} Mbps' -f ($b / 1MB)) }
        return ('{0:N0} bps' -f $b)
    }
    catch { return 'Unavailable' }
}

function ConvertFrom-FmkWslLine {
    <# wsl.exe emits UTF-16, which arrives NUL-interleaved; strip and trim. #>
    param($Line)
    try { return ([string]$Line).Replace([string][char]0, '').Trim() }
    catch { return '' }
}

function ConvertFrom-FmkMonitorString {
    <# WMI monitor uint16 arrays are NUL-padded ASCII; decode and strip. #>
    param($Words)
    try {
        $chars = foreach ($w in @($Words)) { [char][int]$w }
        return (-join $chars).Trim([char]0).Trim()
    }
    catch { return '' }
}

function Get-FmkFirmwareModeAndSecureBoot {
    <#
        Shared UEFI/Secure Boot probe for the Windows and Firmware sections.
        Confirm-SecureBootUEFI answers on UEFI and throws on legacy boot, so a
        boolean result itself proves UEFI. A privilege-flavored failure is
        reported as an access limit, not as legacy hardware.
    #>
    try {
        $sb = Confirm-SecureBootUEFI -ErrorAction Stop
        return @{ Mode = 'UEFI'; SecureBoot = $sb }
    }
    catch {
        if ("$($_.Exception.Message)" -match '(?i)privilege|access|denied|require') {
            return @{ Mode = 'Unknown (administrator rights may be required)'; SecureBoot = $null }
        }
        return @{ Mode = 'Legacy BIOS or unknown'; SecureBoot = $null }
    }
}

function Add-FmkSecureBootRow {
    <# Secure Boot row matching the firmware probe outcome. #>
    param($Section, $Firmware)
    if ($null -eq $Firmware.SecureBoot) {
        if ([string]$Firmware.Mode -like 'Unknown*') {
            Add-FmkSysRow $Section 'Secure Boot' 'Unavailable (see firmware boot mode)'
        }
        else {
            Add-FmkSysRow $Section 'Secure Boot' 'Unavailable (not a UEFI boot)'
        }
    }
    elseif ([bool]$Firmware.SecureBoot) { Add-FmkSysRow $Section 'Secure Boot' 'Enabled' }
    else { Add-FmkSysRow $Section 'Secure Boot' 'Disabled' }
}

function Get-FmkSysWindowsSection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'Windows' -Title 'Windows and Operating System'
    $os = Read-FmkCim 'Win32_OperatingSystem'
    if ($os -and $os.Count -gt 0) { $os = $os[0] } else { $os = $null }
    if (-not $os) { Add-FmkSysWarning $s 'Win32_OperatingSystem returned nothing.' }

    $reg = @{}
    try {
        $rk = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
        foreach ($n in @('ProductName', 'EditionID', 'DisplayVersion', 'ReleaseId', 'CurrentBuild', 'UBR', 'InstallDate')) {
            $reg[$n] = $rk.$n
        }
    }
    catch { Add-FmkSysWarning $s 'Version registry key unreadable.' }

    $osCaption = Get-FmkSysField $os @('Caption')
    $product = Get-FmkSysField @{ V = $reg['ProductName'] } @('V') -Missing ''
    if ($product -eq '') { $product = $osCaption }
    Add-FmkSysRow $s 'Product name' $product
    Add-FmkSysRow $s 'Edition' (Get-FmkSysField @{ V = $reg['EditionID'] } @('V'))
    $release = Get-FmkSysField @{ V = $reg['DisplayVersion'] } @('V') -Missing ''
    if ($release -eq '') {
        $rid = Get-FmkSysField @{ V = $reg['ReleaseId'] } @('V') -Missing ''
        if ($rid -ne '') { $release = "Release $rid" } else { $release = 'Unavailable' }
    }
    Add-FmkSysRow $s 'Release' $release
    $build = Get-FmkSysField @{ V = $reg['CurrentBuild'] } @('V') -Missing ''
    $ubr = Get-FmkSysField @{ V = $reg['UBR'] } @('V') -Missing ''
    if ($build -ne '' -and $ubr -ne '') { $buildText = "$build.$ubr" }
    elseif ($build -ne '') { $buildText = $build }
    else { $buildText = Get-FmkSysField $os @('BuildNumber') }
    Add-FmkSysRow $s 'Build' $buildText
    Add-FmkSysRow $s 'OS version string' (Get-FmkSysField $os @('Version'))
    $arch = Get-FmkSysField $os @('OSArchitecture') -Missing ''
    if ($arch -eq '') {
        if ([System.Environment]::Is64BitOperatingSystem) { $arch = '64-bit' }
        else { $arch = 'Unavailable' }
    }
    Add-FmkSysRow $s 'Architecture' $arch
    Add-FmkSysRow $s 'Installation type' (Get-FmkOsInstallTypeName (Get-FmkSysField $os @('ProductType') -Missing -1))

    $installText = 'Unavailable'
    $wmiInstall = ConvertFrom-FmkWmiDate (Get-FmkSysField $os @('InstallDate') -Missing '')
    if ($wmiInstall) { $installText = $wmiInstall.ToString('yyyy-MM-dd HH:mm') }
    else {
        try {
            $epoch = $reg['InstallDate']
            if ($null -ne $epoch -and [int64]$epoch -gt 0) {
                $installText = (Get-Date '1970-01-01Z').ToLocalTime().AddSeconds([int64]$epoch).ToString('yyyy-MM-dd HH:mm')
            }
        }
        catch { }
    }
    Add-FmkSysRow $s 'Installed on' $installText

    $bootDt = ConvertFrom-FmkWmiDate (Get-FmkSysField $os @('LastBootUpTime') -Missing '')
    if ($bootDt) {
        Add-FmkSysRow $s 'Last boot' ($bootDt.ToString('yyyy-MM-dd HH:mm'))
        Add-FmkSysRow $s 'Uptime' (Format-FmkUptime $bootDt)
    }
    else {
        Add-FmkSysRow $s 'Last boot' 'Unavailable'
        Add-FmkSysRow $s 'Uptime' 'Unavailable'
        Add-FmkSysWarning $s 'Boot time unreadable, so uptime cannot be computed.'
    }

    try {
        $tz = Get-TimeZone -ErrorAction Stop
        Add-FmkSysRow $s 'Time zone' ("$($tz.Id) ($($tz.DisplayName))")
    }
    catch {
        $wtz = Read-FmkCim 'Win32_TimeZone'
        if ($wtz -and $wtz.Count -gt 0) { Add-FmkSysRow $s 'Time zone' (Get-FmkSysField $wtz[0] @('Caption', 'Description')) }
        else {
            Add-FmkSysRow $s 'Time zone' 'Unavailable'
            Add-FmkSysWarning $s 'Time zone unreadable.'
        }
    }
    try {
        $sysLoc = (Get-WinSystemLocale -ErrorAction Stop).Name
        Add-FmkSysRow $s 'System locale' $sysLoc
    }
    catch {
        Add-FmkSysRow $s 'System locale' 'Unavailable'
        Add-FmkSysWarning $s 'System locale unreadable.'
    }
    try {
        $cult = Get-Culture -ErrorAction Stop
        Add-FmkSysRow $s 'Display language' ("$($cult.DisplayName) ($($cult.Name))")
    }
    catch {
        Add-FmkSysRow $s 'Display language' 'Unavailable'
        Add-FmkSysWarning $s 'Display language unreadable.'
    }

    Add-FmkSysRow $s 'Computer name (potentially sensitive)' $env:COMPUTERNAME -Sensitivity 'Identifying'
    $who = "$env:USERDOMAIN\$env:USERNAME"
    Add-FmkSysRow $s 'Current user (potentially sensitive)' $who -Sensitivity 'Identifying'

    $fw = Get-FmkFirmwareModeAndSecureBoot
    Add-FmkSysRow $s 'Firmware boot mode' $fw.Mode
    Add-FmkSecureBootRow $s $fw

    $dg = Read-FmkCim 'Win32_DeviceGuard'
    if ($dg -and $dg.Count -gt 0) {
        $running = @()
        try { $running = @($dg[0].SecurityServicesRunning) } catch { $running = @() }
        if ($running.Count -gt 0) { Add-FmkSysRow $s 'Virtualization-based security' ('On (running: ' + ($running -join ', ') + ')') }
        else {
            $vbs = -1
            try { $vbs = [int]$dg[0].VirtualizationBasedSecurityStatus } catch { }
            if ($vbs -eq 1) { Add-FmkSysRow $s 'Virtualization-based security' 'On' }
            elseif ($vbs -eq 0) { Add-FmkSysRow $s 'Virtualization-based security' 'Off' }
            else { Add-FmkSysRow $s 'Virtualization-based security' 'Unavailable' }
        }
    }
    else {
        Add-FmkSysRow $s 'Virtualization-based security' 'Unavailable'
        Add-FmkSysWarning $s 'Device Guard status not exposed on this system.'
    }

    if ($IsAdmin) { Add-FmkSysRow $s 'Running as administrator' 'Yes' }
    else { Add-FmkSysRow $s 'Running as administrator' 'No' }
    return $s
}

function Get-FmkSysCpuSection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'CPU' -Title 'Processor (CPU)'
    $cpus = Read-FmkCim 'Win32_Processor'
    if (-not $cpus -or $cpus.Count -eq 0) {
        Add-FmkSysWarning $s 'Win32_Processor returned nothing.'
        Add-FmkSysRow $s 'Processors' 'Unavailable'
        return $s
    }
    $multi = $cpus.Count -gt 1
    $idx = 0
    foreach ($c in $cpus) {
        $idx++
        $tag = ''
        if ($multi) { $tag = "Socket $idx " }
        Add-FmkSysRow $s ($tag + 'Model') (Get-FmkSysField $c @('Name'))
        Add-FmkSysRow $s ($tag + 'Manufacturer') (Get-FmkSysField $c @('Manufacturer'))
        $fam = Get-FmkSysField $c @('Family') -Missing ''
        $mod = Get-FmkSysField $c @('Model') -Missing ''
        $stp = Get-FmkSysField $c @('Stepping') -Missing ''
        $fmsParts = @()
        if ($fam -ne '') { $fmsParts += "Family $fam" }
        if ($mod -ne '') { $fmsParts += "model $mod" }
        if ($stp -ne '') { $fmsParts += "stepping $stp" }
        if ($fmsParts.Count -eq 0) {
            Add-FmkSysRow $s ($tag + 'Family / model / stepping') 'Unavailable'
        }
        else {
            Add-FmkSysRow $s ($tag + 'Family / model / stepping') ($fmsParts -join ', ')
        }
        Add-FmkSysRow $s ($tag + 'Architecture') (Get-FmkCpuArchName (Get-FmkSysField $c @('Architecture') -Missing -1))
        Add-FmkSysRow $s ($tag + 'Processor ID') (Get-FmkSysField $c @('ProcessorId'))
        Add-FmkSysRow $s ($tag + 'Physical cores') (Get-FmkSysField $c @('NumberOfCores'))
        Add-FmkSysRow $s ($tag + 'Logical processors') (Get-FmkSysField $c @('NumberOfLogicalProcessors'))
        Add-FmkSysRow $s ($tag + 'Base frequency (advertised)') (Format-FmkGigahertz (Get-FmkSysField $c @('MaxClockSpeed') -Missing 0))
        Add-FmkSysRow $s ($tag + 'Current frequency (measured at collection)') (Format-FmkGigahertz (Get-FmkSysField $c @('CurrentClockSpeed') -Missing 0))
        $l2 = Get-FmkSysField $c @('L2CacheSize') -Missing $null
        if ($null -eq $l2) { Add-FmkSysRow $s ($tag + 'L2 cache') 'Unavailable' }
        else { Add-FmkSysRow $s ($tag + 'L2 cache') (Format-FmkBytes ([double]$l2 * 1KB)) }
        $l3 = Get-FmkSysField $c @('L3CacheSize') -Missing $null
        if ($null -eq $l3) { Add-FmkSysRow $s ($tag + 'L3 cache') 'Unavailable' }
        else { Add-FmkSysRow $s ($tag + 'L3 cache') (Format-FmkBytes ([double]$l3 * 1KB)) }
        $virt = Get-FmkSysField $c @('VirtualizationFirmwareEnabled') -Missing $null
        if ($null -eq $virt) { Add-FmkSysRow $s ($tag + 'Hardware virtualization') 'Unavailable' }
        elseif ([bool]$virt) { Add-FmkSysRow $s ($tag + 'Hardware virtualization') 'Enabled in firmware' }
        else { Add-FmkSysRow $s ($tag + 'Hardware virtualization') 'Disabled or unsupported' }
        $slat = Get-FmkSysField $c @('SecondLevelAddressTranslationExtensions') -Missing $null
        if ($null -eq $slat) { Add-FmkSysRow $s ($tag + 'Second-level address translation') 'Unavailable' }
        elseif ([bool]$slat) { Add-FmkSysRow $s ($tag + 'Second-level address translation') 'Supported' }
        else { Add-FmkSysRow $s ($tag + 'Second-level address translation') 'Not supported' }
    }
    Add-FmkSysRow $s 'Instruction sets' 'Unavailable from inbox interfaces (no CPUID source); x64 implies an x86-64 baseline.'
    $numa = Read-FmkCim 'Win32_NumaNode'
    if ($numa -and $numa.Count -gt 0) {
        Add-FmkSysRow $s 'NUMA nodes' $numa.Count
    }
    else {
        Add-FmkSysRow $s 'NUMA nodes' 'Unavailable'
        Add-FmkSysWarning $s 'NUMA topology is not exposed on this system.'
    }
    return $s
}

function Get-FmkSysMemorySection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'Memory' -Title 'Memory (RAM)'
    $cs = Read-FmkCim 'Win32_ComputerSystem'
    if ($cs -and $cs.Count -gt 0) { $cs = $cs[0] } else { $cs = $null }
    $os = Read-FmkCim 'Win32_OperatingSystem'
    if ($os -and $os.Count -gt 0) { $os = $os[0] } else { $os = $null }
    if (-not $cs -and -not $os) {
        Add-FmkSysWarning $s 'Memory counters unreadable.'
        Add-FmkSysRow $s 'Memory' 'Unavailable'
        return $s
    }

    $installed = Get-FmkSysField $cs @('TotalPhysicalMemory') -Missing $null
    if ($null -eq $installed) { Add-FmkSysRow $s 'Installed physical memory' 'Unavailable' }
    else { Add-FmkSysRow $s 'Installed physical memory' (Format-FmkBytes $installed) }

    $totalVis = Get-FmkSysField $os @('TotalVisibleMemorySize') -Missing $null
    $freePhys = Get-FmkSysField $os @('FreePhysicalMemory') -Missing $null
    if ($null -eq $totalVis -or $null -eq $freePhys) {
        Add-FmkSysRow $s 'Total visible to OS' 'Unavailable'
        Add-FmkSysRow $s 'Available' 'Unavailable'
        Add-FmkSysRow $s 'In use' 'Unavailable'
        Add-FmkSysWarning $s 'Live usage counters unreadable.'
    }
    else {
        $totalB = [double]$totalVis * 1KB
        $freeB = [double]$freePhys * 1KB
        $usedB = $totalB - $freeB
        if ($usedB -lt 0) { $usedB = 0 }
        $pct = 0
        if ($totalB -gt 0) { $pct = [int][Math]::Round($usedB / $totalB * 100) }
        Add-FmkSysRow $s 'Total visible to OS' (Format-FmkBytes $totalB)
        Add-FmkSysRow $s 'Available' (Format-FmkBytes $freeB)
        Add-FmkSysRow $s 'In use' ((Format-FmkBytes $usedB) + " ($pct%)")
    }

    $totalVirt = Get-FmkSysField $os @('TotalVirtualMemorySize') -Missing $null
    $freeVirt = Get-FmkSysField $os @('FreeVirtualMemory') -Missing $null
    if ($null -ne $totalVirt -and $null -ne $freeVirt -and $null -ne $totalVis -and $null -ne $freePhys) {
        $pfTotal = ([double]$totalVirt - [double]$totalVis) * 1KB
        $pfFree = ([double]$freeVirt - [double]$freePhys) * 1KB
        if ($pfTotal -lt 0) { $pfTotal = 0 }
        if ($pfFree -lt 0) { $pfFree = 0 }
        Add-FmkSysRow $s 'Page file total' (Format-FmkBytes $pfTotal)
        Add-FmkSysRow $s 'Page file free' (Format-FmkBytes $pfFree)
    }
    else {
        Add-FmkSysRow $s 'Page file total' 'Unavailable'
        Add-FmkSysWarning $s 'Page-file counters unreadable.'
    }

    $mods = Read-FmkCim 'Win32_PhysicalMemory'
    $arr = Read-FmkCim 'Win32_PhysicalMemoryArray'
    $arrInfo = $null
    if ($arr -and $arr.Count -gt 0) { $arrInfo = $arr[0] }
    $populated = @($mods).Count
    $slots = -1
    if ($arrInfo) {
        try { $slots = [int]$arrInfo.MemoryDevices } catch { $slots = -1 }
    }
    if ($populated -eq 0) {
        Add-FmkSysRow $s 'Memory modules' 'Unavailable'
        Add-FmkSysWarning $s 'No memory modules reported. Some laptops and systems with soldered memory expose totals but no per-module details through Windows; the totals above remain accurate.'
    }
    else {
        $slotText = "$populated module(s)"
        if ($slots -gt $populated) { $slotText += " in $slots slots ($($slots - $populated) empty)" }
        elseif ($slots -eq $populated -and $slots -gt 0) { $slotText += " in $slots slots (none empty)" }
        Add-FmkSysRow $s 'Memory modules' $slotText
        $mi = 0
        foreach ($m in @($mods)) {
            $mi++
            # DeviceLocator first: BankLabel repeats on some firmware (two
            # sticks both answering "BANK 0"), while the locator names the
            # actual slot.
            $loc = Get-FmkSysField $m @('DeviceLocator', 'BankLabel') -Missing "#$mi"
            $cap = Get-FmkSysField $m @('Capacity') -Missing $null
            $capText = 'Unknown size'
            if ($null -ne $cap) { $capText = Format-FmkBytes $cap }
            $typeName = Get-FmkMemoryTypeName (Get-FmkSysField $m @('SMBIOSMemoryType') -Missing -1)
            $spd = Get-FmkSysField $m @('ConfiguredClockSpeed', 'Speed') -Missing 0
            $speedText = ''
            if ($spd -and [double]$spd -gt 0) { $speedText = "-$([int]$spd)" }
            $mfr = Get-FmkSysField $m @('Manufacturer') -Missing ''
            $part = Get-FmkSysField $m @('PartNumber') -Missing ''
            if ($mfr -ne '') { $mfr = $mfr.Trim() }
            if ($part -ne '') { $part = $part.Trim() }
            $bits = @($capText)
            $typeSpeed = ($typeName + $speedText).Trim()
            if ($typeSpeed -ne '' -and $typeSpeed -ne 'Unknown') { $bits += $typeSpeed }
            if ($mfr -ne '') { $bits += $mfr }
            if ($part -ne '') { $bits += $part }
            Add-FmkSysRow $s "Module $loc" ($bits -join ' / ')
        }
    }
    if ($arrInfo) {
        Add-FmkSysRow $s 'Error correction' (Get-FmkEccName (Get-FmkSysField $arrInfo @('MemoryErrorCorrection') -Missing -1))
        $depth = Get-FmkSysField $arrInfo @('InterleaveDataDepth') -Missing $null
        if ($null -eq $depth) { Add-FmkSysRow $s 'Interleave depth' 'Unavailable' }
        else { Add-FmkSysRow $s 'Interleave depth' "$depth" }
    }
    else {
        Add-FmkSysWarning $s 'Memory array details (ECC, slots) not exposed on this system.'
    }
    return $s
}

function Get-FmkSysGpuSection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'GPU' -Title 'Graphics (GPU)'
    $gpus = Read-FmkCim 'Win32_VideoController'
    if (-not $gpus -or $gpus.Count -eq 0) {
        Add-FmkSysWarning $s 'No video controllers reported.'
        Add-FmkSysRow $s 'Graphics adapters' 'Unavailable'
        return $s
    }
    $multi = $gpus.Count -gt 1
    Add-FmkSysRow $s 'Adapter count' $gpus.Count
    $idx = 0
    foreach ($g in $gpus) {
        $idx++
        $tag = ''
        if ($multi) { $tag = "Adapter $idx " }
        Add-FmkSysRow $s ($tag + 'Name') (Get-FmkSysField $g @('Name'))
        Add-FmkSysRow $s ($tag + 'Vendor') (Get-FmkSysField $g @('AdapterCompatibility'))
        Add-FmkSysRow $s ($tag + 'Status') (Get-FmkSysField $g @('Status'))
        $pnp = Get-FmkSysField $g @('PNPDeviceID') -Missing ''
        if ($pnp -ne '' -and $pnp -match 'VEN_([0-9A-Fa-f]{4}).*DEV_([0-9A-Fa-f]{4})') {
            Add-FmkSysRow $s ($tag + 'PCI hardware ID') ("VEN $($Matches[1].ToUpper()) DEV $($Matches[2].ToUpper())")
        }
        else {
            Add-FmkSysRow $s ($tag + 'PCI hardware ID') 'Unavailable'
        }
        $vram = Get-FmkSysField $g @('AdapterRAM') -Missing $null
        if ($null -eq $vram) { Add-FmkSysRow $s ($tag + 'Dedicated video memory') 'Unavailable' }
        else { Add-FmkSysRow $s ($tag + 'Dedicated video memory') (Format-FmkBytes $vram) }
        Add-FmkSysRow $s ($tag + 'Driver version') (Get-FmkSysField $g @('DriverVersion'))
        Add-FmkSysRow $s ($tag + 'Driver date') (Format-FmkWmiDate (Get-FmkSysField $g @('DriverDate') -Missing ''))
        $mode = Get-FmkSysField $g @('VideoModeDescription') -Missing ''
        # A 32-bit color depth is the driver's "unknown" sentinel, not eight
        # billion colors; drop it rather than printing nonsense.
        if ($mode -match '(\d+)\s+colors?$') {
            try {
                if ([double]$Matches[1] -gt 64) {
                    $mode = $mode.Substring(0, $mode.LastIndexOf($Matches[0])).TrimEnd()
                }
            }
            catch { }
        }
        if ($mode -eq '') {
            $w = Get-FmkSysField $g @('CurrentHorizontalResolution') -Missing $null
            $h = Get-FmkSysField $g @('CurrentVerticalResolution') -Missing $null
            $r = Get-FmkSysField $g @('CurrentRefreshRate') -Missing $null
            if ($null -ne $w -and $null -ne $h) {
                $mode = "${w} x ${h}"
                if ($null -ne $r -and [int]$r -gt 1) { $mode += " @ ${r} Hz" }
            }
            else { $mode = 'Unavailable' }
        }
        Add-FmkSysRow $s ($tag + 'Current display mode') $mode
    }
    Add-FmkSysWarning $s 'AdapterRAM is a 32-bit field and may cap at 4 GB on some systems.'
    Add-FmkSysRow $s 'Shared GPU memory' 'Unavailable (requires a DXGI query)'
    $dxv = ''
    try {
        $dxv = (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\DirectX' -Name 'Version' -ErrorAction Stop).Version
    }
    catch { $dxv = '' }
    # A 4.09 stamp is a leftover DirectX 9 version key, not the installed
    # DirectX; reporting it as the version would mislead.
    if ($dxv -eq '') { Add-FmkSysRow $s 'DirectX version' 'Unavailable' }
    elseif ("$dxv" -like '4.09*') {
        Add-FmkSysRow $s 'DirectX version' 'Unavailable (registry holds only a legacy DirectX 9 version stamp)'
    }
    else { Add-FmkSysRow $s 'DirectX version' $dxv }
    Add-FmkSysRow $s 'DirectX feature level' 'Unavailable (no inbox source)'
    Add-FmkSysRow $s 'WDDM driver model' 'Unavailable (no inbox source)'
    Add-FmkSysRow $s 'HDR / variable refresh' 'Unavailable (requires display-core query)'
    return $s
}

function Get-FmkBusTypeName {
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        0 { return 'Unknown' }
        7 { return 'USB' }
        8 { return 'RAID' }
        11 { return 'SATA' }
        14 { return 'Virtual' }
        15 { return 'File-backed virtual' }
        16 { return 'Storage Spaces' }
        17 { return 'NVMe' }
        default { return 'Unknown' }
    }
}

function Get-FmkDiskMediaName {
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        3 { return 'HDD' }
        4 { return 'SSD' }
        5 { return 'SCM' }
        default { return 'Unknown' }
    }
}

function Get-FmkOpStatusName {
    <# DMTF operational-status codes shared by the MSFT storage classes. #>
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        0 { return 'Unknown' }
        1 { return 'Other' }
        2 { return 'OK' }
        3 { return 'Degraded' }
        4 { return 'Stressed' }
        5 { return 'Predictive failure' }
        6 { return 'Error' }
        default { return 'Unknown' }
    }
}

function Get-FmkDiskHealthName {
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        0 { return 'Healthy' }
        1 { return 'Warning' }
        2 { return 'Unhealthy' }
        default { return 'Unknown' }
    }
}

function Get-FmkDriveTypeName {
    param($Code)
    try { $c = [int]$Code } catch { return 'Unknown' }
    switch ($c) {
        0 { return 'Unknown' }
        1 { return 'No root directory' }
        2 { return 'Removable' }
        3 { return 'Local fixed disk' }
        4 { return 'Network drive' }
        5 { return 'Compact disc' }
        6 { return 'RAM disk' }
        default { return 'Unknown' }
    }
}

function Get-FmkSysStorageSection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'Storage' -Title 'Storage'
    Add-FmkSysRow $s 'Scope note' 'Physical disks and logical volumes are listed separately below.'
    $disks = Read-FmkCim 'Win32_DiskDrive'
    if (-not $disks -or $disks.Count -eq 0) {
        Add-FmkSysWarning $s 'No physical disks reported.'
        Add-FmkSysRow $s 'Physical disks' 'Unavailable'
        return $s
    }

    $osDrive = ''
    try {
        $osq = Read-FmkCim 'Win32_OperatingSystem'
        if ($osq -and $osq.Count -gt 0) { $osDrive = [string]$osq[0].SystemDrive }
    }
    catch { }

    # Disk index -> drive letters, best effort through the association classes.
    $letterMap = @{}
    $bootParts = @{}
    try {
        $partToDisk = @{}
        foreach ($a in @(Read-FmkCim 'Win32_DiskDriveToDiskPartition')) {
            $di = -1
            $pi = -1
            if ([string]$a.Antecedent -match 'PHYSICALDRIVE(\d+)') { $di = [int]$Matches[1] }
            if ([string]$a.Dependent -match 'Disk #(\d+),\s*Partition #(\d+)') {
                if ([int]$Matches[1] -eq $di) { $pi = [int]$Matches[2] }
            }
            if ($di -ge 0 -and $pi -ge 0) { $partToDisk["$di/$pi"] = $di }
        }
        foreach ($a in @(Read-FmkCim 'Win32_LogicalDiskToPartition')) {
            $letter = ''
            if ([string]$a.Dependent -match 'DeviceID="([A-Za-z]:)"') { $letter = $Matches[1] }
            $key = ''
            if ([string]$a.Antecedent -match 'Disk #(\d+),\s*Partition #(\d+)') { $key = "$($Matches[1])/$($Matches[2])" }
            if ($letter -ne '' -and $key -ne '' -and $partToDisk.ContainsKey($key)) {
                $di = $partToDisk[$key]
                if (-not $letterMap.ContainsKey($di)) { $letterMap[$di] = @() }
                $letterMap[$di] += $letter
            }
        }
        foreach ($p in @(Read-FmkCim 'Win32_DiskPartition')) {
            try {
                if ([bool]$p.BootPartition -and ("$($p.DeviceID)" -match 'Disk #(\d+)')) {
                    $bootParts[[int]$Matches[1]] = $true
                }
            }
            catch { }
        }
    }
    catch { Add-FmkSysWarning $s 'Disk-to-volume mapping unavailable; volumes listed separately.' }

    $di = -1
    foreach ($d in $disks) {
        $di++
        $model = Get-FmkSysField $d @('Model')
        $size = Get-FmkSysField $d @('Size') -Missing $null
        $sizeText = 'Unknown size'
        if ($null -ne $size) { $sizeText = Format-FmkBytes $size }
        $iface = Get-FmkSysField $d @('InterfaceType') -Missing ''
        $media = Get-FmkSysField $d @('MediaType') -Missing ''
        $kind = $iface
        if ($media -ne '' -and $media -ne $iface) {
            if ($kind -ne '') { $kind += ' / ' }
            $kind += $media
        }
        if ($kind -eq '') { $kind = 'Unknown interface' }
        $tags = @()
        if ($bootParts.ContainsKey($di)) { $tags += 'boot disk' }
        $tagText = ''
        if ($tags.Count -gt 0) { $tagText = ' (' + ($tags -join ', ') + ')' }
        Add-FmkSysRow $s "Disk $di" ("$model -- $sizeText, $kind$tagText")
        Add-FmkSysRow $s "Disk $di manufacturer" (Get-FmkSysField $d @('Manufacturer'))
        Add-FmkSysRow $s "Disk $di partitions" (Get-FmkSysField $d @('Partitions'))
        Add-FmkSysRow $s "Disk $di status" (Get-FmkSysField $d @('Status'))
        Add-FmkSysRow $s "Disk $di serial number" (Get-FmkSysField $d @('SerialNumber')) -Sensitivity 'Private'
        if ($letterMap.ContainsKey($di)) {
            foreach ($letter in @($letterMap[$di])) {
                # Device IDs already end in a colon ("C:"); the row renderer
                # adds its own, so strip it here to avoid "Volume C::".
                Add-FmkSysRow $s ("Disk $di volume " + $letter.TrimEnd(':')) (Get-FmkVolumeText $letter $osDrive)
            }
        }
    }

    $msft = Read-FmkCim 'MSFT_PhysicalDisk' -Namespace 'root/Microsoft/Windows/Storage'
    if ($msft -and $msft.Count -gt 0) {
        $mi = -1
        foreach ($m in $msft) {
            $mi++
            $fname = Get-FmkSysField $m @('FriendlyName')
            $health = Get-FmkDiskHealthName (Get-FmkSysField $m @('HealthStatus') -Missing -1)
            $opRaw = Get-FmkSysField $m @('OperationalStatus') -Missing $null
            $opText = 'Unknown'
            if ($null -ne $opRaw) { $opText = ((@($opRaw) | ForEach-Object { Get-FmkOpStatusName $_ }) -join ', ') }
            $bus = Get-FmkBusTypeName (Get-FmkSysField $m @('BusType') -Missing -1)
            $mediaName = Get-FmkDiskMediaName (Get-FmkSysField $m @('MediaType') -Missing -1)
            $msize = Get-FmkSysField $m @('Size') -Missing $null
            $msizeText = 'Unknown size'
            if ($null -ne $msize) { $msizeText = Format-FmkBytes $msize }
            Add-FmkSysRow $s "Health entry $($mi + 1)" ("$fname -- health: $health, state: $opText, bus: $bus, media: $mediaName, size: $msizeText")
        }
    }
    else {
        Add-FmkSysWarning $s 'Storage health details unavailable (the Storage namespace may require administrator rights).'
    }

    $smart = $null
    try { $smart = Read-FmkCim 'MSStorageDriver_FailurePredictStatus' -Namespace 'root/wmi' } catch { $smart = $null }
    if ($smart -and $smart.Count -gt 0) {
        $si = 0
        foreach ($entry in $smart) {
            $si++
            $pred = $null
            try { $pred = [bool]$entry.PredictFailure } catch { $pred = $null }
            if ($null -eq $pred) { Add-FmkSysRow $s "SMART prediction (drive $si)" 'Unavailable' }
            elseif ($pred) { Add-FmkSysRow $s "SMART prediction (drive $si)" 'Failure predicted -- back up and replace the drive' }
            else { Add-FmkSysRow $s "SMART prediction (drive $si)" 'OK (no failure predicted)' }
        }
    }
    else {
        Add-FmkSysWarning $s 'SMART status unavailable (often requires administrator rights).'
    }

    $vols = Read-FmkCim 'Win32_LogicalDisk'
    if ($vols -and $vols.Count -gt 0) {
        foreach ($v in $vols) {
            $letter = Get-FmkSysField $v @('DeviceID') -Missing ''
            if ($letter -eq '') { continue }
            $mapped = $false
            foreach ($letters in @($letterMap.Values)) {
                if (@($letters) -contains $letter) { $mapped = $true }
            }
            if (-not $mapped) {
                Add-FmkSysRow $s ("Volume " + $letter.TrimEnd(':')) (Get-FmkVolumeText $letter $osDrive)
            }
        }
    }
    return $s
}

function Get-FmkVolumeText {
    <# One-line volume summary; a zero-byte volume stays zero, never 'Unavailable'. #>
    param([string]$Letter, [string]$OsDrive)
    try {
        $list = @(Get-CimInstance -ClassName 'Win32_LogicalDisk' -Filter "DeviceID='$Letter'" -ErrorAction Stop)
        if (-not $list -or $list.Count -eq 0) { return 'Unavailable' }
        $v = $list[0]
        $label = Get-FmkSysField $v @('VolumeName') -Missing ''
        $fs = Get-FmkSysField $v @('FileSystem') -Missing ''
        $size = Get-FmkSysField $v @('Size') -Missing $null
        $free = Get-FmkSysField $v @('FreeSpace') -Missing $null
        $dtype = Get-FmkDriveTypeName (Get-FmkSysField $v @('DriveType') -Missing -1)
        $bits = @()
        if ($label -ne '') { $bits += "($label)" }
        if ($fs -ne '') { $bits += $fs }
        $bits += $dtype
        if ($null -ne $size -and $null -ne $free) {
            $sz = [double]$size
            $fr = [double]$free
            if ($fr -lt 0) { $fr = 0 }
            if ($fr -gt $sz) { $fr = $sz }
            $pct = 0
            if ($sz -gt 0) { $pct = [int][Math]::Round($fr / $sz * 100) }
            $bits += ((Format-FmkBytes $fr) + ' free of ' + (Format-FmkBytes $sz) + " ($pct% free)")
        }
        else {
            $bits += 'size unavailable'
        }
        if ($OsDrive -ne '' -and $letter -ieq $OsDrive) { $bits += '(system drive)' }
        return ($bits -join ' ')
    }
    catch { return 'Unavailable' }
}

function Get-FmkSysFirmwareSection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'Firmware' -Title 'Motherboard and Firmware'
    try {
        $csq = Read-FmkCim 'Win32_ComputerSystem'
        if ($csq -and $csq.Count -gt 0) {
            Add-FmkSysRow $s 'System manufacturer' (Get-FmkSysField $csq[0] @('Manufacturer'))
            Add-FmkSysRow $s 'System model' (Get-FmkSysField $csq[0] @('Model'))
            $fam = Get-FmkSysField $csq[0] @('SystemFamily') -Missing ''
            if ($fam -ne '') { Add-FmkSysRow $s 'System family' $fam }
        }
        else { Add-FmkSysWarning $s 'System identity unreadable.' }
    }
    catch { Add-FmkSysWarning $s 'System identity unreadable.' }
    $bb = Read-FmkCim 'Win32_BaseBoard'
    if ($bb -and $bb.Count -gt 0) {
        Add-FmkSysRow $s 'Motherboard manufacturer' (Get-FmkSysField $bb[0] @('Manufacturer'))
        Add-FmkSysRow $s 'Motherboard model' (Get-FmkSysField $bb[0] @('Product'))
        Add-FmkSysRow $s 'Motherboard version' (Get-FmkSysField $bb[0] @('Version'))
    }
    else {
        Add-FmkSysWarning $s 'Baseboard details not exposed on this system.'
        Add-FmkSysRow $s 'Motherboard' 'Unavailable'
    }
    $bios = Read-FmkCim 'Win32_BIOS'
    if ($bios -and $bios.Count -gt 0) {
        Add-FmkSysRow $s 'BIOS/UEFI vendor' (Get-FmkSysField $bios[0] @('Manufacturer'))
        $bver = Get-FmkSysField $bios[0] @('SMBIOSBIOSVersion') -Missing ''
        if ($bver -eq '') { $bver = Get-FmkSysField $bios[0] @('Version') }
        Add-FmkSysRow $s 'BIOS/UEFI version' $bver
        Add-FmkSysRow $s 'BIOS/UEFI date' (Format-FmkWmiDate (Get-FmkSysField $bios[0] @('ReleaseDate') -Missing ''))
    }
    else {
        Add-FmkSysWarning $s 'BIOS details not exposed on this system.'
        Add-FmkSysRow $s 'BIOS/UEFI' 'Unavailable'
    }
    $fw = Get-FmkFirmwareModeAndSecureBoot
    Add-FmkSysRow $s 'Firmware boot mode' $fw.Mode
    Add-FmkSecureBootRow $s $fw
    $tpmPresent = $null
    $tpmReady = $null
    $tpmVer = ''
    try {
        if (Get-Command Get-Tpm -ErrorAction SilentlyContinue) {
            $tpm = Get-Tpm -ErrorAction Stop
            $tpmPresent = [bool]$tpm.TpmPresent
            $tpmReady = [bool]$tpm.TpmReady
            try { $tpmVer = [string]$tpm.ManufacturerVersion } catch { $tpmVer = '' }
        }
    }
    catch { }
    if ($null -eq $tpmPresent) {
        Add-FmkSysRow $s 'TPM' 'Unavailable (may require administrator rights)'
        Add-FmkSysWarning $s 'TPM status unreadable with current permissions.'
    }
    else {
        if ($tpmPresent) {
            $tpmText = 'Present'
            if ($tpmReady) { $tpmText += ', ready' } else { $tpmText += ', not ready' }
            if ($tpmVer -ne '') { $tpmText += " (spec version $tpmVer)" }
            Add-FmkSysRow $s 'TPM' $tpmText
        }
        else { Add-FmkSysRow $s 'TPM' 'Not present' }
    }
    return $s
}

function Get-FmkSysNetworkSection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'Network' -Title 'Network Adapters'
    $adapters = $null
    try {
        if (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue) {
            $adapters = @(Get-NetAdapter -ErrorAction Stop)
        }
    }
    catch { $adapters = $null }
    if (-not $adapters -or $adapters.Count -eq 0) {
        Add-FmkSysWarning $s 'No network adapters reported.'
        Add-FmkSysRow $s 'Network adapters' 'Unavailable'
        return $s
    }
    $shown = 0
    $cap = 12
    foreach ($a in $adapters) {
        if ($shown -ge $cap) { break }
        $shown++
        $aname = Get-FmkSysField $a @('Name')
        Add-FmkSysRow $s "Adapter: $aname" (Get-FmkSysField $a @('InterfaceDescription'))
        Add-FmkSysRow $s "$aname status" (Get-FmkSysField $a @('Status'))
        Add-FmkSysRow $s "$aname link speed" (Get-FmkSysField $a @('LinkSpeed'))
        Add-FmkSysRow $s "$aname MAC address" (Get-FmkSysField $a @('MacAddress')) -Sensitivity 'Private'
        $drv = Read-FmkCim 'Win32_NetworkAdapter' -Filter ("NetConnectionID='" + ($aname -replace "'", "''") + "'")
        if ($drv -and $drv.Count -gt 0) {
            Add-FmkSysRow $s "$aname driver" (Get-FmkSysField $drv[0] @('DriverVersion'))
            $ddate = Format-FmkWmiDate (Get-FmkSysField $drv[0] @('DriverDate') -Missing '')
            Add-FmkSysRow $s "$aname driver date" $ddate
        }
        else {
            Add-FmkSysRow $s "$aname driver" 'Unavailable'
        }
    }
    if ($adapters.Count -gt $cap) {
        Add-FmkSysRow $s 'Adapter list' ("Showing $cap of $($adapters.Count) adapters.")
    }
    try {
        if (Get-Command Get-NetIPAddress -ErrorAction SilentlyContinue) {
            $ips = @(Get-NetIPAddress -ErrorAction Stop | Where-Object {
                    ($_.AddressFamily -eq 'IPv4' -or $_.AddressFamily -eq 'IPv6') -and
                    $_.IPAddress -ne '127.0.0.1' -and $_.IPAddress -ne '::1'
                })
            $shownIp = 0
            foreach ($ip in $ips) {
                if ($shownIp -ge 12) { break }
                $shownIp++
                $fam = 'IPv4'
                if ([string]$ip.AddressFamily -eq 'IPv6') { $fam = 'IPv6' }
                Add-FmkSysRow $s ("$($ip.InterfaceAlias) $fam") ("$($ip.IPAddress)/$($ip.PrefixLength)") -Sensitivity 'Private'
            }
            if ($ips.Count -eq 0) { Add-FmkSysWarning $s 'No non-loopback IP addresses found.' }
        }
    }
    catch { Add-FmkSysWarning $s 'IP addresses unreadable.' }
    try {
        if (Get-Command Get-NetIPInterface -ErrorAction SilentlyContinue) {
            $ifs = @(Get-NetIPInterface -ErrorAction Stop)
            $shownDhcp = 0
            foreach ($ni in $ifs) {
                if ($shownDhcp -ge 12) { break }
                $dh = Get-FmkSysField $ni @('Dhcp') -Missing $null
                if ($null -eq $dh) { continue }
                $shownDhcp++
                if ([string]$dh -eq 'Enabled') { Add-FmkSysRow $s ("$($ni.InterfaceAlias) DHCP") 'Enabled' }
                else { Add-FmkSysRow $s ("$($ni.InterfaceAlias) DHCP") 'Disabled' }
            }
        }
    }
    catch { Add-FmkSysWarning $s 'DHCP status unreadable.' }
    try {
        if (Get-Command Get-DnsClientServerAddress -ErrorAction SilentlyContinue) {
            $dns = @(Get-DnsClientServerAddress -ErrorAction Stop)
            $shownDns = 0
            foreach ($d in $dns) {
                $addrs = @()
                try { $addrs = @($d.ServerAddresses) } catch { $addrs = @() }
                if ($addrs.Count -eq 0) { continue }
                if ($shownDns -ge 8) { break }
                $shownDns++
                Add-FmkSysRow $s ("$($d.InterfaceAlias) DNS") ($addrs -join '; ') -Sensitivity 'Private'
            }
        }
    }
    catch { Add-FmkSysWarning $s 'DNS servers unreadable.' }
    try {
        if (Get-Command Get-NetRoute -ErrorAction SilentlyContinue) {
            $gw = @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop |
                Where-Object { $_.NextHop -ne '0.0.0.0' -and $_.NextHop -ne '' } |
                Select-Object -First 4)
            foreach ($r in $gw) {
                Add-FmkSysRow $s 'Default gateway' ([string]$r.NextHop) -Sensitivity 'Private'
            }
            if ($gw.Count -eq 0) { Add-FmkSysWarning $s 'No default IPv4 gateway found.' }
        }
    }
    catch { Add-FmkSysWarning $s 'Default gateway unreadable.' }
    return $s
}

function Get-FmkSysBatterySection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'Battery' -Title 'Battery and Power'
    $batt = Read-FmkCim 'Win32_Battery'
    if (-not $batt -or $batt.Count -eq 0) {
        Add-FmkSysRow $s 'Battery' 'Not applicable (no battery detected)'
        return $s
    }
    $b = $batt[0]
    Add-FmkSysRow $s 'Battery' (Get-FmkSysField $b @('Name'))
    if ($batt.Count -gt 1) { Add-FmkSysRow $s 'Battery count' $batt.Count }
    $chg = Get-FmkSysField $b @('EstimatedChargeRemaining') -Missing $null
    if ($null -eq $chg) { Add-FmkSysRow $s 'Charge' 'Unavailable' }
    else { Add-FmkSysRow $s 'Charge' "$chg%" }
    $wmiStat = $null
    try { $wmiStat = Read-FmkCim 'BatteryStatus' -Namespace 'root/wmi' } catch { $wmiStat = $null }
    if ($wmiStat -and $wmiStat.Count -gt 0) {
        $charging = $false
        $discharging = $false
        $onAc = $false
        try { $charging = [bool]$wmiStat[0].Charging } catch { }
        try { $discharging = [bool]$wmiStat[0].Discharging } catch { }
        try { $onAc = [bool]$wmiStat[0].PowerOnline } catch { }
        if ($charging) { Add-FmkSysRow $s 'Status' 'Charging' }
        elseif ($discharging) { Add-FmkSysRow $s 'Status' 'Discharging' }
        elseif ($onAc) { Add-FmkSysRow $s 'Status' 'On AC power' }
        else { Add-FmkSysRow $s 'Status' 'Unknown' }
        if ($onAc) { Add-FmkSysRow $s 'AC power' 'Connected' }
        else { Add-FmkSysRow $s 'AC power' 'Not connected' }
    }
    else {
        Add-FmkSysRow $s 'Status' 'Unavailable'
        Add-FmkSysWarning $s 'Live battery status not exposed on this system.'
    }
    $designed = $null
    $full = $null
    try {
        $static = Read-FmkCim 'BatteryStaticData' -Namespace 'root/wmi'
        if ($static -and $static.Count -gt 0) { $designed = $static[0].DesignedCapacity }
    }
    catch { }
    try {
        $fcc = Read-FmkCim 'BatteryFullChargedCapacity' -Namespace 'root/wmi'
        if ($fcc -and $fcc.Count -gt 0) { $full = $fcc[0].FullChargedCapacity }
    }
    catch { }
    # WMI capacities arrive in milliwatt-hours: show watt-hours, not bytes.
    if ($null -ne $designed -and [double]$designed -gt 0) {
        Add-FmkSysRow $s 'Design capacity' (('{0:N1} Wh' -f ([double]$designed / 1000)))
    }
    else { Add-FmkSysRow $s 'Design capacity' 'Unavailable' }
    if ($null -ne $full -and [double]$full -gt 0) {
        Add-FmkSysRow $s 'Full-charge capacity' (('{0:N1} Wh' -f ([double]$full / 1000)))
    }
    else { Add-FmkSysRow $s 'Full-charge capacity' 'Unavailable' }
    if ($null -ne $designed -and $null -ne $full -and [double]$designed -gt 0 -and [double]$full -gt 0) {
        $health = [int][Math]::Round([double]$full / [double]$designed * 100)
        if ($health -gt 100) { $health = 100 }
        Add-FmkSysRow $s 'Battery health estimate' "$health% of design capacity"
    }
    else {
        Add-FmkSysRow $s 'Battery health estimate' 'Unavailable (needs design and full-charge capacities)'
    }
    try {
        $cyc = Read-FmkCim 'BatteryCycleCount' -Namespace 'root/wmi'
        if ($cyc -and $cyc.Count -gt 0 -and $null -ne $cyc[0].CycleCount) {
            Add-FmkSysRow $s 'Cycle count' ([int]$cyc[0].CycleCount)
        }
        else { Add-FmkSysRow $s 'Cycle count' 'Unavailable' }
    }
    catch { Add-FmkSysRow $s 'Cycle count' 'Unavailable' }
    try {
        $plan = powercfg /getactivescheme 2>$null
        $planText = (@($plan) | ForEach-Object { "$_" }) -join ' '
        if ($planText -match '\(([^)]+)\)\s*$') { Add-FmkSysRow $s 'Power plan' $Matches[1].Trim() }
        elseif ($planText.Trim() -ne '') { Add-FmkSysRow $s 'Power plan' $planText.Trim() }
        else { Add-FmkSysRow $s 'Power plan' 'Unavailable' }
    }
    catch {
        Add-FmkSysRow $s 'Power plan' 'Unavailable'
        Add-FmkSysWarning $s 'Active power plan unreadable.'
    }
    return $s
}

function Get-FmkSysAudioDisplaySection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'AudioDisplay' -Title 'Audio, Displays and Peripherals'
    $snd = Read-FmkCim 'Win32_SoundDevice'
    if ($snd -and $snd.Count -gt 0) {
        $shownSnd = 0
        foreach ($dev in $snd) {
            if ($shownSnd -ge 6) { break }
            $shownSnd++
            $nm = Get-FmkSysField $dev @('Name')
            $mf = Get-FmkSysField $dev @('Manufacturer') -Missing ''
            if ($mf -ne '') { Add-FmkSysRow $s "Audio device $shownSnd" "$nm ($mf)" }
            else { Add-FmkSysRow $s "Audio device $shownSnd" $nm }
        }
        if ($snd.Count -gt 6) { Add-FmkSysRow $s 'Audio devices' ("Showing 6 of $($snd.Count).") }
    }
    else {
        Add-FmkSysWarning $s 'No audio devices reported.'
        Add-FmkSysRow $s 'Audio devices' 'Unavailable'
    }
    $mons = $null
    try { $mons = Read-FmkCim 'WmiMonitorID' -Namespace 'root/wmi' } catch { $mons = $null }
    if ($mons -and $mons.Count -gt 0) {
        $shownMon = 0
        foreach ($mon in $mons) {
            if ($shownMon -ge 6) { break }
            $shownMon++
            $mfr = ConvertFrom-FmkMonitorString (Get-FmkSysField $mon @('ManufacturerName') -Missing @())
            $friendly = ConvertFrom-FmkMonitorString (Get-FmkSysField $mon @('UserFriendlyName') -Missing @())
            if ($friendly -eq '') { $friendly = 'Generic monitor' }
            $label = $friendly
            if ($mfr -ne '') { $label = "$mfr $friendly" }
            Add-FmkSysRow $s "Monitor $shownMon" $label
            $serial = ConvertFrom-FmkMonitorString (Get-FmkSysField $mon @('SerialNumberID') -Missing @())
            if ($serial -ne '' -and $serial -ne '0') {
                Add-FmkSysRow $s "Monitor $shownMon serial number" $serial -Sensitivity 'Private'
            }
        }
        if ($mons.Count -gt 6) { Add-FmkSysRow $s 'Monitors' ("Showing 6 of $($mons.Count).") }
    }
    else {
        $desk = Read-FmkCim 'Win32_DesktopMonitor'
        if ($desk -and $desk.Count -gt 0) {
            $shownDesk = 0
            foreach ($d in $desk) {
                if ($shownDesk -ge 6) { break }
                $shownDesk++
                Add-FmkSysRow $s "Monitor $shownDesk" (Get-FmkSysField $d @('Name'))
            }
            Add-FmkSysWarning $s 'Detailed monitor names unavailable; showing generic entries.'
        }
        else {
            Add-FmkSysWarning $s 'No monitors reported.'
            Add-FmkSysRow $s 'Monitors' 'Unavailable'
        }
    }
    $kbd = Read-FmkCim 'Win32_Keyboard'
    if ($kbd -and $kbd.Count -gt 0) {
        $shownK = 0
        foreach ($k in $kbd) {
            if ($shownK -ge 2) { break }
            $shownK++
            Add-FmkSysRow $s "Keyboard $shownK" (Get-FmkSysField $k @('Name'))
        }
    }
    $ptr = Read-FmkCim 'Win32_PointingDevice'
    if ($ptr -and $ptr.Count -gt 0) {
        $shownP = 0
        foreach ($p in $ptr) {
            if ($shownP -ge 2) { break }
            $shownP++
            Add-FmkSysRow $s "Pointing device $shownP" (Get-FmkSysField $p @('Name'))
        }
    }
    $cams = Read-FmkCim 'Win32_PnPEntity' -Filter "PNPClass='Image'"
    if ($cams -and $cams.Count -gt 0) {
        $shownC = 0
        foreach ($c in $cams) {
            if ($shownC -ge 4) { break }
            $shownC++
            Add-FmkSysRow $s "Camera $shownC" (Get-FmkSysField $c @('Name'))
        }
    }
    else {
        Add-FmkSysRow $s 'Cameras' 'None detected'
    }
    $usb = Read-FmkCim 'Win32_PnPEntity' -Filter "PNPClass='USB'"
    if ($usb -and $usb.Count -gt 0) {
        $shownU = 0
        foreach ($u in $usb) {
            if ($shownU -ge 8) { break }
            $shownU++
            Add-FmkSysRow $s "USB device $shownU" (Get-FmkSysField $u @('Name'))
        }
        if ($usb.Count -gt 8) { Add-FmkSysRow $s 'USB devices' ("Showing 8 of $($usb.Count). Generic HID devices are summarized, not listed individually.") }
    }
    else {
        Add-FmkSysRow $s 'USB devices' 'Unavailable'
        Add-FmkSysWarning $s 'USB device list unreadable.'
    }
    return $s
}

function Get-FmkSysRuntimeSection {
    param([bool]$IsAdmin)
    $s = New-FmkSysSection -Key 'Runtime' -Title 'Runtime and Virtualization'
    try {
        Add-FmkSysRow $s 'PowerShell version' ([string]$PSVersionTable.PSVersion)
        Add-FmkSysRow $s 'PowerShell edition' ([string]$PSVersionTable.PSEdition)
    }
    catch {
        Add-FmkSysRow $s 'PowerShell version' 'Unavailable'
        Add-FmkSysWarning $s 'PowerShell version table unreadable.'
    }
    try {
        if ([System.Environment]::Is64BitOperatingSystem) { Add-FmkSysRow $s 'OS architecture (process view)' '64-bit OS' }
        else { Add-FmkSysRow $s 'OS architecture (process view)' '32-bit OS' }
        if ([System.Environment]::Is64BitProcess) { Add-FmkSysRow $s 'FreeMixKit process' '64-bit' }
        else { Add-FmkSysRow $s 'FreeMixKit process' '32-bit' }
    }
    catch { Add-FmkSysWarning $s 'Process architecture unreadable.' }
    $dotnetOk = $false
    try {
        $dn = Get-Command dotnet -ErrorAction SilentlyContinue
        if ($dn -and ("$($dn.Source)" -notmatch 'WindowsApps')) { $dotnetOk = $true }
    }
    catch { $dotnetOk = $false }
    if ($dotnetOk) {
        try {
            $sdks = @(dotnet --list-sdks 2>$null)
            if ($sdks.Count -gt 0) {
                $show = @($sdks | Select-Object -First 8)
                foreach ($sdk in $show) { Add-FmkSysRow $s '.NET SDK' ([string]$sdk).Trim() }
                if ($sdks.Count -gt 8) { Add-FmkSysRow $s '.NET SDKs' ("Showing 8 of $($sdks.Count).") }
            }
            else { Add-FmkSysRow $s '.NET SDKs' 'None reported' }
        }
        catch { Add-FmkSysWarning $s '.NET SDK list unreadable.' }
        try {
            $rts = @(dotnet --list-runtimes 2>$null)
            if ($rts.Count -gt 0) {
                $showRt = @($rts | Select-Object -First 8)
                foreach ($rt in $showRt) { Add-FmkSysRow $s '.NET runtime' ([string]$rt).Trim() }
                if ($rts.Count -gt 8) { Add-FmkSysRow $s '.NET runtimes' ("Showing 8 of $($rts.Count).") }
            }
            else { Add-FmkSysRow $s '.NET runtimes' 'None reported' }
        }
        catch { Add-FmkSysWarning $s '.NET runtime list unreadable.' }
    }
    else {
        Add-FmkSysRow $s '.NET SDKs / runtimes' 'Unavailable (dotnet not installed; nothing was installed to check)'
    }
    try {
        $csq = Read-FmkCim 'Win32_ComputerSystem'
        $hyp = $null
        if ($csq -and $csq.Count -gt 0) {
            try { $hyp = [bool]$csq[0].HypervisorPresent } catch { $hyp = $null }
            $mm = (Get-FmkSysField $csq[0] @('Manufacturer') -Missing '') + ' ' + (Get-FmkSysField $csq[0] @('Model') -Missing '')
            if ($mm.Trim() -ne '') {
                if ($mm -match '(?i)virtual machine|vmware|virtualbox|qemu|xen|kvm|hyper-v|parallels|bhyve|Pacer') {
                    Add-FmkSysRow $s 'Virtual machine indicators' ("Likely virtualized (model string: $($mm.Trim()))")
                }
                else {
                    Add-FmkSysRow $s 'Virtual machine indicators' 'No virtual-machine indicators in system model'
                }
            }
            else { Add-FmkSysRow $s 'Virtual machine indicators' 'Unavailable' }
        }
        if ($null -eq $hyp) { Add-FmkSysRow $s 'Hypervisor present' 'Unavailable' }
        elseif ($hyp) { Add-FmkSysRow $s 'Hypervisor present' 'Yes' }
        else { Add-FmkSysRow $s 'Hypervisor present' 'No' }
    }
    catch { Add-FmkSysWarning $s 'Virtualization status unreadable.' }
    $wslOk = $false
    try {
        if (Get-Command wsl.exe -ErrorAction SilentlyContinue) { $wslOk = $true }
    }
    catch { $wslOk = $false }
    if ($wslOk) {
        try {
            $st = @(wsl.exe --status 2>$null)
            if ($st.Count -gt 0) {
                foreach ($line in @($st | Select-Object -First 6)) {
                    $clean = ConvertFrom-FmkWslLine $line
                    if ($clean -ne '') { Add-FmkSysRow $s 'WSL' $clean }
                }
            }
            else { Add-FmkSysRow $s 'WSL' 'No status reported' }
        }
        catch {
            Add-FmkSysRow $s 'WSL' 'Unavailable'
            Add-FmkSysWarning $s 'WSL status unreadable.'
        }
    }
    else {
        Add-FmkSysRow $s 'WSL' 'Not installed or unavailable'
    }
    return $s
}

function Get-FmkSystemReportData {
    <#
        One collection pass over every section. Each section is independent:
        a failing section degrades to a warning row instead of stopping the
        report. Runs in a background runspace from the UI; runs inline
        anywhere else. Nothing here needs administrator rights to attempt,
        and sections needing more access say so when denied.
    #>
    $isAdmin = $false
    try {
        $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
        $isAdmin = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    }
    catch { }

    $sections = New-Object System.Collections.ArrayList
    $collectors = @(
        @{ Key = 'Windows'; Title = 'Windows and Operating System'; Fn = ${function:Get-FmkSysWindowsSection} },
        @{ Key = 'CPU'; Title = 'Processor (CPU)'; Fn = ${function:Get-FmkSysCpuSection} },
        @{ Key = 'Memory'; Title = 'Memory (RAM)'; Fn = ${function:Get-FmkSysMemorySection} },
        @{ Key = 'GPU'; Title = 'Graphics (GPU)'; Fn = ${function:Get-FmkSysGpuSection} },
        @{ Key = 'Storage'; Title = 'Storage'; Fn = ${function:Get-FmkSysStorageSection} },
        @{ Key = 'Firmware'; Title = 'Motherboard and Firmware'; Fn = ${function:Get-FmkSysFirmwareSection} },
        @{ Key = 'Network'; Title = 'Network Adapters'; Fn = ${function:Get-FmkSysNetworkSection} },
        @{ Key = 'Battery'; Title = 'Battery and Power'; Fn = ${function:Get-FmkSysBatterySection} },
        @{ Key = 'AudioDisplay'; Title = 'Audio, Displays and Peripherals'; Fn = ${function:Get-FmkSysAudioDisplaySection} },
        @{ Key = 'Runtime'; Title = 'Runtime and Virtualization'; Fn = ${function:Get-FmkSysRuntimeSection} }
    )
    foreach ($c in $collectors) {
        try {
            [void]$sections.Add((& $c.Fn -IsAdmin $isAdmin))
        }
        catch {
            $fallback = New-FmkSysSection -Key $c.Key -Title $c.Title
            Add-FmkSysRow $fallback 'Section' 'Unavailable'
            Add-FmkSysWarning $fallback ("Collector failed: $($_.Exception.Message)")
            [void]$sections.Add($fallback)
        }
    }

    $byKey = @{}
    foreach ($sec in $sections) { $byKey[$sec.Key] = $sec }
    $overview = New-FmkSysSection -Key 'Overview' -Title 'System overview'
    Add-FmkSysRow $overview 'Operating system' (Find-FmkSysRow $byKey['Windows'] 'Product name')
    $rel = Find-FmkSysRow $byKey['Windows'] 'Release'
    $bld = Find-FmkSysRow $byKey['Windows'] 'Build'
    if ($rel -ne '' -and $bld -ne '') { Add-FmkSysRow $overview 'Release / build' "$rel (build $bld)" }
    Add-FmkSysRow $overview 'Processor' (Find-FmkSysRow $byKey['CPU'] 'Model')
    $cores = Find-FmkSysRow $byKey['CPU'] 'Physical cores'
    $threads = Find-FmkSysRow $byKey['CPU'] 'Logical processors'
    if ($cores -ne '' -and $threads -ne '') { Add-FmkSysRow $overview 'Cores / threads' "$cores cores, $threads threads" }
    $installed = Find-FmkSysRow $byKey['Memory'] 'Installed physical memory'
    $inuse = Find-FmkSysRow $byKey['Memory'] 'In use'
    if ($installed -ne '' -and $inuse -ne '') { Add-FmkSysRow $overview 'Memory' "$installed installed, $inuse in use" }
    elseif ($installed -ne '') { Add-FmkSysRow $overview 'Memory' $installed }
    Add-FmkSysRow $overview 'Graphics' (Find-FmkSysRow $byKey['GPU'] 'Name')
    $diskCount = 0
    try {
        foreach ($row in @($byKey['Storage'].Rows)) {
            if ([string]$row.Label -match '^Disk \d+$') { $diskCount++ }
        }
    }
    catch { }
    if ($diskCount -gt 0) { Add-FmkSysRow $overview 'Storage' "$diskCount physical disk(s) (see Storage section)" }

    $all = New-Object System.Collections.ArrayList
    [void]$all.Add($overview)
    foreach ($sec in $sections) { [void]$all.Add($sec) }

    return @{
        GeneratedAt = (Get-Date)
        IsAdmin     = $isAdmin
        Sections    = @($all)
    }
}

# ==============================================================================
# SYSTEM REPORT -- text and JSON output
# ==============================================================================

function Get-FmkSysDisplayValue {
    <#
        What a row shows. Untagged values always show. Identifying values
        (computer/user names) show on screen but are withheld from exports
        unless included. Private values (serials, MACs, IPs) hide everywhere
        unless an export explicitly includes them.
    #>
    param($Row, [bool]$IncludeSensitive = $false, [bool]$ForExport = $false)
    $sens = ''
    try { $sens = [string]$Row.Sensitivity } catch { $sens = '' }
    if ($sens -eq '' -or $sens -eq 'None') { return [string]$Row.Value }
    if ($IncludeSensitive) { return [string]$Row.Value }
    if ($ForExport) { return '[withheld]' }
    if ($sens -eq 'Identifying') { return [string]$Row.Value }
    return '[hidden]'
}

function Format-FmkSysTextReport {
    # ForExport selects the export wording for withheld values ('[withheld]');
    # the on-screen and clipboard form says '[hidden]' instead.
    param($Report, [bool]$IncludeSensitive = $false, [bool]$ForExport = $false)
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('FreeMixKit System Report')
    try { [void]$lines.Add("Report format version: 1 (FreeMixKit v$AppVersion)") } catch { }
    try {
        $when = ([datetime]$Report.GeneratedAt).ToString('yyyy-MM-dd HH:mm')
        [void]$lines.Add("Generated: $when")
    }
    catch { [void]$lines.Add('Generated: unknown') }
    $adminText = 'No'
    try { if ([bool]$Report.IsAdmin) { $adminText = 'Yes' } } catch { }
    [void]$lines.Add("Running as administrator: $adminText")
    if ($IncludeSensitive) { [void]$lines.Add('Sensitive identifiers: included') }
    else { [void]$lines.Add('Sensitive identifiers: withheld') }
    try {
        foreach ($sec in @($Report.Sections)) {
            [void]$lines.Add('')
            [void]$lines.Add("==== $($sec.Title) ====")
            foreach ($row in @($sec.Rows)) {
                [void]$lines.Add(("{0}: {1}" -f $row.Label, (Get-FmkSysDisplayValue $row -IncludeSensitive:$IncludeSensitive -ForExport:$ForExport)))
            }
            foreach ($warn in @($sec.Warnings)) {
                [void]$lines.Add("Note: $warn")
            }
        }
    }
    catch { [void]$lines.Add('(report body unreadable)') }
    return ($lines -join "`r`n")
}

function Write-FmkSysReportFile {
    <#
        Writes report text to a .txt file as UTF-8 WITH BOM. The BOM is the
        entire point: without it, BOM-less bytes are bare bytes, and any
        reader that assumes or sniffs UTF-16 decodes plain ASCII as CJK
        ("Free Mix Kit ..." becomes U+7246 U+6565 ..., i.e. Chinese-looking
        mojibake). The BOM makes the file self-describing for Notepad and
        every other Windows reader, while old and new PowerShell/.NET readers
        detect and strip it either way.
    #>
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Text
    )
    $utf8Bom = New-Object System.Text.UTF8Encoding($true)
    [System.IO.File]::WriteAllText($Path, $Text, $utf8Bom)
}

function ConvertTo-FmkSysJsonReport {
    <# Redacted plain-data copy of the report, ready for ConvertTo-Json. #>
    param($Report, [bool]$IncludeSensitive = $false)
    $secs = New-Object System.Collections.ArrayList
    try {
        foreach ($sec in @($Report.Sections)) {
            $rows = New-Object System.Collections.ArrayList
            foreach ($row in @($sec.Rows)) {
                [void]$rows.Add([ordered]@{
                        Label       = [string]$row.Label
                        Value       = (Get-FmkSysDisplayValue $row -IncludeSensitive:$IncludeSensitive -ForExport:$true)
                        Sensitivity = [string]$row.Sensitivity
                    })
            }
            [void]$secs.Add([ordered]@{
                    Key      = [string]$sec.Key
                    Title    = [string]$sec.Title
                    Rows     = @($rows)
                    Warnings = @($sec.Warnings | ForEach-Object { [string]$_ })
                })
        }
    }
    catch { }
    $stamp = ''
    try { $stamp = ([datetime]$Report.GeneratedAt).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') } catch { }
    $admin = $false
    try { $admin = [bool]$Report.IsAdmin } catch { }
    return [ordered]@{
        GeneratedAt       = $stamp
        IsAdmin           = $admin
        SensitiveIncluded = [bool]$IncludeSensitive
        Sections          = @($secs)
    }
}

# ==============================================================================
# 3b. UI THEME TOKENS
# ==============================================================================

# ----------------------------------------------------------------------------
# source: theme.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# UI THEME TOKENS
# ==============================================================================
# Palette keys here must match the percent-wrapped placeholders in
# src/xaml/ui.xaml. Every brush in that file is declared as Color="%%FmkBg%%" and
# so on; Get-FmkThemedXaml substitutes the hex values into the XAML text before it
# is handed to XamlReader.Parse, which is what makes this the single place the
# colors live.
#
# Why the substitution happens before Parse rather than as a ResourceDictionary
# write afterwards: see the comment above the palette in ui.xaml. Short version
# -- writing a brush under a key a live {DynamicResource} points at throws, and
# the brushes are frozen once resolved, so they cannot be recolored in place
# either. There is no safe way to swap the palette on a window that is already up.
#
# Values are taken from WinUtil's own theme table,
#   config/themes.json   (github.com/ChrisTitusTech/winutil)
# and each key names the WinUtil key it was copied from. Keys marked "derived"
# have no upstream equivalent: WinUtil paints its window and its panels one flat
# colour and separates them with borders, which does not carry over to a
# card-based layout, so those sit between the real values.
#
# Metrics come from the same file and live in src/xaml/ui.xaml: base font Arial
# 12, header Consolas 16, corner radius 2 on buttons (WinUtil is nearly square),
# 5 on cards and text boxes, button height 25, header row 50.

$FmkThemes = @{
    Dark  = [ordered]@{
        # --- surfaces (WinUtil config/themes.json, Dark) ----------------------
        FmkBg          = '#232629'   # MainBackgroundColor
        FmkBgAlt       = '#1D2024'   # sidebar/header panel -- derived, WinUtil
        #                              paints these the same as the background
        FmkCard        = '#2A2E33'   # card surface -- between MainBackgroundColor
        #                              and AppInstallHighlightedColor
        FmkCardHover   = '#3C3C3C'   # AppInstallHighlightedColor
        FmkBorder      = '#2F373D'   # BorderColor
        # --- text ------------------------------------------------------------
        FmkFg          = '#F7F7F7'   # MainForegroundColor
        FmkFgMuted     = '#A9B1B9'   # derived
        FmkLabel       = '#5BDCFF'   # LabelboxForegroundColor
        # --- actions ---------------------------------------------------------
        FmkAccent      = '#1E3747'   # ButtonBackgroundColor
        FmkAccentHover = '#3B4252'   # ButtonBackgroundMouseoverColor
        FmkSelect      = '#5E81AC'   # ButtonBackgroundSelectedColor
        FmkAccentFg    = '#F7F7F7'   # ButtonForegroundColor
        # --- log pane --------------------------------------------------------
        FmkLogBg       = '#1B1E21'   # derived
        # --- busy overlay ----------------------------------------------------
        FmkOverlay     = '#B31D2024'   # BgAlt at ~70% opacity; dims the body
        #                              while an exclusive task runs
        # --- risk ------------------------------------------------------------
        FmkRiskLow     = '#6EFF72'   # ProgressBarForegroundColor
        FmkRiskMed     = '#FFC83D'   # ProgressBarWarningColor
        FmkRiskHigh    = '#FF6B6B'   # ProgressBarErrorColor
    }
    Light = [ordered]@{
        FmkBg          = '#F7F7F7'   # MainBackgroundColor
        FmkBgAlt       = '#EFEFEF'
        FmkCard        = '#FFFFFF'
        FmkCardHover   = '#CFCFCF'   # AppInstallHighlightedColor
        FmkBorder      = '#C4C8CC'   # BorderColor is #232629 at 0.2 opacity;
        #                              pre-blended so it stays one flat token
        FmkFg          = '#232629'   # MainForegroundColor
        FmkFgMuted     = '#5A5F66'
        FmkLabel       = '#1F6F8B'   # LabelboxForegroundColor is #5BDCFF, which
        #                              is unreadable on white; darkened instead
        FmkAccent      = '#F5F5F5'   # ButtonBackgroundColor
        FmkAccentHover = '#C2C2C2'   # ButtonBackgroundMouseoverColor
        FmkSelect      = '#D8DDE2'
        FmkAccentFg    = '#232629'   # ButtonForegroundColor
        FmkLogBg       = '#FFFFFF'
        FmkOverlay     = '#B3EFEFEF'   # BgAlt at ~70% opacity; dims the body
        FmkRiskLow     = '#1A7F37'
        FmkRiskMed     = '#B36A00'   # ProgressBarWarningColor
        FmkRiskHigh    = '#D13438'   # ProgressBarErrorColor
    }
}

function Get-FmkThemedXaml {
    <#
        Returns the window XAML with every percent-wrapped placeholder replaced
        by the hex value for the requested theme. Call this immediately before
        XamlReader.Parse; the window is then born with its final colors and
        nothing is ever written into Window.Resources at runtime.

        Both runtime approaches were tried against this window and both fail:

          * Writing a brush under a key that a live {DynamicResource} points at
            makes WPF synchronously re-resolve that reference. The re-resolution
            throws
                '#FF1B1B1F' is not a valid value for property 'Background'
            for the Window's own Background/Foreground. Writing a key nothing
            references succeeds, so it is the invalidation that breaks, not the
            value being written.
          * Mutating the existing brush's Color instead does not dodge it: a
            brush is frozen as soon as a {DynamicResource} resolves it onto a
            live element, and a frozen brush's Color is read-only.

        A missing token is a build-time mistake, so this throws rather than
        letting XamlReader report it as a syntax error somewhere unrelated.
    #>
    param(
        [Parameter(Mandatory)][string]$Xaml,
        [Parameter(Mandatory)][ValidateSet('Dark', 'Light')][string]$Theme
    )

    $palette = $FmkThemes[$Theme]
    $result = $Xaml

    foreach ($key in $palette.Keys) {
        $result = $result.Replace("%%$key%%", $palette[$key])
    }

    $leftover = @([regex]::Matches($result, '%%([A-Za-z0-9_]+)%%') |
            ForEach-Object { $_.Groups[1].Value } |
            Select-Object -Unique)

    if ($leftover.Count -gt 0) {
        throw "ui.xaml uses palette token(s) the '$Theme' theme does not define: $($leftover -join ', ')"
    }

    return $result
}

function Get-FmkBrush {
    <# Convenience lookup for colors the registry supplies at runtime (risk badges). #>
    param([Parameter(Mandatory)][string]$Key)
    $window = $null
    if ($global:sync) { $window = $global:sync.FmkWindow }
    if ($window -and $window.Resources.Contains($Key)) {
        return $window.Resources[$Key]
    }
    return [System.Windows.Media.Brushes]::Gray
}

# ==============================================================================
# 3c. VENDORED ASSETS
# ==============================================================================
# Brand marks for the Software grid, as SVG path data. Vendored rather than
# fetched so the built script stays a single self-contained file that draws its
# icons with no network access and no image files.

# ----------------------------------------------------------------------------
# source: icon.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# APPLICATION WINDOW ICON
# ==============================================================================
# The project logo (blue panes-and-gear mark from freemixkit_icon.ico) as
# base64 ICO bytes, vendored so the built script stays self-contained: the
# window/taskbar icon works even when no sibling .ico file exists, which is
# the case for the `irm | iex` launch path that has no local directory.
#
# Same artwork as the root freemixkit_icon.ico, multi-size 16..256
# PNG-compressed entries with alpha preserved. Regenerate from the root
# .ico rather than editing by hand.
#
# This scalar intentionally does not match the $FmkLogos entry shape that
