# ------------------------------------------------------------------------------
# Bibata Cursor
# ------------------------------------------------------------------------------
$Modules["Dev_BibataCursor"] = {
    Write-Log "Installing Bibata Cursor..." "Info"
    try {
        $zip = "$DataDownloads\Bibata.zip"; $dest = "$DataDownloads\Bibata"
        Invoke-WebRequest "https://github.com/ful1e5/Bibata_Cursor/releases/download/v2.0.7/Bibata-Modern-Classic-Windows.zip" -OutFile $zip
        Expand-Archive $zip -Dest $dest -Force
        $regularInf = Get-ChildItem "$dest" -Recurse -Filter "*.inf" | Where-Object { $_.FullName -match "Regular" } | Select-Object -First 1
        if (-not $regularInf) { $regularInf = Get-ChildItem "$dest" -Recurse -Filter "*.inf" | Select-Object -First 1 }
        if ($regularInf) { Start-Process "RUNDLL32.EXE" -Arg "SETUPAPI.DLL,InstallHinfSection DefaultInstall 128 $($regularInf.FullName)" -Wait }
    }
    catch { Write-Log "Cursor Failed" "Error" }

    Write-Log "Bibata Cursor done." "Success"
}

# ------------------------------------------------------------------------------
# Game runtimes
# ------------------------------------------------------------------------------
$Modules["Dev_GameRuntimes"] = {
    # DirectX and XNA were part of the old bundle but are not development tools,
    # so they get their own entry instead of being folded into one of the
    # component modules.
    Write-Log "Installing game runtimes (DirectX, XNA)..." "Info"
    Ensure-WingetInstalled

    foreach ($gid in @("Microsoft.DirectX", "Microsoft.XNARedist")) {
        try {
            Write-Log "Installing game runtime: $gid" "Info"
            Install-WingetPackage -Id $gid
        }
        catch {
            Write-Log "Failed game runtime '$gid': $($_.Exception.Message)" "Error"
        }
    }

    Write-Log "Game runtimes done." "Success"
}

# ----------------------------------------------------------------------------
# source: maintenance.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# MODULE: Cleanup & repair
# ==============================================================================

$Modules["CleanSystem"] = {
    Write-Log "Cleaning..."
    Remove-Item "$env:TEMP\*" -Recurse -Force -EA SilentlyContinue
    Remove-Item "$DataTemp\*" -Recurse -Force -EA SilentlyContinue
    Remove-Item "C:\Windows\Temp\*" -Recurse -Force -EA SilentlyContinue
    Remove-Item "C:\Windows\Prefetch\*" -Recurse -Force -EA SilentlyContinue
    Clear-DnsClientCache
    Write-Log "Cleaned." "Success"
}

$Modules["SystemRepair"] = {
    Invoke-ExternalCommand -FilePath "sfc.exe" -Arguments @("/scannow") | Out-Null
    Invoke-ExternalCommand -FilePath "DISM.exe" -Arguments @("/Online", "/Cleanup-Image", "/RestoreHealth") | Out-Null
    Write-Log "Done." "Success"
}

$Modules["MalwareScan"] = {
    $mrt = "$env:SystemRoot\System32\MRT.exe"
    if (!(Test-Path $mrt)) {
        Invoke-WebRequest "https://go.microsoft.com/fwlink/?LinkID=212732" -OutFile "$DataDownloads\MRT.exe"
        $mrt = "$DataDownloads\MRT.exe"
    }
    Start-Process $mrt -Wait

    $kvrt = Join-Path $DataDownloads "kvrt.exe"
    Invoke-WebRequest "https://devbuilds.s.kaspersky-labs.com/kvrt/latest/full/kvrt.exe" -OutFile $kvrt
    Start-Process $kvrt -Wait
}

$Modules["SystemReport"] = {
    # Full hardware and Windows report via the shared collection service.
    # Sensitive identifiers stay withheld. Desktop path is the long-standing
    # behavior: Run generates the file and opens it, nothing renders on screen.
    Write-Log "Collecting full system report..." "Info"
    $report = Get-FmkSystemReportData
    $text = Format-FmkSysTextReport -Report $report -IncludeSensitive:$false -ForExport:$true
    $f = "$env:USERPROFILE\Desktop\SysReport.txt"
    Write-FmkSysReportFile -Path $f -Text $text
    Write-Log "System report saved (sensitive identifiers withheld): $f" "Success"
    Invoke-Item $f
}

# ----------------------------------------------------------------------------
# source: software.ps1
# ----------------------------------------------------------------------------
# ==============================================================================
# MODULES: Software catalog (browsers, media, gaming, developer apps)
# ==============================================================================
# One module per application. WinGet is the default source: every ID below was
# verified with `winget search --id <Id> --exact` (and `winget show` for the
# publisher on the less obvious ones) before it was written here. Do not invent
# IDs -- re-run the search if one stops resolving.
#
# When WinGet fails, the module opens the vendor's official download page and
# fails loudly rather than falling back to an unrelated package.

function Install-FmkCatalogApp {
    <#
        Installs one catalog application via WinGet, opening the official
        download page when WinGet cannot complete the install.

        Kept as one helper rather than repeated per module so the failure
        behaviour cannot drift: a WinGet failure is logged with the package ID,
        the official page is opened for a manual install, and the module still
        reports Failed with an actionable message instead of a false Success.
    #>
    param(
        [Parameter(Mandatory)][string]$Label,
        [Parameter(Mandatory)][string]$WingetId,
        [Parameter(Mandatory)][string]$FallbackUrl
    )

    Ensure-WingetInstalled

    try {
        Install-WingetPackage -Id $WingetId
    }
    catch {
        Write-Log "WinGet install failed for $Label ($WingetId): $($_.Exception.Message)" "Warn"
        Write-Log "Opening official download page instead: $FallbackUrl" "Info"
        Start-Process $FallbackUrl
        throw "WinGet install failed for $Label; opened the official download page ($FallbackUrl)."
    }

    Write-Log "$Label installed via WinGet ($WingetId)." "Success"
}

